import time


def _greedy(inp):
    evs = sorted(inp["events"], key=lambda e: e["i"])
    st = {}
    order = []
    out = {}
    for e in evs:
        ty = e["type"]
        if ty == "open":
            st[e["sid"]] = {"m": "active", "node": e["node"], "off": 0, "dur": 0}
            order.append(e["sid"])
            continue
        if ty == "crash":
            for s, v in st.items():
                if v["m"] == "active" and v["node"] == e["node"]:
                    v["m"] = "down"; v["off"] = v["dur"]
            continue
        sid = e["sid"]
        if sid is None or sid not in st:
            best = None; bc = None
            for s, v in st.items():
                c = 5
                if v["node"] == e["node"] and v["m"] == "active":
                    c = 1
                    if e["off"] is not None and e["off"] == v["off"]:
                        c = 0
                elif ty == "recover" and v["m"] == "down":
                    c = 0 if e["off"] == v["dur"] else 2
                if bc is None or c < bc:
                    bc = c; best = s
            sid = best if best is not None else (order[0] if order else "")
            if e["sid"] is None:
                out[str(e["i"])] = sid
        v = st.get(sid)
        if v is None:
            continue
        o = e["off"]
        if ty == "write" and o is not None:
            v["m"] = "active"; v["node"] = e["node"]; v["off"] = o + (e["len"] or 0)
        elif ty == "checkpoint" and o is not None:
            v["off"] = o; v["dur"] = max(v["dur"], o)
        elif ty == "commit" and o is not None:
            v["m"] = "committed"; v["off"] = o; v["dur"] = o
        elif ty == "abort":
            v["m"] = "aborted"
        elif ty == "recover" and o is not None:
            v["m"] = "active"; v["node"] = e["node"]; v["off"] = o; v["dur"] = o
    for e in evs:
        if e["type"] != "crash" and e["sid"] is None and str(e["i"]) not in out:
            out[str(e["i"])] = order[0] if order else ""
    sess = {s: {"status": v["m"], "durable": int(v["dur"])} for s, v in st.items()}
    return {"assignments": out, "sessions": sess}


def _beam(inp, t0):
    evs = sorted(inp["events"], key=lambda e: e["i"])
    sids = []
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    sidx = {s: k for k, s in enumerate(sids)}
    NS = len(sids)
    n = len(evs)

    C_GAP = 3.0
    C_REO = 2.5
    C_MREC = 4.0
    C_MCK = 3.0
    C_NOCR = 4.0
    C_DUP = 1.5
    C_FORCE = 12.0
    C_FILL = 1.0
    C_BAD = 5.0
    C_ABORT = 0.3
    W = 12

    def reo(gap):
        return C_REO + 0.4 * max(0, gap - 4) + (100.0 if gap > 3 * W else 0.0)

    keymap = {}
    dupcands = [[] for _ in range(n)]
    lastcopy = {}
    for k, e in enumerate(evs):
        if e["type"] in ("open", "crash"):
            continue
        key = (e["node"], e["type"], e["off"], e["len"])
        prev = keymap.get(key)
        if prev:
            dupcands[k] = prev[-3:]
            for p in prev[-3:]:
                lastcopy[p] = k
            prev.append(k)
        else:
            keymap[key] = [k]

    # session state: (mode,node,off,dur,pre,ct,lt,pend,gaps)
    # mode 0 unopened, 1 active, 2 down, 3 committed, 4 aborted
    def addgap(gaps, a, b, t):
        if b <= a:
            return gaps
        return (gaps + ((a, b, t),))[-3:]

    def fill(gaps, o, L, t):
        for gi in range(len(gaps)):
            a, b, gt = gaps[gi]
            if a <= o and o + L <= b:
                late = max(0, t - gt - W)
                rest = list(gaps[:gi]) + list(gaps[gi + 1:])
                if o == a and o + L == b:
                    return (-C_GAP + C_FILL + 0.3 * late, tuple(rest))
                if o == a:
                    rest.append((o + L, b, gt))
                    return (C_FILL + 0.3 * late, tuple(rest))
                rest.append((a, o, gt))
                return (C_FILL + 1.0 + 0.3 * late, tuple(rest))
        return None

    def trans(e, st):
        mode, node, off, dur, pre, ct, lt, pend, gaps = st
        ty = e["type"]; N = e["node"]; o = e["off"]; t = e["t"]
        L = e["len"] or 0
        res = []
        if mode == 0:
            return res
        if ty in ("write", "checkpoint", "commit"):
            if o is None:
                return res
            if mode == 1:
                if node == N:
                    if o >= off:
                        c = 0.0 if o == off else C_GAP
                        ng = addgap(gaps, off, o, t) if o > off else gaps
                        if ty == "write":
                            res.append((c, (1, N, o + L, dur, pre, ct, t, pend, ng)))
                        elif ty == "checkpoint":
                            res.append((c, (1, N, o, o, pre, ct, t, pend, ng)))
                        else:
                            res.append((c, (3, N, o, o, pre, ct, t, pend, ng)))
                    else:
                        if ty == "write":
                            f = fill(gaps, o, L, t)
                            if f is not None:
                                res.append((f[0], (1, N, off, dur, pre, ct, lt, pend, f[1])))
                            else:
                                res.append((C_BAD + reo(t - lt), st))
                        elif ty == "checkpoint" and o >= dur:
                            res.append((reo(t - lt), (1, N, off, o, pre, ct, lt, pend, gaps)))
            elif mode == 2:
                g = t - ct
                if node == N and o == pre:
                    if ty == "write":
                        res.append((reo(g), (2, node, off, dur, pre + L, ct, lt, pend, gaps)))
                        res.append((C_NOCR, (1, N, o + L, dur, pre, ct, t, pend, gaps)))
                    elif ty == "checkpoint":
                        res.append((reo(g), (2, node, o, o, pre, ct, lt, pend, gaps)))
                        res.append((C_NOCR, (1, N, o, o, pre, ct, t, pend, gaps)))
                    else:
                        res.append((reo(g) + 1.0, (3, N, o, o, pre, ct, t, pend, gaps)))
                        res.append((C_NOCR, (3, N, o, o, pre, ct, t, pend, gaps)))
                elif node == N and ty == "write" and o < pre:
                    f = fill(gaps, o, L, t)
                    if f is not None:
                        res.append((f[0], (2, node, off, dur, pre, ct, lt, pend, f[1])))
                elif node == N and ty == "checkpoint" and dur <= o < pre and g <= 3 * W:
                    res.append((reo(g) + 0.5, (2, node, o, o, pre, ct, lt, pend, gaps)))
                if o >= dur:
                    c = C_MREC + (0.0 if o == dur else C_GAP)
                    ng = addgap(gaps, dur, o, t) if o > dur else gaps
                    if ty == "write":
                        res.append((c, (1, N, o + L, dur, pre, ct, t, pend, ng)))
                    elif ty == "checkpoint":
                        res.append((c + 0.5, (1, N, o, o, pre, ct, t, pend, ng)))
                    else:
                        res.append((c + 0.5, (3, N, o, o, pre, ct, t, pend, ng)))
            else:
                if node == N:
                    if mode == 4 and o == pre:
                        if ty == "write":
                            res.append((reo(t - lt), (4, node, off, dur, pre + L, ct, lt, pend, gaps)))
                        elif ty == "checkpoint":
                            res.append((reo(t - lt), (4, node, o, o, pre, ct, lt, pend, gaps)))
                    elif ty == "write":
                        f = fill(gaps, o, L, t)
                        if f is not None:
                            res.append((f[0], (mode, node, off, dur, pre, ct, lt, pend, f[1])))
                    elif ty == "checkpoint" and mode == 3 and o <= off and t - lt <= 3 * W:
                        res.append((reo(t - lt), st))
                    elif ty == "checkpoint" and mode == 4 and dur <= o < pre and t - lt <= 3 * W:
                        res.append((reo(t - lt) + 0.5, (4, node, o, o, pre, ct, lt, pend, gaps)))
        elif ty == "abort":
            if mode == 1 and node == N:
                res.append((C_ABORT + 0.003 * min(max(t - lt, 0), 300),
                            (4, N, dur, dur, off, ct, t, pend, gaps)))
            elif mode == 2:
                if node == N:
                    res.append((reo(t - ct) + 0.5, (4, N, dur, dur, pre, ct, t, pend, gaps)))
                res.append((C_MREC + 1.0, (4, N, dur, dur, dur, ct, t, pend, gaps)))
        elif ty == "recover":
            if o is None:
                return res
            if mode == 2:
                if o == dur:
                    res.append((0.0, (1, N, o, o, pre, ct, t, pend, ())))
                elif dur < o <= pre:
                    res.append((C_MCK, (1, N, o, o, pre, ct, t, pend, ())))
                elif o > dur:
                    res.append((C_MCK + 3.0, (1, N, o, o, pre, ct, t, pend, ())))
            elif mode == 1 and o == dur:
                res.append((C_REO + 1.5, (1, N, o, o, off, ct, t, node, ())))
        return res

    def forced(e, st):
        mode, node, off, dur, pre, ct, lt, pend, gaps = st
        ty = e["type"]; N = e["node"]; o = e["off"]; t = e["t"]; L = e["len"] or 0
        if ty == "write" and o is not None:
            return (1, N, o + L, dur, pre, ct, t, pend, ())
        if ty in ("checkpoint", "recover") and o is not None:
            return (1, N, o, o, pre, ct, t, pend, ())
        if ty == "commit" and o is not None:
            return (3, N, o, o, pre, ct, t, pend, ())
        if ty == "abort":
            return (4, N, dur, dur, off, ct, t, pend, ())
        return st

    init = tuple((0, None, 0, 0, 0, -10 ** 9, 0, None, ()) for _ in range(NS))
    beam = [(0.0, init, {}, None)]
    BW = 60 if n <= 200 else (40 if n <= 400 else 30)
    budget = 0.7

    for k, e in enumerate(evs):
        ty = e["type"]
        if time.process_time() - t0 > budget:
            BW = 3
        newb = {}

        def push(cost, sess, dmap, chain):
            dkey = tuple(sorted((a, b) for a, b in dmap.items() if lastcopy.get(a, -1) > k))
            key = (sess, dkey)
            old = newb.get(key)
            if old is None or cost < old[0]:
                newb[key] = (cost, sess, dmap, chain)

        if ty == "crash":
            N = e["node"]
            for cost, sess, dmap, chain in beam:
                ns = list(sess)
                for j, st in enumerate(sess):
                    if st[0] == 1 and st[1] == N:
                        if st[7] == N:
                            ns[j] = st[:7] + (None, st[8])
                        else:
                            ns[j] = (2, N, st[3], st[3], st[2], e["t"], st[6], None, st[8])
                push(cost, tuple(ns), dmap, chain)
        elif ty == "open":
            j = sidx[e["sid"]]
            for cost, sess, dmap, chain in beam:
                st = sess[j]
                ns = list(sess)
                ns[j] = (1, e["node"], 0, 0, 0, -10 ** 9, e["t"], None, ())
                push(cost + (0.0 if st[0] == 0 else C_FORCE), tuple(ns), dmap, chain)
        else:
            known = e["sid"]
            cands = [sidx[known]] if known is not None else list(range(NS))
            isorig = k in lastcopy
            for cost, sess, dmap, chain in beam:
                got = False
                for p in dupcands[k]:
                    ps = dmap.get(p)
                    if ps is None:
                        pk = evs[p]["sid"]
                        if pk is None:
                            continue
                        ps = sidx[pk]
                    if known is not None and sidx[known] != ps:
                        continue
                    nd = dmap
                    if isorig:
                        nd = dict(dmap); nd[k] = ps
                    push(cost + C_DUP + 0.001 * (k - p), sess, nd, (k, ps, chain))
                    got = True
                for j in cands:
                    for c, s2 in trans(e, sess[j]):
                        ns = list(sess); ns[j] = s2
                        nd = dmap
                        if isorig:
                            nd = dict(dmap); nd[k] = j
                        push(cost + c, tuple(ns), nd, (k, j, chain))
                        got = True
                if not got:
                    if known is not None:
                        j = sidx[known]
                    else:
                        j = None
                        for jj in range(NS):
                            if sess[jj][0] in (1, 2) and sess[jj][1] == e["node"]:
                                j = jj; break
                        if j is None:
                            for jj in range(NS):
                                if sess[jj][0] != 0:
                                    j = jj; break
                        if j is None:
                            j = 0
                    ns = list(sess)
                    if NS and sess[j][0] != 0:
                        ns[j] = forced(e, sess[j])
                    nd = dmap
                    if isorig:
                        nd = dict(dmap); nd[k] = j
                    push(cost + C_FORCE, tuple(ns), nd, (k, j, chain))
        vals = sorted(newb.values(), key=lambda h: h[0])
        beam = vals[:BW]

    best = beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        kk, j, ch = ch
        assign[kk] = sids[j]
    out_assign = {}
    for k, e in enumerate(evs):
        if e["type"] != "crash" and e["sid"] is None:
            out_assign[str(e["i"])] = assign.get(k, sids[0] if sids else "")
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    sessions = {}
    for j, s in enumerate(sids):
        st = best[1][j]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    return {"assignments": out_assign, "sessions": sessions}


def solve(state, params):
    t0 = time.process_time()
    inp = state["input"]
    try:
        out = _beam(inp, t0)
    except Exception:
        out = _greedy(inp)
    state["output"] = out
    return state

import time


def solve(state, params):
    try:
        return solve_main(state, params)
    except Exception:
        return fallback(state, params)


def fallback(state, params):
    events = state.get("input", {}).get("events", [])
    sids = []
    first_on = {}
    for e in events:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
            first_on.setdefault(e.get("node"), e["sid"])
    a = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            a[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    state["output"] = {"assignments": a,
                       "sessions": {s: {"status": "active", "durable": 0} for s in sids}}
    return state


def solve_main(state, params):
    t0 = time.process_time()
    inp = state["input"]
    events = list(inp.get("events", []))
    sids = []
    for e in events:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(events)
    C_GAP = 2.5; C_FILL = -1.5; C_LATE = 1.5; C_REORD = 1.5; C_MISSREC = 2.5
    C_DUP = 1.0; C_BAD = 8.0; C_FUT = 4.0

    keyid = {}
    ekey = []
    for e in events:
        k = (e.get("node"), e.get("type"), e.get("off"), e.get("len"))
        if k not in keyid:
            keyid[k] = len(keyid)
        ekey.append(keyid[k])
    firstpos = {}
    for p, k in enumerate(ekey):
        if k not in firstpos:
            firstpos[k] = p
    futvis = [[] for _ in range(S)]
    for p, e in enumerate(events):
        s = e.get("sid")
        if s is not None and e.get("type") not in ("open", "crash"):
            if firstpos[ekey[p]] == p:
                futvis[sidx[s]].append(p)
    lastnd = [max(v) if v else -1 for v in futvis]

    def active_opts(st, typ, off, ln):
        status, node, fr, dur, holes = st
        res = []
        if typ == "write":
            if off is None or ln is None:
                res.append((1.0, st))
                return res
            if off == fr:
                res.append((0.0, (1, node, off + ln, dur, holes)))
            elif off > fr:
                res.append((C_GAP, (1, node, off + ln, dur, (holes + ((fr, off),))[-4:])))
            else:
                done = False
                for hi, (a, b) in enumerate(holes):
                    if a <= off and off + ln <= b:
                        nh = list(holes[:hi]) + list(holes[hi + 1:])
                        if a < off:
                            nh.append((a, off))
                        if off + ln < b:
                            nh.append((off + ln, b))
                        c = C_FILL if a == off else C_FILL + 1.0
                        res.append((c, (1, node, fr, dur, tuple(nh))))
                        done = True
                        break
                if not done and off >= dur:
                    res.append((C_BAD * 0.5, st))
        elif typ == "checkpoint":
            if off is None:
                res.append((0.5, (1, node, fr, fr, holes)))
                return res
            if off == fr:
                res.append((0.0, (1, node, fr, off, holes)))
            elif off > fr:
                res.append((C_GAP, (1, node, off, off, holes)))
            elif off >= dur:
                res.append((C_REORD, (1, node, fr, off, holes)))
            else:
                res.append((C_BAD, st))
        elif typ == "commit":
            if off is None:
                res.append((0.5, (3, node, fr, fr, ())))
                return res
            if off == fr:
                res.append((0.0, (3, node, off, off, ())))
            elif off > fr:
                res.append((C_GAP, (3, node, off, off, ())))
            elif off >= dur:
                res.append((C_REORD + 1.0, (3, node, off, off, ())))
            else:
                res.append((C_BAD, (3, node, off, off, ())))
        elif typ == "abort":
            res.append((0.0, (4, node, fr, dur, ())))
        return res

    def opts(st, e):
        status, node, fr, dur, holes = st
        typ = e.get("type"); en = e.get("node"); off = e.get("off"); ln = e.get("len")
        res = []
        if status == 0:
            return res
        if status in (3, 4):
            if typ == "write" and off is not None and ln is not None:
                if status == 3 and off + ln <= dur:
                    res.append((C_LATE, st))
                elif status == 4 and en == node and off >= dur:
                    res.append((C_LATE + 1.0, st))
            elif typ == "checkpoint" and off is not None:
                if status == 3 and off <= dur:
                    res.append((C_LATE, st))
                elif status == 4 and en == node:
                    res.append((C_LATE + 1.0, st))
            return res
        if status == 2:
            if en == node:
                if typ == "write" and off is not None and ln is not None:
                    if off == fr:
                        res.append((C_LATE, (2, node, off + ln, dur, holes)))
                elif typ == "checkpoint" and off is not None:
                    if dur <= off <= fr:
                        res.append((C_LATE, (2, node, fr, off, holes)))
                elif typ == "commit" and off is not None:
                    if off >= dur:
                        res.append((C_LATE + 0.5, (3, node, off, off, ())))
                elif typ == "abort":
                    res.append((C_LATE + 0.5, (4, node, fr, dur, ())))
            if typ == "recover":
                if off is None:
                    res.append((0.5, (1, en, dur, dur, ())))
                elif off == dur:
                    res.append((0.0, (1, en, off, off, ())))
                elif off > dur:
                    res.append((C_GAP, (1, en, off, off, ())))
                else:
                    res.append((C_BAD, (1, en, off, off, ())))
                return res
            st2 = (1, en, dur, dur, ())
            for c, ns in active_opts(st2, typ, off, ln):
                res.append((c + C_MISSREC, ns))
            return res
        if typ == "recover":
            if off is not None and en == node and dur <= off <= fr:
                res.append((C_LATE + 1.0, st))
            return res
        if en != node:
            return res
        return active_opts(st, typ, off, ln)

    init_sess = tuple((0, None, 0, 0, ()) for _ in range(S))
    init_keys = tuple(frozenset() for _ in range(S))
    beam = [(0.0, init_sess, init_keys, None)]
    W = 32 if n * max(S, 1) <= 4000 else 16
    for p, e in enumerate(events):
        el = time.process_time() - t0
        if el > 0.7:
            W = 2
        elif el > 0.45:
            W = min(W, 8)
        typ = e.get("type")
        if typ == "crash":
            nb = []
            for cost, ss, ks, h in beam:
                l = list(ss)
                ch = False
                for k, st in enumerate(l):
                    if st[0] == 1 and st[1] == e.get("node"):
                        l[k] = (2, st[1], st[2], st[3], st[4])
                        ch = True
                nb.append((cost, tuple(l) if ch else ss, ks, h))
            beam = nb
            continue
        sid = e.get("sid")
        if typ == "open" and sid is not None:
            k = sidx[sid]
            nb = []
            for cost, ss, ks, h in beam:
                l = list(ss)
                if l[k][0] == 0:
                    l[k] = (1, e.get("node"), 0, 0, ())
                nb.append((cost, tuple(l), ks, h))
            beam = nb
            continue
        cands = [sidx[sid]] if sid is not None else range(S)
        kid = ekey[p]
        cand_map = {}
        for cost, ss, ks, h in beam:
            got = False
            for si in cands:
                st = ss[si]
                if st[0] == 0:
                    continue
                o = opts(st, e)
                if kid in ks[si] and firstpos[kid] < p:
                    o = o + [(C_DUP, st)]
                fut = C_FUT if (typ in ("commit", "abort") and lastnd[si] > p + 2) else 0.0
                for c, ns in o:
                    if ns[0] >= 3 and st[0] < 3:
                        c += fut
                    nc = cost + c
                    l = list(ss); l[si] = ns; tl = tuple(l)
                    got = True
                    if tl in cand_map and cand_map[tl][0] <= nc:
                        continue
                    if ns is st:
                        nks = ks
                    else:
                        lk = list(ks); lk[si] = ks[si] | {kid}; nks = tuple(lk)
                    cand_map[tl] = (nc, tl, nks, (p, si, h))
            if not got:
                fs = None
                if sid is not None:
                    fs = sidx[sid]
                else:
                    for si in range(S):
                        if ss[si][0] != 0 and ss[si][1] == e.get("node"):
                            fs = si
                            break
                    if fs is None:
                        for si in range(S):
                            if ss[si][0] != 0:
                                fs = si
                                break
                if fs is None:
                    fs = 0
                nc = cost + 20.0
                if ss not in cand_map or cand_map[ss][0] > nc:
                    cand_map[ss] = (nc, ss, ks, (p, fs, h))
        if cand_map:
            beam = sorted(cand_map.values(), key=lambda x: x[0])[:W]
    best = beam[0]
    assign = {}
    h = best[3]
    while h is not None:
        p, si, h = h
        assign[p] = sids[si] if S else ""
    out_a = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            out_a[str(e.get("i", p))] = assign.get(p, sids[0] if sids else "")
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_s = {}
    for k, s in enumerate(sids):
        st = best[1][k]
        out_s[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": out_s}
    return state

import time


def _options(st, ev, k):
    PRE, ACT, DOWN, COM, ABO = 0, 1, 2, 3, 4
    status, node, cur, dur, lost = st
    typ = ev["type"]
    en = ev["node"]
    off = ev["off"]
    res = []
    if status == PRE:
        return res
    if typ in ("write", "checkpoint", "commit", "recover") and off is None:
        off = cur
    if typ == "write":
        ln = ev["len"] or 0
        end = off + ln
        if status == ACT:
            if node == en:
                if off == cur:
                    res.append((0.0, (ACT, node, end, dur, -1)))
                elif off > cur:
                    res.append((3.0, (ACT, node, end, dur, -1)))
                else:
                    res.append((1.5 if end <= cur else 1.5 + 1.0, None))
            else:
                if off < cur:
                    res.append((5.0, None))
                else:
                    res.append((8.0, (ACT, en, end, dur, -1)))
        elif status == DOWN:
            if lost >= 0 and end <= lost:
                res.append((1.5, None))
            if off == dur:
                res.append((2.5, (ACT, en, end, dur, -1)))
            elif off > dur:
                res.append((5.0, (ACT, en, end, off, -1)))
            else:
                res.append((6.0, None))
        else:
            if status == COM and end <= cur:
                res.append((3.0, None))
            else:
                res.append((9.0, None))
        return res
    if typ in ("checkpoint", "commit"):
        fin = typ == "commit"
        if status == ACT:
            base = 0.0 if node == en else 6.0
            if off == cur:
                c = base
            elif off > cur:
                c = base + 2.0
            else:
                c = None
            if c is not None:
                if fin:
                    res.append((c, (COM, en, off, off, -1)))
                else:
                    res.append((c, (ACT, en, off, off, -1)))
            else:
                if fin:
                    res.append((base + 3.0, (COM, en, off, off, -1)))
                else:
                    res.append((base + 1.0, (ACT, node, cur, max(dur, off), -1)))
        elif status == DOWN:
            if lost >= 0 and off <= lost and off >= dur:
                if fin:
                    res.append((2.0, (COM, en, off, off, -1)))
                else:
                    res.append((1.5, (DOWN, node, off, off, lost)))
            if off >= dur:
                c = 3.0 if off == dur else 5.0
                if fin:
                    res.append((c, (COM, en, off, off, -1)))
                else:
                    res.append((c, (ACT, en, off, off, -1)))
            else:
                res.append((6.0, None))
        else:
            res.append((9.0 if not (status == COM and off <= cur) else 4.0, None))
        return res
    if typ == "abort":
        if status == ACT:
            res.append((0.0 if node == en else 6.0, (ABO, en, dur, dur, -1)))
        elif status == DOWN:
            res.append((3.0, (ABO, en, dur, dur, -1)))
        else:
            res.append((9.0, None))
        return res
    if typ == "recover":
        if status == DOWN:
            if off == dur:
                res.append((0.0, (ACT, en, off, off, -1)))
            elif off > dur:
                res.append((2.0, (ACT, en, off, off, -1)))
            else:
                res.append((6.0, (ACT, en, off, off, -1)))
        elif status == ACT:
            if node == en and off <= cur and off >= dur:
                res.append((2.0, None))
            else:
                res.append((5.0, (ACT, en, off, max(dur, off) if off == cur else dur, -1)))
        else:
            res.append((9.0, None))
        return res
    if typ == "open":
        if status == PRE:
            return [(0.0, (ACT, en, 0, 0, -1))]
        return [(9.0, None)]
    return res


def reconstruct(state, params):
    PRE, ACT, DOWN, COM, ABO = 0, 1, 2, 3, 4
    t0 = time.process_time()
    inp = state.get("input") or {}
    events = sorted(inp.get("events") or [], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    idx = {s: k for k, s in enumerate(sids)}
    ns = len(sids)
    n_ev = len(events)
    if ns == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    # possible duplicates: earlier events with identical node/type/off/len
    keyfirst = {}
    dupof = {}
    for pos, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        key = (e["node"], e["type"], e["off"], e["len"])
        lst = keyfirst.setdefault(key, [])
        if lst:
            dupof[pos] = lst[-3:]
        lst.append(pos)

    init = tuple((PRE, None, 0, 0, -1) for _ in range(ns))
    beam = [(0.0, init, None)]
    BEAM = 40 if n_ev <= 200 else (24 if n_ev <= 400 else 16)

    def chain_lookup(ch, pos):
        while ch is not None:
            if ch[0] == pos:
                return ch[1]
            if ch[0] < pos:
                return None
            ch = ch[2]
        return None

    for pos, e in enumerate(events):
        el = time.process_time() - t0
        if el > 0.75:
            BEAM = 1
        elif el > 0.5:
            BEAM = min(BEAM, 4)
        typ = e["type"]
        if typ == "crash":
            nd = e["node"]
            nb = []
            for (c, sts, ch) in beam:
                lst = list(sts)
                for k in range(ns):
                    s = lst[k]
                    if s[0] == ACT and s[1] == nd:
                        lst[k] = (DOWN, nd, s[3], s[3], s[2])
                nb.append((c, tuple(lst), ch))
            beam = nb
            continue
        sid = e.get("sid")
        if sid is not None and sid in idx:
            cand = [idx[sid]]
            forced = True
        else:
            cand = None
            forced = False
        newb = {}

        def push(c, sts, ch):
            old = newb.get(sts)
            if old is None or c < old[0]:
                newb[sts] = (c, sts, ch)

        for (c, sts, ch) in beam:
            if pos in dupof:
                for p in dupof[pos]:
                    k = chain_lookup(ch, p)
                    if k is None:
                        ps = events[p].get("sid")
                        k = idx.get(ps) if ps is not None else None
                    if k is None:
                        continue
                    if forced and k != cand[0]:
                        continue
                    push(c + 0.3, sts, (pos, k, ch))
            ks = cand if forced else range(ns)
            any_opt = False
            for k in ks:
                opts = _options(sts[k], e, k)
                for oc, nst in opts:
                    any_opt = True
                    if nst is None:
                        push(c + oc, sts, (pos, k, ch))
                    else:
                        lst = list(sts)
                        lst[k] = nst
                        push(c + oc, tuple(lst), (pos, k, ch))
            if not any_opt:
                if forced:
                    push(c + 9.0, sts, (pos, cand[0], ch))
                else:
                    kk = 0
                    for k in range(ns):
                        if sts[k][0] != PRE:
                            kk = k
                    push(c + 10.0, sts, (pos, kk, ch))
        items = sorted(newb.values(), key=lambda z: z[0])
        beam = items[:max(1, BEAM)]

    best = beam[0]
    assign = {}
    ch = best[2]
    while ch is not None:
        assign[ch[0]] = ch[1]
        ch = ch[2]
    out_assign = {}
    tend = events[-1]["t"] if events else 0
    for pos, e in enumerate(events):
        if e["type"] == "crash":
            continue
        if e.get("sid") is None:
            k = assign.get(pos)
            if k is None:
                k = 0
            out_assign[str(e["i"])] = sids[k]
    sess = {}
    names = {ACT: "active", DOWN: "down", COM: "committed", ABO: "aborted", PRE: "active"}
    times = [[] for _ in range(ns)]
    for pos, e in enumerate(events):
        k = assign.get(pos)
        if e["type"] != "crash" and k is not None:
            times[k].append(e["t"])
    tstart = events[0]["t"] if events else 0
    span = max(1, tend - tstart)
    for k in range(ns):
        st = best[1][k]
        status = names[st[0]]
        if st[0] == ACT and len(times[k]) >= 3:
            ts = sorted(times[k])
            gaps = sorted(ts[j + 1] - ts[j] for j in range(len(ts) - 1))
            med = max(1, gaps[len(gaps) // 2])
            idle = tend - ts[-1]
            if idle > 10 * med and idle > 0.3 * span:
                status = "aborted"
        dur = st[3]
        sess[sids[k]] = {"status": status, "durable": int(dur)}
    state["output"] = {"assignments": out_assign, "sessions": sess}
    return state

