# session tuple: (st, node, off, dur, gaps, last_t, pre_off, crash_t, imp, act_t)
# st: 0 not opened, 1 active, 2 down, 3 committed, 4 aborted
ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    assign = {}
    for e in events:
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e["i"])] = sids[0] if sids else ""
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    # earlier events with identical signature (duplicate candidates)
    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    # duplicate delay estimate from pairs with known identical sid
    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    init = tuple((0, None, 0, 0, (), 0, 0, -10 ** 9, False, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 48
    elif nev < 400:
        BW = 28
    else:
        BW = 18
    budget = 0.7

    def opts_for(s, e):
        st, node, off, dur, gaps, lt, poff, ct, imp, at = s
        ty = e["type"]
        t = e["t"]
        eo = e["off"]
        res = []
        if st == 1 and node == e["node"]:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((1.0, (st, node, off + L, dur, gaps, t, poff, ct, imp, at)))
                elif eo == off:
                    res.append((0.0, (st, node, off + L, dur, gaps, t, poff, ct, imp, at)))
                elif eo > off:
                    ng = gaps + ((off, eo),)
                    if len(ng) > 4:
                        ng = ng[-4:]
                    res.append((3.0, (st, node, eo + L, dur, ng, t, poff, ct, imp, at)))
                else:
                    for gi in range(len(gaps)):
                        a, b = gaps[gi]
                        if a <= eo and eo + L <= b:
                            pieces = []
                            if a < eo:
                                pieces.append((a, eo))
                            if eo + L < b:
                                pieces.append((eo + L, b))
                            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
                            if not pieces:
                                c = -2.5
                            elif a == eo or eo + L == b:
                                c = 0.0
                            else:
                                c = 0.8
                            res.append((c, (st, node, off, dur, ng, t, poff, ct, imp, at)))
                            break
            elif ty in ("checkpoint", "commit"):
                nst = 3 if ty == "commit" else 1
                if eo is None:
                    res.append((1.0, (nst, node, off, off, gaps, t, poff, ct, imp, at)))
                elif eo == off:
                    res.append((0.0, (nst, node, off, off, gaps, t, poff, ct, imp, at)))
                elif eo > off:
                    ng = gaps + ((off, eo),)
                    if len(ng) > 4:
                        ng = ng[-4:]
                    res.append((3.0, (nst, node, eo, eo, ng, t, poff, ct, imp, at)))
                elif eo >= dur:
                    if nst == 3:
                        res.append((1.5, (nst, node, eo, eo, (), t, poff, ct, imp, at)))
                    else:
                        res.append((1.0, (nst, node, off, eo, gaps, t, poff, ct, imp, at)))
            elif ty == "abort":
                gap = max(0, t - lt)
                res.append((0.3 + 0.02 * min(gap, 60), (4, node, dur, dur, (), t, poff, ct, imp, at)))
            elif ty == "recover":
                if imp and eo is not None and eo == dur:
                    res.append((-2.5, (st, node, off, dur, gaps, t, poff, ct, False, at)))
        elif st == 2:
            if ty == "recover":
                if eo is None:
                    eo2 = dur
                    c = 0.5
                else:
                    eo2 = eo
                    c = 0.0 if eo == dur else (2.0 if eo > dur else 5.0)
                res.append((c, (1, e["node"], eo2, eo2, (), t, poff, ct, False, t)))
            else:
                # late event that truly happened before the crash
                if t - ct <= W + 2 and node == e["node"]:
                    if ty == "write":
                        if eo is None or dur <= eo <= poff + 1:
                            res.append((1.5, s))
                    elif ty == "checkpoint":
                        if eo is not None and eo >= dur:
                            res.append((1.5, (2, node, eo, eo, (), t, poff, ct, imp, at)))
                    elif ty == "commit":
                        if eo is not None and eo >= dur:
                            res.append((1.5, (3, node, eo, eo, (), t, poff, ct, imp, at)))
                    elif ty == "abort":
                        res.append((1.5, (4, node, dur, dur, (), t, poff, ct, imp, at)))
                # missing recover: implicit recover on this event's node
                ns = (1, e["node"], dur, dur, (), t, poff, ct, True, t)
                for c, s2 in opts_for(ns, e):
                    res.append((c + 3.0, s2))
        elif st in (3, 4):
            if t - lt <= W + 2 and node == e["node"] and ty != "recover":
                if eo is None or eo <= off:
                    res.append((1.5, s))
        return res

    budget_hit = False
    for p, e in enumerate(events):
        ty = e["type"]
        if not budget_hit and time.process_time() - t0 > budget:
            budget_hit = True
            BW = 1
            beam = beam[:1]
        newb = []
        if ty == "crash":
            nd = e["node"]
            t = e["t"]
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[3], s[3], (), s[5], s[2], t, False, s[9])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[9] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            for (cost, ss, dm, ch) in beam:
                lst = list(ss)
                lst[k] = (1, e["node"], 0, 0, (), e["t"], 0, -10 ** 9, False, e["t"])
                if p in need_track:
                    dm = dict(dm)
                    dm[p] = k
                newb.append((cost, tuple(lst), dm, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if e["t"] - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    if s[0] == 0:
                        continue
                    for c, s2 in opts_for(s, e):
                        if known is None and hint[p] is not None and hint[p] != k:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    for k in cands:
                        if ss[k][0] == 0 and known is None:
                            continue
                        produced.append((12.0, k, ss))
                    if not produced:
                        produced.append((12.0, cands[0], ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        seen = set()
        beam = []
        for h in newb:
            key = (tuple(x[:5] + x[6:9] for x in h[1]),
                   tuple(sorted(h[2].items())) if h[2] else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break

    best = beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[str(events[p]["i"])] = sids[k]
    for e in events:
        if e["type"] != "crash" and e["sid"] is None and str(e["i"]) not in assign:
            assign[str(e["i"])] = sids[0]
    sessions = {}
    for k, s in enumerate(best[1]):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

