def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, lt, ct, imp, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, t, ct, imp, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, t, ct, imp, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), t, ct, imp, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], t, ct, imp, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, t, ct, imp, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, t, ct, imp, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), t, ct, imp, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), t, ct, imp, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, t, ct, imp, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), t, ct, imp, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, t, ct, imp, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, t, ct, False, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    # last time of a labelled, non-duplicate-signature event per session (look-ahead)
    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    def opts_for(s, e):
        st = s[0]
        ty = e["type"]
        if st == 1:
            if s[1] == e["node"]:
                return _act_opts(s, e)
            return []
        res = []
        if st == 2:
            _, node, fr, dur, gaps, lt, ct, imp, at = s
            t = e["t"]
            eo = e["off"]
            if ty == "recover":
                if eo is None:
                    res.append((0.5, (1, e["node"], dur, dur, (), t, ct, False, t)))
                else:
                    if eo == dur:
                        c = 0.0
                    elif dur < eo <= fr:
                        c = 1.0
                    elif eo > fr:
                        c = 3.0
                    else:
                        c = 5.0
                    res.append((c, (1, e["node"], eo, eo, (), t, ct, False, t)))
                return res
            if node == e["node"]:
                wc = 1.5 if t - ct <= W + 2 else 4.0
                if ty == "write":
                    L = e["len"] or 0
                    if eo is None:
                        res.append((wc + 1.0, s))
                    elif eo == fr:
                        res.append((wc, (2, node, fr + L, dur, gaps, lt, ct, imp, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), lt, ct, imp, at)))
                    else:
                        f = _fill(gaps, eo, L)
                        if f is not None:
                            res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], lt, ct, imp, at)))
                elif ty == "checkpoint":
                    if eo is not None:
                        if dur <= eo <= fr:
                            res.append((wc, (2, node, fr, eo, gaps, lt, ct, imp, at)))
                        elif eo > fr:
                            res.append((wc + 3.0, (2, node, eo, eo, gaps, lt, ct, imp, at)))
                elif ty == "commit":
                    if eo is not None and eo >= dur:
                        res.append((wc + 0.5, (3, node, eo, eo, (), t, ct, imp, at)))
                elif ty == "abort":
                    res.append((wc + 0.5, (4, node, fr, dur, gaps, t, ct, imp, at)))
            ns = (1, e["node"], dur, dur, (), t, ct, True, t)
            for c, s2 in _act_opts(ns, e):
                res.append((c + 3.0, s2))
            return res
        if st in (3, 4):
            _, node, fr, dur, gaps, lt, ct, imp, at = s
            if ty == "recover" or node != e["node"]:
                return res
            t = e["t"]
            eo = e["off"]
            wc = 1.5 if t - lt <= W + 2 else 4.0
            if st == 3:
                if ty == "write":
                    L = e["len"] or 0
                    if eo is None:
                        res.append((wc + 1.0, s))
                    elif eo + L <= fr:
                        res.append((wc, s))
                elif ty == "checkpoint":
                    if eo is None or eo <= fr:
                        res.append((wc, s))
            else:
                if ty == "write":
                    L = e["len"] or 0
                    if eo is None:
                        res.append((wc + 1.0, s))
                    elif eo == fr:
                        res.append((wc, (4, node, fr + L, dur, gaps, lt, ct, imp, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), lt, ct, imp, at)))
                    else:
                        f = _fill(gaps, eo, L)
                        if f is not None:
                            res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], lt, ct, imp, at)))
                elif ty == "checkpoint":
                    if eo is None:
                        res.append((wc + 1.0, s))
                    elif dur <= eo <= fr:
                        res.append((wc, (4, node, fr, eo, gaps, lt, ct, imp, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (4, node, eo, eo, gaps, lt, ct, imp, at)))
                    else:
                        res.append((wc + 1.0, s))
        return res

    init = tuple((0, None, 0, 0, (), 0, NEG, False, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 48
    elif nev < 400:
        BW = 28
    else:
        BW = 18
    LIMIT = 0.78
    lastcrash = {}

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 3:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(3, int(BW * 0.75))
        newb = []
        if ty == "crash":
            nd = e["node"]
            t = e["t"]
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], s[5], t, False, s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            t = e["t"]
            nd = e["node"]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), t, NEG, False, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), t, lc, False, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if e["t"] - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    if s[0] == 0:
                        continue
                    for c, s2 in opts_for(s, e):
                        if known is None and hint[p] is not None and hint[p] != k:
                            c += 4.0
                        if s2[0] >= 3 and s[0] < 3 and lastT[k] > e["t"] + W:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hint[p] is not None:
                            fs = hint[p]
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == e["node"]:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        seen = set()
        beam = []
        for h in newb:
            key = (tuple((x[0], x[1], x[2], x[3], x[4], x[6], x[7]) for x in h[1]),
                   tuple(sorted(h[2].items())) if h[2] else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[str(events[p]["i"])] = sids[k]
    for e in events:
        if e["type"] != "crash" and e["sid"] is None and str(e["i"]) not in assign:
            assign[str(e["i"])] = sids[0]
    sessions = {}
    for k, s in enumerate(best[1]):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

import time

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
# session tuple: (st, node, fr, dur, gaps, ct, imp, lt, at) ; merge key = x[:7]
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


