    nev = len(events)

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 48
    elif nev < 400:
        BW = 28
    else:
        BW = 18
    LIMIT = 0.78
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        # windowed duplicate-tracking key (only recent tracked events matter)
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[str(events[p]["i"])] = sids[k]
    for e in events:
        if e["type"] != "crash" and e["sid"] is None and str(e["i"]) not in assign:
            assign[str(e["i"])] = sids[0]
    sessions = {}
    for k, s in enumerate(best[1]):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

import time
import bisect
import heapq

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, ct, imp, lt, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, t, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], ct, imp, t, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), ct, imp, t, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, ct, imp, t, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, ct, imp, t, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, ct, False, t, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _opts_for(s, e, W):
    st = s[0]
    ty = e["type"]
    if st == 1:
        if s[1] == e["node"]:
            return _act_opts(s, e)
        return []
    res = []
    if st == 2:
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        t = e["t"]
        eo = e["off"]
        if ty == "recover":
            if eo is None:
                res.append((0.5, (1, e["node"], dur, dur, (), ct, False, t, t)))
            else:
                if eo == dur:
                    c = 0.0
                elif dur < eo <= fr:
                    c = 1.0
                elif eo > fr:
                    c = 3.0
                else:
                    c = 5.0
                res.append((c, (1, e["node"], eo, eo, (), ct, False, t, t)))
            return res
        if node == e["node"]:
            wc = 1.5 if t - ct <= W + 2 else 4.0
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (2, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is not None:
                    if dur <= eo <= fr:
                        res.append((wc, (2, node, fr, eo, gaps, ct, imp, lt, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo, eo, gaps, ct, imp, lt, at)))
            elif ty == "commit":
                if eo is not None and eo >= dur:
                    res.append((wc + 0.5, (3, node, eo, eo, (), ct, imp, t, at)))
            elif ty == "abort":
                res.append((wc + 0.5, (4, node, fr, dur, gaps, ct, imp, t, at)))
        ns = (1, e["node"], dur, dur, (), ct, True, t, t)
        for c, s2 in _act_opts(ns, e):
            res.append((c + 3.0, s2))
        return res
    if st in (3, 4):
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        if ty == "recover" or node != e["node"]:
            return res
        t = e["t"]
        eo = e["off"]
        wc = 1.5 if t - lt <= W + 2 else 4.0
        if st == 3:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo + L <= fr:
                    res.append((wc, s))
            elif ty == "checkpoint":
                if eo is None or eo <= fr:
                    res.append((wc, s))
        else:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (4, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is None:
                    res.append((wc + 1.0, s))
                elif dur <= eo <= fr:
                    res.append((wc, (4, node, fr, eo, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo, eo, gaps, ct, imp, lt, at)))
                else:
                    res.append((wc + 1.0, s))
    return res


def _refine(events, S, W, D, hint, lastT, assign, init_states, t0, deadline):
    """Local search over the assignment with a per-session decomposed objective."""
    nev = len(events)
    crash_pos = [p for p in range(nev) if events[p]["type"] == "crash"]
    times = [e["t"] for e in events]
    sig = [None] * nev
    lcb = [None] * nev
    lastcrash = {}
    for p, e in enumerate(events):
        ty = e["type"]
        if ty == "crash":
            lastcrash[e["node"]] = e["t"]
        elif ty == "open":
            lcb[p] = lastcrash.get(e["node"])
        else:
            sig[p] = (e["node"], ty, e["off"], e["len"])
    anon = [e["sid"] is None and e["type"] not in ("crash", "open") for e in events]
    RW = 6

    def prune(nh):
        nh.sort(key=lambda h: h[0])
        out = []
        seen = set()
        for h in nh:
            key = None if h[1] is None else h[1][:7]
            if key in seen:
                continue
            seen.add(key)
            out.append(h)
            if len(out) >= RW:
                break
        return out

    def replay(k, plist):
        hyps = [(0.0, None)]
        lastsig = {}
        for p in heapq.merge(plist, crash_pos):
            e = events[p]
            ty = e["type"]
            t = e["t"]
            nd = e["node"]
            nh = []
            if ty == "crash":
                for c, s in hyps:
                    if s is not None and s[0] == 1 and s[1] == nd:
                        nh.append((c, (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])))
                        if t - s[8] <= W:
                            nh.append((c + 2.0, s))
                    else:
                        nh.append((c, s))
            elif ty == "open":
                for c, s in hyps:
                    if s is None:
                        nh.append((c, (1, nd, 0, 0, (), NEG, False, t, t)))
                        lc = lcb[p]
                        if lc is not None and t - lc <= W:
                            nh.append((c + 2.5, (2, nd, 0, 0, (), lc, False, t, t)))
                    else:
                        nh.append((c + 12.0, s))
            else:
                pen = 4.0 if (anon[p] and hint[p] is not None and hint[p] != k) else 0.0
                sg = sig[p]
                prevt = lastsig.get(sg)
                for c, s in hyps:
                    produced = False
                    if prevt is not None:
                        dc = 1.0 if t - prevt <= D else 3.0
                        nh.append((c + dc + pen, s))
                        produced = True
                    if s is not None and s[0] != 0:
                        for oc, s2 in _opts_for(s, e, W):
                            if s2[0] >= 3 and s[0] < 3 and lastT[k] > t + W:
                                oc += 4.0
                            nh.append((c + oc + pen, s2))
                            produced = True
                    if not produced:
                        nh.append((c + 12.0 + pen, s))
                lastsig[sg] = t
            hyps = prune(nh)
        return hyps[0]

    lists = [[] for _ in range(S)]
    for p in range(nev):
        if assign[p] is not None:
            lists[assign[p]].append(p)
    cache = [replay(k, lists[k]) for k in range(S)]
    touched = set()
    movable = [p for p in range(nev) if anon[p]]
    R = max(40, 4 * W)
    passes = 0
    improved = True
    timeout = False
    while improved and passes < 5 and not timeout:
        improved = False
        passes += 1
        order = sorted(movable, key=lambda p: (-cache[assign[p]][0], p))
        for p in order:
            if time.process_time() - t0 > deadline:
                timeout = True
                break
            a = assign[p]
            e = events[p]
            t = e["t"]
            nd = e["node"]
            ty = e["type"]
            lo = bisect.bisect_left(times, t - R)
            hi = bisect.bisect_right(times, t + R)
            cands = []
            for q in range(lo, hi):
                kq = assign[q]
                if kq is None or kq == a or kq in cands:
                    continue
                eq = events[q]
                if ty == "recover" or eq["node"] == nd or eq["type"] == "recover":
                    cands.append(kq)
            if not cands:
                continue
            base_a = cache[a][0]
            la = list(lists[a])
            la.remove(p)
            ra = replay(a, la)
            best = None
            bestd = -1e-9
            for b in cands:
                lb = list(lists[b])
                bisect.insort(lb, p)
                rb = replay(b, lb)
                d = ra[0] + rb[0] - base_a - cache[b][0]
                if d < bestd:
                    bestd = d
                    best = ("m", b, la, lb, ra, rb, None)
            if best is None:
                half = R // 2 + 1
                for q in range(lo, hi):
                    if time.process_time() - t0 > deadline:
                        timeout = True
                        break
                    if q == p or not anon[q]:
                        continue
                    b = assign[q]
                    if b == a:
                        continue
                    eq = events[q]
                    if eq["type"] != ty or eq["node"] != nd or abs(eq["t"] - t) > half:
                        continue
                    la2 = list(la)
                    bisect.insort(la2, q)
                    lb = list(lists[b])
                    lb.remove(q)
                    bisect.insort(lb, p)
                    ra2 = replay(a, la2)
                    rb = replay(b, lb)
                    d = ra2[0] + rb[0] - base_a - cache[b][0]
                    if d < bestd:
                        bestd = d
                        best = ("s", b, la2, lb, ra2, rb, q)
            if best is not None:
                kind, b, nla, nlb, nra, nrb, q = best
                lists[a] = nla
                lists[b] = nlb
                cache[a] = nra
                cache[b] = nrb
                assign[p] = b
                if q is not None:
                    assign[q] = a
                touched.add(a)
                touched.add(b)
                improved = True
    final_states = list(init_states)
    for k in touched:
        s = cache[k][1]
        if s is not None:
            final_states[k] = s
    return assign, final_states


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 40
    elif nev < 400:
        BW = 22
    else:
        BW = 14
    LIMIT = 0.55
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = [None] * nev
    for p, e in enumerate(events):
        if e["type"] == "crash":
            continue
        if e["sid"] is not None:
            assign[p] = sidx[e["sid"]]
        else:
            assign[p] = 0
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[p] = k
    final_states = list(best[1])

    # refinement phase (local search with per-session replay objective)
    try:
        if time.process_time() - t0 < 0.8:
            a2, f2 = _refine(events, S, W, D, hint, lastT, list(assign), final_states, t0, 0.86)
            assign = a2
            final_states = f2
    except Exception:
        pass

    out_assign = {}
    for p, e in enumerate(events):
        if e["type"] != "crash" and e["sid"] is None:
            k = assign[p] if assign[p] is not None else 0
            out_assign[str(e["i"])] = sids[k]
    sessions = {}
    for k, s in enumerate(final_states):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": out_assign, "sessions": sessions}
    return state

import time
import bisect
import heapq

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, ct, imp, lt, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, t, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], ct, imp, t, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), ct, imp, t, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, ct, imp, t, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, ct, imp, t, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, ct, False, t, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _opts_for(s, e, W):
    st = s[0]
    ty = e["type"]
    if st == 1:
        if s[1] == e["node"]:
            return _act_opts(s, e)
        return []
    res = []
    if st == 2:
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        t = e["t"]
        eo = e["off"]
        if ty == "recover":
            if eo is None:
                res.append((0.5, (1, e["node"], dur, dur, (), ct, False, t, t)))
            else:
                if eo == dur:
                    c = 0.0
                elif dur < eo <= fr:
                    c = 1.0
                elif eo > fr:
                    c = 3.0
                else:
                    c = 5.0
                res.append((c, (1, e["node"], eo, eo, (), ct, False, t, t)))
            return res
        if node == e["node"]:
            wc = 1.5 if t - ct <= W + 2 else 4.0
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (2, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is not None:
                    if dur <= eo <= fr:
                        res.append((wc, (2, node, fr, eo, gaps, ct, imp, lt, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo, eo, gaps, ct, imp, lt, at)))
            elif ty == "commit":
                if eo is not None and eo >= dur:
                    res.append((wc + 0.5, (3, node, eo, eo, (), ct, imp, t, at)))
            elif ty == "abort":
                res.append((wc + 0.5, (4, node, fr, dur, gaps, ct, imp, t, at)))
        ns = (1, e["node"], dur, dur, (), ct, True, t, t)
        for c, s2 in _act_opts(ns, e):
            res.append((c + 3.0, s2))
        return res
    if st in (3, 4):
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        if ty == "recover" or node != e["node"]:
            return res
        t = e["t"]
        eo = e["off"]
        wc = 1.5 if t - lt <= W + 2 else 4.0
        if st == 3:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo + L <= fr:
                    res.append((wc, s))
            elif ty == "checkpoint":
                if eo is None or eo <= fr:
                    res.append((wc, s))
        else:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (4, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is None:
                    res.append((wc + 1.0, s))
                elif dur <= eo <= fr:
                    res.append((wc, (4, node, fr, eo, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo, eo, gaps, ct, imp, lt, at)))
                else:
                    res.append((wc + 1.0, s))
    return res


def _refine(events, S, W, D, hint, lastT, assign, init_states, t0, deadline):
    """Local search with single-event moves and block (segment / suffix) exchanges."""
    nev = len(events)
    crash_pos = [p for p in range(nev) if events[p]["type"] == "crash"]
    times = [e["t"] for e in events]
    sig = [None] * nev
    lcb = [None] * nev
    lastcrash = {}
    for p, e in enumerate(events):
        ty = e["type"]
        if ty == "crash":
            lastcrash[e["node"]] = e["t"]
        elif ty == "open":
            lcb[p] = lastcrash.get(e["node"])
        else:
            sig[p] = (e["node"], ty, e["off"], e["len"])
    anon = [e["sid"] is None and e["type"] not in ("crash", "open") for e in events]
    RW = 6

    def prune(nh):
        nh.sort(key=lambda h: h[0])
        out = []
        seen = set()
        for h in nh:
            key = None if h[1] is None else h[1][:7]
            if key in seen:
                continue
            seen.add(key)
            out.append(h)
            if len(out) >= RW:
                break
        return out

    def replay(k, plist):
        hyps = [(0.0, None)]
        lastsig = {}
        for p in heapq.merge(plist, crash_pos):
            e = events[p]
            ty = e["type"]
            t = e["t"]
            nd = e["node"]
            nh = []
            if ty == "crash":
                for c, s in hyps:
                    if s is not None and s[0] == 1 and s[1] == nd:
                        nh.append((c, (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])))
                        if t - s[8] <= W:
                            nh.append((c + 2.0, s))
                    else:
                        nh.append((c, s))
            elif ty == "open":
                for c, s in hyps:
                    if s is None:
                        nh.append((c, (1, nd, 0, 0, (), NEG, False, t, t)))
                        lc = lcb[p]
                        if lc is not None and t - lc <= W:
                            nh.append((c + 2.5, (2, nd, 0, 0, (), lc, False, t, t)))
                    else:
                        nh.append((c + 12.0, s))
            else:
                pen = 4.0 if (anon[p] and hint[p] is not None and hint[p] != k) else 0.0
                sg = sig[p]
                prevt = lastsig.get(sg)
                for c, s in hyps:
                    produced = False
                    if prevt is not None:
                        dc = 1.0 if t - prevt <= D else 3.0
                        nh.append((c + dc + pen, s))
                        produced = True
                    if s is not None and s[0] != 0:
                        for oc, s2 in _opts_for(s, e, W):
                            if s2[0] >= 3 and s[0] < 3 and lastT[k] > t + W:
                                oc += 4.0
                            nh.append((c + oc + pen, s2))
                            produced = True
                    if not produced:
                        nh.append((c + 12.0 + pen, s))
                lastsig[sg] = t
            hyps = prune(nh)
        return hyps[0]

    lists = [[] for _ in range(S)]
    for p in range(nev):
        if assign[p] is not None:
            lists[assign[p]].append(p)
    cache = [replay(k, lists[k]) for k in range(S)]
    touched = set()
    movable = [p for p in range(nev) if anon[p]]
    R = max(40, 4 * W)
    flags = {"timeout": False}

    def out_of_time():
        if time.process_time() - t0 > deadline:
            flags["timeout"] = True
            return True
        return False

    def nearby_sessions(a, p_list, nd, allow_recover):
        res = []
        tl = min(times[p] for p in p_list)
        th = max(times[p] for p in p_list)
        lo = bisect.bisect_left(times, tl - R)
        hi = bisect.bisect_right(times, th + R)
        for q in range(lo, hi):
            kq = assign[q]
            if kq is None or kq == a or kq in res:
                continue
            eq = events[q]
            if allow_recover or eq["node"] == nd or eq["type"] == "recover":
                res.append(kq)
        return res

    def single_pass():
        improved = False
        order = sorted(movable, key=lambda p: (-cache[assign[p]][0], p))
        for p in order:
            if out_of_time():
                break
            a = assign[p]
            e = events[p]
            t = e["t"]
            nd = e["node"]
            ty = e["type"]
            lo = bisect.bisect_left(times, t - R)
            hi = bisect.bisect_right(times, t + R)
            cands = nearby_sessions(a, [p], nd, ty == "recover")
            if not cands:
                continue
            base_a = cache[a][0]
            la = list(lists[a])
            la.remove(p)
            ra = replay(a, la)
            best = None
            bestd = -1e-9
            for b in cands:
                lb = list(lists[b])
                bisect.insort(lb, p)
                rb = replay(b, lb)
                d = ra[0] + rb[0] - base_a - cache[b][0]
                if d < bestd:
                    bestd = d
                    best = (b, la, lb, ra, rb, None)
            if best is None:
                half = R // 2 + 1
                for q in range(lo, hi):
                    if out_of_time():
                        break
                    if q == p or not anon[q]:
                        continue
                    b = assign[q]
                    if b == a:
                        continue
                    eq = events[q]
                    if eq["type"] != ty or eq["node"] != nd or abs(eq["t"] - t) > half:
                        continue
                    la2 = list(la)
                    bisect.insort(la2, q)
                    lb = list(lists[b])
                    lb.remove(q)
                    bisect.insort(lb, p)
                    ra2 = replay(a, la2)
                    rb = replay(b, lb)
                    d = ra2[0] + rb[0] - base_a - cache[b][0]
                    if d < bestd:
                        bestd = d
                        best = (b, la2, lb, ra2, rb, q)
            if best is not None:
                b, nla, nlb, nra, nrb, q = best
                lists[a] = nla
                lists[b] = nlb
                cache[a] = nra
                cache[b] = nrb
                assign[p] = b
                if q is not None:
                    assign[q] = a
                touched.add(a)
                touched.add(b)
                improved = True
        return improved

    def block_pass():
        improved = False
        order_s = sorted(range(S), key=lambda k: (-cache[k][0], k))
        for a in order_s:
            if flags["timeout"]:
                break
            if cache[a][0] <= 0.9:
                continue
            bynode = {}
            for p in lists[a]:
                if anon[p]:
                    bynode.setdefault(events[p]["node"], []).append(p)
            done = False
            for nd in sorted(bynode.keys()):
                if done or flags["timeout"]:
                    break
                seq = bynode[nd]
                n = len(seq)
                for i in range(n):
                    if out_of_time():
                        break
                    base_a = cache[a][0]
                    best = None
                    bestd = -1e-9
                    segs = []
                    for L in (2, 3, 5):
                        if i + L <= n:
                            segs.append(seq[i:i + L])
                    if n - i >= 2 and (n - i) not in (2, 3, 5):
                        segs.append(seq[i:])
                    cands = nearby_sessions(a, seq[i:i + 2], nd, False)
                    if not cands:
                        continue
                    for seg in segs:
                        if out_of_time():
                            break
                        segset = set(seg)
                        la = [x for x in lists[a] if x not in segset]
                        ra = replay(a, la)
                        for b in cands:
                            lb = sorted(lists[b] + seg)
                            rb = replay(b, lb)
                            d = ra[0] + rb[0] - base_a - cache[b][0]
                            if d < bestd:
                                bestd = d
                                best = (b, la, lb, ra, rb, seg, [])
                    # suffix exchange (uncross tracks after a cut time)
                    tc = times[seq[i]]
                    asuf = seq[i:]
                    aset = set(asuf)
                    for b in cands:
                        if out_of_time():
                            break
                        bsuf = [q for q in lists[b]
                                if anon[q] and events[q]["node"] == nd and times[q] >= tc]
                        if not bsuf:
                            continue
                        bset = set(bsuf)
                        la = sorted([x for x in lists[a] if x not in aset] + bsuf)
                        lb = sorted([x for x in lists[b] if x not in bset] + asuf)
                        ra = replay(a, la)
                        rb = replay(b, lb)
                        d = ra[0] + rb[0] - base_a - cache[b][0]
                        if d < bestd:
                            bestd = d
                            best = (b, la, lb, ra, rb, asuf, bsuf)
                    if best is not None:
                        b, nla, nlb, nra, nrb, moved_a, moved_b = best
                        lists[a] = nla
                        lists[b] = nlb
                        cache[a] = nra
                        cache[b] = nrb
                        for x in moved_a:
                            assign[x] = b
                        for x in moved_b:
                            assign[x] = a
                        touched.add(a)
                        touched.add(b)
                        improved = True
                        done = True
                        break
        return improved

    rounds = 0
    while rounds < 8 and not flags["timeout"]:
        rounds += 1
        i1 = single_pass()
        i2 = False
        if not flags["timeout"]:
            i2 = block_pass()
        if not (i1 or i2):
            break

    final_states = list(init_states)
    for k in touched:
        s = cache[k][1]
        if s is not None:
            final_states[k] = s
    return assign, final_states


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 40
    elif nev < 400:
        BW = 22
    else:
        BW = 14
    LIMIT = 0.5
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = [None] * nev
    for p, e in enumerate(events):
        if e["type"] == "crash":
            continue
        if e["sid"] is not None:
            assign[p] = sidx[e["sid"]]
        else:
            assign[p] = 0
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[p] = k
    final_states = list(best[1])

    try:
        if time.process_time() - t0 < 0.82:
            a2, f2 = _refine(events, S, W, D, hint, lastT, list(assign), final_states, t0, 0.9)
            assign = a2
            final_states = f2
    except Exception:
        pass

    out_assign = {}
    for p, e in enumerate(events):
        if e["type"] != "crash" and e["sid"] is None:
            k = assign[p] if assign[p] is not None else 0
            out_assign[str(e["i"])] = sids[k]
    sessions = {}
    for k, s in enumerate(final_states):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": out_assign, "sessions": sessions}
    return state

import time
import bisect
import heapq
import random

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, ct, imp, lt, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, t, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], ct, imp, t, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), ct, imp, t, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, ct, imp, t, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, ct, imp, t, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, ct, False, t, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _opts_for(s, e, W):
    st = s[0]
    ty = e["type"]
    if st == 1:
        if s[1] == e["node"]:
            return _act_opts(s, e)
        return []
    res = []
    if st == 2:
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        t = e["t"]
        eo = e["off"]
        if ty == "recover":
            if eo is None:
                res.append((0.5, (1, e["node"], dur, dur, (), ct, False, t, t)))
            else:
                if eo == dur:
                    c = 0.0
                elif dur < eo <= fr:
                    c = 1.0
                elif eo > fr:
                    c = 3.0
                else:
                    c = 5.0
                res.append((c, (1, e["node"], eo, eo, (), ct, False, t, t)))
            return res
        if node == e["node"]:
            wc = 1.5 if t - ct <= W + 2 else 4.0
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (2, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is not None:
                    if dur <= eo <= fr:
                        res.append((wc, (2, node, fr, eo, gaps, ct, imp, lt, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo, eo, gaps, ct, imp, lt, at)))
            elif ty == "commit":
                if eo is not None and eo >= dur:
                    res.append((wc + 0.5, (3, node, eo, eo, (), ct, imp, t, at)))
            elif ty == "abort":
                res.append((wc + 0.5, (4, node, fr, dur, gaps, ct, imp, t, at)))
        ns = (1, e["node"], dur, dur, (), ct, True, t, t)
        for c, s2 in _act_opts(ns, e):
            res.append((c + 3.0, s2))
        return res
    if st in (3, 4):
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        if ty == "recover" or node != e["node"]:
            return res
        t = e["t"]
        eo = e["off"]
        wc = 1.5 if t - lt <= W + 2 else 4.0
        if st == 3:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo + L <= fr:
                    res.append((wc, s))
            elif ty == "checkpoint":
                if eo is None or eo <= fr:
                    res.append((wc, s))
        else:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (4, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is None:
                    res.append((wc + 1.0, s))
                elif dur <= eo <= fr:
                    res.append((wc, (4, node, fr, eo, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo, eo, gaps, ct, imp, lt, at)))
                else:
                    res.append((wc + 1.0, s))
    return res


def _refine(events, S, W, D, hint, lastT, assign, init_states, t0, deadline, phase1_end):
    """Descent local search, then iterated local search with window-swap kicks."""
    nev = len(events)
    crash_pos = [p for p in range(nev) if events[p]["type"] == "crash"]
    times = [e["t"] for e in events]
    sig = [None] * nev
    lcb = [None] * nev
    lastcrash = {}
    for p, e in enumerate(events):
        ty = e["type"]
        if ty == "crash":
            lastcrash[e["node"]] = e["t"]
        elif ty == "open":
            lcb[p] = lastcrash.get(e["node"])
        else:
            sig[p] = (e["node"], ty, e["off"], e["len"])
    anon = [e["sid"] is None and e["type"] not in ("crash", "open") for e in events]
    RW = 6

    def prune(nh):
        nh.sort(key=lambda h: h[0])
        out = []
        seen = set()
        for h in nh:
            key = None if h[1] is None else h[1][:7]
            if key in seen:
                continue
            seen.add(key)
            out.append(h)
            if len(out) >= RW:
                break
        return out

    def replay(k, plist):
        hyps = [(0.0, None)]
        lastsig = {}
        for p in heapq.merge(plist, crash_pos):
            e = events[p]
            ty = e["type"]
            t = e["t"]
            nd = e["node"]
            nh = []
            if ty == "crash":
                for c, s in hyps:
                    if s is not None and s[0] == 1 and s[1] == nd:
                        nh.append((c, (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])))
                        if t - s[8] <= W:
                            nh.append((c + 2.0, s))
                    else:
                        nh.append((c, s))
            elif ty == "open":
                for c, s in hyps:
                    if s is None:
                        nh.append((c, (1, nd, 0, 0, (), NEG, False, t, t)))
                        lc = lcb[p]
                        if lc is not None and t - lc <= W:
                            nh.append((c + 2.5, (2, nd, 0, 0, (), lc, False, t, t)))
                    else:
                        nh.append((c + 12.0, s))
            else:
                pen = 4.0 if (anon[p] and hint[p] is not None and hint[p] != k) else 0.0
                sg = sig[p]
                prevt = lastsig.get(sg)
                for c, s in hyps:
                    produced = False
                    if prevt is not None:
                        dc = 1.0 if t - prevt <= D else 3.0
                        nh.append((c + dc + pen, s))
                        produced = True
                    if s is not None and s[0] != 0:
                        for oc, s2 in _opts_for(s, e, W):
                            if s2[0] >= 3 and s[0] < 3 and lastT[k] > t + W:
                                oc += 4.0
                            nh.append((c + oc + pen, s2))
                            produced = True
                    if not produced:
                        nh.append((c + 12.0 + pen, s))
                lastsig[sg] = t
            hyps = prune(nh)
        return hyps[0]

    lists = [[] for _ in range(S)]
    for p in range(nev):
        if assign[p] is not None:
            lists[assign[p]].append(p)
    cache = [replay(k, lists[k]) for k in range(S)]
    touched = set()
    movable = [p for p in range(nev) if anon[p]]
    R = max(40, 4 * W)
    flags = {"timeout": False, "dl": min(deadline, phase1_end)}

    def out_of_time():
        if time.process_time() - t0 > flags["dl"]:
            flags["timeout"] = True
            return True
        return False

    def nearby_sessions(a, p_list, nd, allow_recover):
        res = []
        tl = min(times[p] for p in p_list)
        th = max(times[p] for p in p_list)
        lo = bisect.bisect_left(times, tl - R)
        hi = bisect.bisect_right(times, th + R)
        for q in range(lo, hi):
            kq = assign[q]
            if kq is None or kq == a or kq in res:
                continue
            eq = events[q]
            if allow_recover or eq["node"] == nd or eq["type"] == "recover":
                res.append(kq)
        return res

    def single_pass(subset=None):
        improved = False
        base_set = movable if subset is None else subset
        order = sorted(base_set, key=lambda p: (-cache[assign[p]][0], p))
        for p in order:
            if out_of_time():
                break
            a = assign[p]
            e = events[p]
            t = e["t"]
            nd = e["node"]
            ty = e["type"]
            lo = bisect.bisect_left(times, t - R)
            hi = bisect.bisect_right(times, t + R)
            cands = nearby_sessions(a, [p], nd, ty == "recover")
            if not cands:
                continue
            base_a = cache[a][0]
            la = list(lists[a])
            la.remove(p)
            ra = replay(a, la)
            best = None
            bestd = -1e-9
            for b in cands:
                lb = list(lists[b])
                bisect.insort(lb, p)
                rb = replay(b, lb)
                d = ra[0] + rb[0] - base_a - cache[b][0]
                if d < bestd:
                    bestd = d
                    best = (b, la, lb, ra, rb, None)
            if best is None:
                half = R // 2 + 1
                for q in range(lo, hi):
                    if out_of_time():
                        break
                    if q == p or not anon[q]:
                        continue
                    b = assign[q]
                    if b == a:
                        continue
                    eq = events[q]
                    if eq["type"] != ty or eq["node"] != nd or abs(eq["t"] - t) > half:
                        continue
                    la2 = list(la)
                    bisect.insort(la2, q)
                    lb = list(lists[b])
                    lb.remove(q)
                    bisect.insort(lb, p)
                    ra2 = replay(a, la2)
                    rb = replay(b, lb)
                    d = ra2[0] + rb[0] - base_a - cache[b][0]
                    if d < bestd:
                        bestd = d
                        best = (b, la2, lb, ra2, rb, q)
            if best is not None:
                b, nla, nlb, nra, nrb, q = best
                lists[a] = nla
                lists[b] = nlb
                cache[a] = nra
                cache[b] = nrb
                assign[p] = b
                if q is not None:
                    assign[q] = a
                touched.add(a)
                touched.add(b)
                improved = True
        return improved

    def block_pass():
        improved = False
        order_s = sorted(range(S), key=lambda k: (-cache[k][0], k))
        for a in order_s:
            if flags["timeout"]:
                break
            if cache[a][0] <= 0.9:
                continue
            bynode = {}
            for p in lists[a]:
                if anon[p]:
                    bynode.setdefault(events[p]["node"], []).append(p)
            done = False
            for nd in sorted(bynode.keys()):
                if done or flags["timeout"]:
                    break
                seq = bynode[nd]
                n = len(seq)
                for i in range(n):
                    if out_of_time():
                        break
                    base_a = cache[a][0]
                    best = None
                    bestd = -1e-9
                    segs = []
                    for L in (2, 3, 5):
                        if i + L <= n:
                            segs.append(seq[i:i + L])
                    if n - i >= 2 and (n - i) not in (2, 3, 5):
                        segs.append(seq[i:])
                    cands = nearby_sessions(a, seq[i:i + 2], nd, False)
                    if not cands:
                        continue
                    for seg in segs:
                        if out_of_time():
                            break
                        segset = set(seg)
                        la = [x for x in lists[a] if x not in segset]
                        ra = replay(a, la)
                        for b in cands:
                            lb = sorted(lists[b] + seg)
                            rb = replay(b, lb)
                            d = ra[0] + rb[0] - base_a - cache[b][0]
                            if d < bestd:
                                bestd = d
                                best = (b, la, lb, ra, rb, seg, [])
                    tc = times[seq[i]]
                    asuf = seq[i:]
                    aset = set(asuf)
                    for b in cands:
                        if out_of_time():
                            break
                        bsuf = [q for q in lists[b]
                                if anon[q] and events[q]["node"] == nd and times[q] >= tc]
                        if not bsuf:
                            continue
                        bset = set(bsuf)
                        la = sorted([x for x in lists[a] if x not in aset] + bsuf)
                        lb = sorted([x for x in lists[b] if x not in bset] + asuf)
                        ra = replay(a, la)
                        rb = replay(b, lb)
                        d = ra[0] + rb[0] - base_a - cache[b][0]
                        if d < bestd:
                            bestd = d
                            best = (b, la, lb, ra, rb, asuf, bsuf)
                    if best is not None:
                        b, nla, nlb, nra, nrb, moved_a, moved_b = best
                        lists[a] = nla
                        lists[b] = nlb
                        cache[a] = nra
                        cache[b] = nrb
                        for x in moved_a:
                            assign[x] = b
                        for x in moved_b:
                            assign[x] = a
                        touched.add(a)
                        touched.add(b)
                        improved = True
                        done = True
                        break
        return improved

    # ---- phase 1: descent ----
    rounds = 0
    while rounds < 8 and not flags["timeout"]:
        rounds += 1
        i1 = single_pass()
        i2 = False
        if not flags["timeout"]:
            i2 = block_pass()
        if not (i1 or i2):
            break

    # ---- phase 2: iterated local search with window-swap kicks ----
    flags["timeout"] = False
    flags["dl"] = deadline
    rng = random.Random(7919 + nev * 31 + S * 7)
    spans = (0, W, 2 * W, 4 * W)
    it = 0
    fails = 0
    while it < 600 and fails < 120 and not out_of_time():
        it += 1
        bad = [k for k in range(S) if cache[k][0] > 0.9]
        if not bad:
            break
        tot = sum(cache[k][0] for k in bad)
        r = rng.random() * tot
        a = bad[-1]
        acc = 0.0
        for k in bad:
            acc += cache[k][0]
            if r <= acc:
                a = k
                break
        ev = [x for x in lists[a] if anon[x]]
        if not ev:
            fails += 1
            continue
        p = ev[rng.randrange(len(ev))]
        nd = events[p]["node"]
        cands = nearby_sessions(a, [p], nd, events[p]["type"] == "recover")
        if not cands:
            fails += 1
            continue
        b = cands[rng.randrange(len(cands))]
        span = spans[rng.randrange(len(spans))]
        t1 = times[p] - (span // 2 if rng.random() < 0.5 else 0)
        t2 = t1 + span
        A = [x for x in lists[a] if anon[x] and events[x]["node"] == nd and t1 <= times[x] <= t2]
        B = [x for x in lists[b] if anon[x] and events[x]["node"] == nd and t1 <= times[x] <= t2]
        if not A and not B:
            fails += 1
            continue
        old_total = sum(c[0] for c in cache)
        s_lists = list(lists)
        s_cache = list(cache)
        s_assign = list(assign)
        s_touched = set(touched)
        aset = set(A)
        bset = set(B)
        la = sorted([x for x in lists[a] if x not in aset] + B)
        lb = sorted([x for x in lists[b] if x not in bset] + A)
        lists[a] = la
        lists[b] = lb
        cache[a] = replay(a, la)
        cache[b] = replay(b, lb)
        for x in A:
            assign[x] = b
        for x in B:
            assign[x] = a
        touched.add(a)
        touched.add(b)
        lo_t = t1 - R
        hi_t = t2 + R
        sub = [x for x in lists[a] + lists[b] if anon[x] and lo_t <= times[x] <= hi_t]
        if not flags["timeout"]:
            single_pass(sub)
        new_total = sum(c[0] for c in cache)
        if new_total < old_total - 1e-9:
            fails = 0
        else:
            lists[:] = s_lists
            cache[:] = s_cache
            assign[:] = s_assign
            touched.clear()
            touched.update(s_touched)
            fails += 1

    final_states = list(init_states)
    for k in touched:
        s = cache[k][1]
        if s is not None:
            final_states[k] = s
    return assign, final_states


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 40
    elif nev < 400:
        BW = 22
    else:
        BW = 14
    LIMIT = 0.42
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = [None] * nev
    for p, e in enumerate(events):
        if e["type"] == "crash":
            continue
        if e["sid"] is not None:
            assign[p] = sidx[e["sid"]]
        else:
            assign[p] = 0
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[p] = k
    final_states = list(best[1])

    try:
        if time.process_time() - t0 < 0.8:
            a2, f2 = _refine(events, S, W, D, hint, lastT, list(assign), final_states,
                             t0, 0.9, 0.7)
            assign = a2
            final_states = f2
    except Exception:
        pass

    out_assign = {}
    for p, e in enumerate(events):
        if e["type"] != "crash" and e["sid"] is None:
            k = assign[p] if assign[p] is not None else 0
            out_assign[str(e["i"])] = sids[k]
    sessions = {}
    for k, s in enumerate(final_states):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": out_assign, "sessions": sessions}
    return state

import time
import bisect

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, ct, imp, lt, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, t, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], ct, imp, t, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), ct, imp, t, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, ct, imp, t, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, ct, imp, t, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, ct, False, t, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _opts_for(s, e, W):
    st = s[0]
    ty = e["type"]
    if st == 1:
        if s[1] == e["node"]:
            return _act_opts(s, e)
        return []
    res = []
    if st == 2:
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        t = e["t"]
        eo = e["off"]
        if ty == "recover":
            if eo is None:
                res.append((0.5, (1, e["node"], dur, dur, (), ct, False, t, t)))
            else:
                if eo == dur:
                    c = 0.0
                elif dur < eo <= fr:
                    c = 1.0
                elif eo > fr:
                    c = 3.0
                else:
                    c = 5.0
                res.append((c, (1, e["node"], eo, eo, (), ct, False, t, t)))
            return res
        if node == e["node"]:
            wc = 1.5 if t - ct <= W + 2 else 4.0
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (2, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is not None:
                    if dur <= eo <= fr:
                        res.append((wc, (2, node, fr, eo, gaps, ct, imp, lt, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo, eo, gaps, ct, imp, lt, at)))
            elif ty == "commit":
                if eo is not None and eo >= dur:
                    res.append((wc + 0.5, (3, node, eo, eo, (), ct, imp, t, at)))
            elif ty == "abort":
                res.append((wc + 0.5, (4, node, fr, dur, gaps, ct, imp, t, at)))
        ns = (1, e["node"], dur, dur, (), ct, True, t, t)
        for c, s2 in _act_opts(ns, e):
            res.append((c + 3.0, s2))
        return res
    if st in (3, 4):
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        if ty == "recover" or node != e["node"]:
            return res
        t = e["t"]
        eo = e["off"]
        wc = 1.5 if t - lt <= W + 2 else 4.0
        if st == 3:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo + L <= fr:
                    res.append((wc, s))
            elif ty == "checkpoint":
                if eo is None or eo <= fr:
                    res.append((wc, s))
        else:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (4, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is None:
                    res.append((wc + 1.0, s))
                elif dur <= eo <= fr:
                    res.append((wc, (4, node, fr, eo, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo, eo, gaps, ct, imp, lt, at)))
                else:
                    res.append((wc + 1.0, s))
    return res


def _build_anchors(events, sidx, S):
    anc = [[] for _ in range(S)]
    for e in events:
        if e["sid"] is None or e["type"] in ("open", "crash"):
            continue
        anc[sidx[e["sid"]]].append((e["t"], e["type"], e["off"], e["len"], e["node"]))
    for k in range(S):
        anc[k].sort(key=lambda a: a[0])
    anc_t = [[a[0] for a in anc[k]] for k in range(S)]
    crashes = {}
    for e in events:
        if e["type"] == "crash":
            crashes.setdefault(e["node"], []).append(e["t"])
    for nd in crashes:
        crashes[nd].sort()
    return anc, anc_t, crashes


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    anc, anc_t, crashes = _build_anchors(events, sidx, S)

    def crashed(nd, a, b):
        lst = crashes.get(nd)
        if not lst:
            return False
        j = bisect.bisect_right(lst, a)
        return j < len(lst) and lst[j] < b

    def in_gaps(gaps, o):
        for (a, b) in gaps:
            if a <= o < b:
                return True
        return False

    def anc_adj(k, t, s2):
        if s2[0] != 1:
            return 0.0
        lst = anc[k]
        if not lst:
            return 0.0
        ts = anc_t[k]
        adj = 0.0
        nd2 = s2[1]
        fr2 = s2[2]
        j = bisect.bisect_right(ts, t)
        if j < len(lst):
            a = lst[j]
            if a[0] - t <= 3 * W and a[4] == nd2 and a[2] is not None:
                if a[1] in ("write", "checkpoint", "commit") and a[2] == fr2:
                    adj -= 0.6
        j2 = bisect.bisect_right(ts, t + W)
        if j2 < len(lst):
            a = lst[j2]
            if not crashed(nd2, t - W, a[0] + W):
                if a[4] != nd2:
                    if a[1] != "recover":
                        adj += 1.5
                elif a[1] in ("write", "checkpoint", "commit") and a[2] is not None:
                    if a[2] < fr2 and not in_gaps(s2[4], a[2]):
                        adj += 2.0
        return adj

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 48
    elif nev < 400:
        BW = 28
    else:
        BW = 18
    LIMIT = 0.75
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        c += anc_adj(k, t, s2)
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[str(events[p]["i"])] = sids[k]
    for e in events:
        if e["type"] != "crash" and e["sid"] is None and str(e["i"]) not in assign:
            assign[str(e["i"])] = sids[0]
    sessions = {}
    for k, s in enumerate(best[1]):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

import time
import bisect

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, ct, imp, lt, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, t, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], ct, imp, t, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), ct, imp, t, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, ct, imp, t, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, ct, imp, t, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, ct, False, t, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _opts_for(s, e, W):
    st = s[0]
    ty = e["type"]
    if st == 1:
        if s[1] == e["node"]:
            return _act_opts(s, e)
        return []
    res = []
    if st == 2:
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        t = e["t"]
        eo = e["off"]
        if ty == "recover":
            if eo is None:
                res.append((0.5, (1, e["node"], dur, dur, (), ct, False, t, t)))
            else:
                if eo == dur:
                    c = 0.0
                elif dur < eo <= fr:
                    c = 1.0
                elif eo > fr:
                    c = 3.0
                else:
                    c = 5.0
                res.append((c, (1, e["node"], eo, eo, (), ct, False, t, t)))
            return res
        if node == e["node"]:
            wc = 1.5 if t - ct <= W + 2 else 4.0
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (2, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is not None:
                    if dur <= eo <= fr:
                        res.append((wc, (2, node, fr, eo, gaps, ct, imp, lt, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo, eo, gaps, ct, imp, lt, at)))
            elif ty == "commit":
                if eo is not None and eo >= dur:
                    res.append((wc + 0.5, (3, node, eo, eo, (), ct, imp, t, at)))
            elif ty == "abort":
                res.append((wc + 0.5, (4, node, fr, dur, gaps, ct, imp, t, at)))
        ns = (1, e["node"], dur, dur, (), ct, True, t, t)
        for c, s2 in _act_opts(ns, e):
            res.append((c + 3.0, s2))
        return res
    if st in (3, 4):
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        if ty == "recover" or node != e["node"]:
            return res
        t = e["t"]
        eo = e["off"]
        wc = 1.5 if t - lt <= W + 2 else 4.0
        if st == 3:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo + L <= fr:
                    res.append((wc, s))
            elif ty == "checkpoint":
                if eo is None or eo <= fr:
                    res.append((wc, s))
        else:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (4, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is None:
                    res.append((wc + 1.0, s))
                elif dur <= eo <= fr:
                    res.append((wc, (4, node, fr, eo, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo, eo, gaps, ct, imp, lt, at)))
                else:
                    res.append((wc + 1.0, s))
    return res


def _build_anchors(events, sidx, S):
    anc = [[] for _ in range(S)]
    for e in events:
        if e["sid"] is None or e["type"] in ("open", "crash"):
            continue
        anc[sidx[e["sid"]]].append((e["t"], e["type"], e["off"], e["len"], e["node"]))
    for k in range(S):
        anc[k].sort(key=lambda a: a[0])
    anc_t = [[a[0] for a in anc[k]] for k in range(S)]
    crashes = {}
    for e in events:
        if e["type"] == "crash":
            crashes.setdefault(e["node"], []).append(e["t"])
    for nd in crashes:
        crashes[nd].sort()
    return anc, anc_t, crashes


def _make_replay(events, dup_prev, hint, W, D, RW):
    crash_pos = [p for p, e in enumerate(events) if e["type"] == "crash"]

    def replay(k, plist, memb):
        seq = []
        i = 0
        j = 0
        n1 = len(plist)
        n2 = len(crash_pos)
        while i < n1 or j < n2:
            if j >= n2 or (i < n1 and plist[i] < crash_pos[j]):
                seq.append(plist[i])
                i += 1
            else:
                seq.append(crash_pos[j])
                j += 1
        base = 0.0
        hyps = [(0.0, (0, None, 0, 0, (), NEG, False, 0, 0))]
        lastcrash = {}
        for p in seq:
            e = events[p]
            ty = e["type"]
            t = e["t"]
            nd = e["node"]
            nh = []
            if ty == "crash":
                lastcrash[nd] = t
                for (c, s) in hyps:
                    if s[0] == 1 and s[1] == nd:
                        nh.append((c, (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])))
                        if t - s[8] <= W:
                            nh.append((c + 2.0, s))
                    else:
                        nh.append((c, s))
            elif ty == "open":
                lc = lastcrash.get(nd)
                for (c, s) in hyps:
                    if s[0] != 0:
                        nh.append((c + 12.0, s))
                        continue
                    nh.append((c, (1, nd, 0, 0, (), NEG, False, t, t)))
                    if lc is not None and t - lc <= W:
                        nh.append((c + 2.5, (2, nd, 0, 0, (), lc, False, t, t)))
            else:
                if e["sid"] is None and hint[p] is not None and hint[p] != k:
                    base += 4.0
                dupc = None
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        if q in memb:
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            if dupc is None or dc < dupc:
                                dupc = dc
                for (c, s) in hyps:
                    any_ = False
                    if dupc is not None:
                        nh.append((c + dupc, s))
                        any_ = True
                    if s[0] != 0:
                        for c2, s2 in _opts_for(s, e, W):
                            nh.append((c + c2, s2))
                            any_ = True
                    if not any_:
                        nh.append((c + 12.0, s))
            nh.sort(key=lambda h: h[0])
            seen = set()
            hyps = []
            for h in nh:
                key = h[1][:7]
                if key in seen:
                    continue
                seen.add(key)
                hyps.append(h)
                if len(hyps) >= RW:
                    break
        return (hyps[0][0] + base, hyps[0][1])

    return replay


def _refine(events, owner, final_states, S, dup_prev, hint, W, D, t0):
    BUDGET = 0.88
    nev = len(events)
    replay = _make_replay(events, dup_prev, hint, W, D, 6)
    plists = [[] for _ in range(S)]
    for p in range(nev):
        if owner[p] is not None and events[p]["type"] != "crash":
            plists[owner[p]].append(p)
    memb = [set(pl) for pl in plists]
    cost = [0.0] * S
    fstate = list(final_states)
    for k in range(S):
        if time.process_time() - t0 > BUDGET:
            return owner, final_states
        c, s = replay(k, plists[k], memb[k])
        cost[k] = c
        fstate[k] = s
    anon = [p for p in range(nev) if events[p]["sid"] is None and events[p]["type"] != "crash"]
    rad = max(40, 4 * W)

    def cands_for(p):
        e = events[p]
        t = e["t"]
        res = []
        for k in range(S):
            if k == owner[p]:
                continue
            pl = plists[k]
            if not pl:
                continue
            if events[pl[0]]["t"] > t + W:
                continue
            if e["type"] == "recover":
                res.append(k)
                continue
            ts = [events[q]["t"] for q in pl]
            a = bisect.bisect_left(ts, t - rad)
            b = bisect.bisect_right(ts, t + rad)
            for q in pl[a:b]:
                if events[q]["node"] == e["node"]:
                    res.append(k)
                    break
        return res

    def without(pl, p):
        j = bisect.bisect_left(pl, p)
        return pl[:j] + pl[j + 1:]

    def withp(pl, p):
        j = bisect.bisect_left(pl, p)
        return pl[:j] + [p] + pl[j:]

    out_of_time = False
    for it in range(4):
        improved = False
        for p in anon:
            if time.process_time() - t0 > BUDGET:
                out_of_time = True
                break
            cl = cands_for(p)
            if not cl:
                continue
            a = owner[p]
            pa = without(plists[a], p)
            ma = memb[a] - {p}
            ca, sa = replay(a, pa, ma)
            bestd = -1e-6
            bestm = None
            for b in cl:
                pb = withp(plists[b], p)
                mb = memb[b] | {p}
                cb, sb = replay(b, pb, mb)
                d = (ca + cb) - (cost[a] + cost[b])
                if d < bestd:
                    bestd = d
                    bestm = (b, pb, mb, cb, sb)
            if bestm is not None:
                b, pb, mb, cb, sb = bestm
                plists[a] = pa
                memb[a] = ma
                cost[a] = ca
                fstate[a] = sa
                plists[b] = pb
                memb[b] = mb
                cost[b] = cb
                fstate[b] = sb
                owner[p] = b
                improved = True
        if out_of_time or not improved:
            break
    return owner, fstate


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
