                    lb = list(lists[b])
                    lb.remove(q)
                    bisect.insort(lb, p)
                    ra2 = replay(a, la2)
                    rb = replay(b, lb)
                    d = ra2[0] + rb[0] - base_a - cache[b][0]
                    if d < bestd:
                        bestd = d
                        best = (b, la2, lb, ra2, rb, q)
            if best is not None:
                b, nla, nlb, nra, nrb, q = best
                lists[a] = nla
                lists[b] = nlb
                cache[a] = nra
                cache[b] = nrb
                assign[p] = b
                if q is not None:
                    assign[q] = a
                touched.add(a)
                touched.add(b)
                improved = True
        return improved

    def block_pass():
        improved = False
        order_s = sorted(range(S), key=lambda k: (-cache[k][0], k))
        for a in order_s:
            if flags["timeout"]:
                break
            if cache[a][0] <= 0.9:
                continue
            bynode = {}
            for p in lists[a]:
                if anon[p]:
                    bynode.setdefault(events[p]["node"], []).append(p)
            done = False
            for nd in sorted(bynode.keys()):
                if done or flags["timeout"]:
                    break
                seq = bynode[nd]
                n = len(seq)
                for i in range(n):
                    if out_of_time():
                        break
                    base_a = cache[a][0]
                    best = None
                    bestd = -1e-9
                    segs = []
                    for L in (2, 3, 5):
                        if i + L <= n:
                            segs.append(seq[i:i + L])
                    if n - i >= 2 and (n - i) not in (2, 3, 5):
                        segs.append(seq[i:])
                    cands = nearby_sessions(a, seq[i:i + 2], nd, False)
                    if not cands:
                        continue
                    for seg in segs:
                        if out_of_time():
                            break
                        segset = set(seg)
                        la = [x for x in lists[a] if x not in segset]
                        ra = replay(a, la)
                        for b in cands:
                            lb = sorted(lists[b] + seg)
                            rb = replay(b, lb)
                            d = ra[0] + rb[0] - base_a - cache[b][0]
                            if d < bestd:
                                bestd = d
                                best = (b, la, lb, ra, rb, seg, [])
                    tc = times[seq[i]]
                    asuf = seq[i:]
                    aset = set(asuf)
                    for b in cands:
                        if out_of_time():
                            break
                        bsuf = [q for q in lists[b]
                                if anon[q] and events[q]["node"] == nd and times[q] >= tc]
                        if not bsuf:
                            continue
                        bset = set(bsuf)
                        la = sorted([x for x in lists[a] if x not in aset] + bsuf)
                        lb = sorted([x for x in lists[b] if x not in bset] + asuf)
                        ra = replay(a, la)
                        rb = replay(b, lb)
                        d = ra[0] + rb[0] - base_a - cache[b][0]
                        if d < bestd:
                            bestd = d
                            best = (b, la, lb, ra, rb, asuf, bsuf)
                    if best is not None:
                        b, nla, nlb, nra, nrb, moved_a, moved_b = best
                        lists[a] = nla
                        lists[b] = nlb
                        cache[a] = nra
                        cache[b] = nrb
                        for x in moved_a:
                            assign[x] = b
                        for x in moved_b:
                            assign[x] = a
                        touched.add(a)
                        touched.add(b)
                        improved = True
                        done = True
                        break
        return improved

    HW = max(10, 2 * W)
    MAXR = 7
    MAXA = 6
    lns_tried = set()

    def recreate(aff, base_lists, base_cache, order, regret):
        cl = dict((k, list(v)) for k, v in base_lists.items())
        cc = dict(base_cache)
        ass = {}
        pending = list(order)
        while pending:
            if out_of_time():
                return None
            if regret and len(pending) > 1:
                # evaluate all pending, choose event with max regret
                pick = None
                for q in pending:
                    opts = []
                    for k in aff:
                        lk = list(cl[k])
                        bisect.insort(lk, q)
                        r = replay(k, lk)
                        opts.append((r[0] - cc[k][0], k, lk, r))
                    opts.sort(key=lambda x: (x[0], x[1]))
                    rg = (opts[1][0] - opts[0][0]) if len(opts) > 1 else 0.0
                    if pick is None or rg > pick[0] + 1e-9:
                        pick = (rg, q, opts[0])
                rg, q, bo = pick
                pending.remove(q)
            else:
                q = pending.pop(0)
                bo = None
                for k in aff:
                    lk = list(cl[k])
                    bisect.insort(lk, q)
                    r = replay(k, lk)
                    d = r[0] - cc[k][0]
                    if bo is None or d < bo[0]:
                        bo = (d, k, lk, r)
            d, k, lk, r = bo
            cl[k] = lk
            cc[k] = r
            ass[q] = k
        return cl, cc, ass

    def lns_pass():
        improved = False
        order_s = sorted(range(S), key=lambda k: (-cache[k][0], k))
        for a in order_s:
            if flags["timeout"]:
                break
            if cache[a][0] <= 0.9:
                continue
            seeds = [p for p in lists[a] if anon[p]]
            for p in seeds:
                if out_of_time():
                    break
                if assign[p] != a:
                    continue
                key = (a, p, round(cache[a][0], 3))
                if key in lns_tried:
                    continue
                lns_tried.add(key)
                nd = events[p]["node"]
                t = times[p]
                lo = bisect.bisect_left(times, t - HW)
                hi = bisect.bisect_right(times, t + HW)
                ruin = [q for q in range(lo, hi) if anon[q] and events[q]["node"] == nd]
                if len(ruin) > MAXR:
                    ruin = sorted(ruin, key=lambda q: (abs(times[q] - t), q))[:MAXR]
                    ruin.sort()
                if len(ruin) < 2:
                    continue
                aff = []
                for q in ruin:
                    if assign[q] not in aff:
                        aff.append(assign[q])
                anyrec = any(events[q]["type"] == "recover" for q in ruin)
                for b in nearby_sessions(a, ruin, nd, anyrec):
                    if len(aff) >= MAXA:
                        break
                    if b not in aff:
                        aff.append(b)
                if len(aff) < 2:
                    continue
                old = sum(cache[k][0] for k in aff)
                rset = set(ruin)
                base_lists = {}
                base_cache = {}
                for k in aff:
                    bl = [x for x in lists[k] if x not in rset]
                    base_lists[k] = bl
                    base_cache[k] = replay(k, bl) if len(bl) != len(lists[k]) else cache[k]
                best = None
                bestt = old - 1e-6
                variants = [(ruin, False), (ruin[::-1], False)]
                if len(ruin) <= 5:
                    variants.append((ruin, True))
                for order, rg in variants:
                    res = recreate(aff, base_lists, base_cache, order, rg)
                    if res is None:
                        break
                    tot = sum(res[1][k][0] for k in aff)
                    if tot < bestt:
                        bestt = tot
                        best = res
                if best is not None:
                    cl, cc, ass = best
                    for k in aff:
                        lists[k] = cl[k]
                        cache[k] = cc[k]
                        touched.add(k)
                    for q, k in ass.items():
                        assign[q] = k
                    improved = True
        return improved

    rounds = 0
    while rounds < 10 and not flags["timeout"]:
        rounds += 1
        i1 = single_pass()
        i2 = False
        i3 = False
        if not flags["timeout"]:
            i2 = block_pass()
        if not flags["timeout"]:
            i3 = lns_pass()
        if not (i1 or i2 or i3):
            break

    final_states = list(init_states)
    for k in touched:
        s = cache[k][1]
        if s is not None:
            final_states[k] = s
    return assign, final_states


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 40
    elif nev < 400:
        BW = 22
    else:
        BW = 14
    LIMIT = 0.45
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    assign = [None] * nev
    for p, e in enumerate(events):
        if e["type"] == "crash":
            continue
        if e["sid"] is not None:
            assign[p] = sidx[e["sid"]]
        else:
            assign[p] = 0
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        assign[p] = k
    final_states = list(best[1])

    try:
        if time.process_time() - t0 < 0.82:
            a2, f2 = _refine(events, S, W, D, hint, lastT, list(assign), final_states, t0, 0.9)
            assign = a2
            final_states = f2
    except Exception:
        pass

    out_assign = {}
    for p, e in enumerate(events):
        if e["type"] != "crash" and e["sid"] is None:
            k = assign[p] if assign[p] is not None else 0
            out_assign[str(e["i"])] = sids[k]
    sessions = {}
    for k, s in enumerate(final_states):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": out_assign, "sessions": sessions}
    return state

import time
import bisect

ST_NAMES = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
NEG = -10 ** 9


def _est_window(events):
    seen = {}
    best = 0
    for e in events:
        if e.get("sid") is None or e.get("type") not in ("write", "checkpoint", "commit"):
            continue
        if e.get("off") is None:
            continue
        lst = seen.setdefault(e["sid"], [])
        for (t0, o0) in lst[-8:]:
            if o0 > e["off"] and e["t"] - t0 < 25:
                best = max(best, e["t"] - t0)
        lst.append((e["t"], e["off"]))
    return max(3, best + 2)


def _fallback(state):
    inp = state.get("input") or {}
    events = inp.get("events") or []
    sids = []
    first_on = {}
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
        if e.get("type") == "open" and e.get("sid") is not None:
            first_on.setdefault(e.get("node"), e["sid"])
    assign = {}
    for p, e in enumerate(events):
        if e.get("type") != "crash" and e.get("sid") is None:
            assign[str(e.get("i", p))] = first_on.get(e.get("node"), sids[0] if sids else "")
    sessions = {s: {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _solve(state)
    except Exception:
        return _fallback(state)


def _addgap(gaps, a, b):
    ng = gaps + ((a, b),)
    if len(ng) > 4:
        ng = ng[-4:]
    return ng


def _fill(gaps, eo, L):
    for gi in range(len(gaps)):
        a, b = gaps[gi]
        if a <= eo and eo + L <= b:
            pieces = []
            if a < eo:
                pieces.append((a, eo))
            if eo + L < b:
                pieces.append((eo + L, b))
            ng = gaps[:gi] + tuple(pieces) + gaps[gi + 1:]
            if not pieces:
                c = -2.5
            elif a == eo or eo + L == b:
                c = 0.0
            else:
                c = 0.8
            return (c, ng)
    return None


def _act_opts(s, e):
    st, node, fr, dur, gaps, ct, imp, lt, at = s
    ty = e["type"]
    t = e["t"]
    eo = e["off"]
    res = []
    if ty == "write":
        L = e["len"] or 0
        if eo is None:
            res.append((1.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (1, node, fr + L, dur, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (1, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, t, at)))
        else:
            f = _fill(gaps, eo, L)
            if f is not None:
                res.append((f[0], (1, node, fr, dur, f[1], ct, imp, t, at)))
            elif eo >= dur:
                res.append((5.0, s))
    elif ty in ("checkpoint", "commit"):
        com = (ty == "commit")
        nst = 3 if com else 1
        if eo is None:
            res.append((1.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo == fr:
            res.append((0.0, (nst, node, fr, fr, gaps, ct, imp, t, at)))
        elif eo > fr:
            res.append((3.0, (nst, node, eo, eo, _addgap(gaps, fr, eo), ct, imp, t, at)))
        elif eo >= dur:
            if com:
                res.append((1.5, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((1.0, (1, node, fr, eo, gaps, ct, imp, t, at)))
        else:
            if com:
                res.append((6.0, (3, node, eo, eo, (), ct, imp, t, at)))
            else:
                res.append((4.0, s))
    elif ty == "abort":
        gap = max(0, t - lt)
        res.append((0.3 + 0.02 * min(gap, 60), (4, node, fr, dur, gaps, ct, imp, t, at)))
    elif ty == "recover":
        if eo is not None:
            if imp and eo == dur:
                res.append((-2.5, (1, node, fr, dur, gaps, ct, False, t, at)))
            elif (not imp) and dur <= eo <= fr:
                res.append((2.5, s))
    return res


def _opts_for(s, e, W):
    st = s[0]
    ty = e["type"]
    if st == 1:
        if s[1] == e["node"]:
            return _act_opts(s, e)
        return []
    res = []
    if st == 2:
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        t = e["t"]
        eo = e["off"]
        if ty == "recover":
            if eo is None:
                res.append((0.5, (1, e["node"], dur, dur, (), ct, False, t, t)))
            else:
                if eo == dur:
                    c = 0.0
                elif dur < eo <= fr:
                    c = 1.0
                elif eo > fr:
                    c = 3.0
                else:
                    c = 5.0
                res.append((c, (1, e["node"], eo, eo, (), ct, False, t, t)))
            return res
        if node == e["node"]:
            wc = 1.5 if t - ct <= W + 2 else 4.0
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (2, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (2, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (2, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is not None:
                    if dur <= eo <= fr:
                        res.append((wc, (2, node, fr, eo, gaps, ct, imp, lt, at)))
                    elif eo > fr:
                        res.append((wc + 3.0, (2, node, eo, eo, gaps, ct, imp, lt, at)))
            elif ty == "commit":
                if eo is not None and eo >= dur:
                    res.append((wc + 0.5, (3, node, eo, eo, (), ct, imp, t, at)))
            elif ty == "abort":
                res.append((wc + 0.5, (4, node, fr, dur, gaps, ct, imp, t, at)))
        ns = (1, e["node"], dur, dur, (), ct, True, t, t)
        for c, s2 in _act_opts(ns, e):
            res.append((c + 3.0, s2))
        return res
    if st in (3, 4):
        _, node, fr, dur, gaps, ct, imp, lt, at = s
        if ty == "recover" or node != e["node"]:
            return res
        t = e["t"]
        eo = e["off"]
        wc = 1.5 if t - lt <= W + 2 else 4.0
        if st == 3:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo + L <= fr:
                    res.append((wc, s))
            elif ty == "checkpoint":
                if eo is None or eo <= fr:
                    res.append((wc, s))
        else:
            if ty == "write":
                L = e["len"] or 0
                if eo is None:
                    res.append((wc + 1.0, s))
                elif eo == fr:
                    res.append((wc, (4, node, fr + L, dur, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo + L, dur, _addgap(gaps, fr, eo), ct, imp, lt, at)))
                else:
                    f = _fill(gaps, eo, L)
                    if f is not None:
                        res.append((wc + max(f[0], -1.0), (4, node, fr, dur, f[1], ct, imp, lt, at)))
            elif ty == "checkpoint":
                if eo is None:
                    res.append((wc + 1.0, s))
                elif dur <= eo <= fr:
                    res.append((wc, (4, node, fr, eo, gaps, ct, imp, lt, at)))
                elif eo > fr:
                    res.append((wc + 3.0, (4, node, eo, eo, gaps, ct, imp, lt, at)))
                else:
                    res.append((wc + 1.0, s))
    return res


def _build_anchors(events, sidx, S):
    anc = [[] for _ in range(S)]
    for e in events:
        if e["sid"] is None or e["type"] in ("open", "crash"):
            continue
        anc[sidx[e["sid"]]].append((e["t"], e["type"], e["off"], e["len"], e["node"]))
    for k in range(S):
        anc[k].sort(key=lambda a: a[0])
    anc_t = [[a[0] for a in anc[k]] for k in range(S)]
    crashes = {}
    for e in events:
        if e["type"] == "crash":
            crashes.setdefault(e["node"], []).append(e["t"])
    for nd in crashes:
        crashes[nd].sort()
    return anc, anc_t, crashes


def _make_replay(events, dup_prev, hint, W, D, RW):
    crash_pos = [p for p, e in enumerate(events) if e["type"] == "crash"]

    def replay(k, plist, memb):
        seq = []
        i = 0
        j = 0
        n1 = len(plist)
        n2 = len(crash_pos)
        while i < n1 or j < n2:
            if j >= n2 or (i < n1 and plist[i] < crash_pos[j]):
                seq.append(plist[i])
                i += 1
            else:
                seq.append(crash_pos[j])
                j += 1
        base = 0.0
        hyps = [(0.0, (0, None, 0, 0, (), NEG, False, 0, 0))]
        lastcrash = {}
        for p in seq:
            e = events[p]
            ty = e["type"]
            t = e["t"]
            nd = e["node"]
            nh = []
            if ty == "crash":
                lastcrash[nd] = t
                for (c, s) in hyps:
                    if s[0] == 1 and s[1] == nd:
                        nh.append((c, (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])))
                        if t - s[8] <= W:
                            nh.append((c + 2.0, s))
                    else:
                        nh.append((c, s))
            elif ty == "open":
                lc = lastcrash.get(nd)
                for (c, s) in hyps:
                    if s[0] != 0:
                        nh.append((c + 12.0, s))
                        continue
                    nh.append((c, (1, nd, 0, 0, (), NEG, False, t, t)))
                    if lc is not None and t - lc <= W:
                        nh.append((c + 2.5, (2, nd, 0, 0, (), lc, False, t, t)))
            else:
                if e["sid"] is None and hint[p] is not None and hint[p] != k:
                    base += 4.0
                dupc = None
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        if q in memb:
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            if dupc is None or dc < dupc:
                                dupc = dc
                for (c, s) in hyps:
                    any_ = False
                    if dupc is not None:
                        nh.append((c + dupc, s))
                        any_ = True
                    if s[0] != 0:
                        for c2, s2 in _opts_for(s, e, W):
                            nh.append((c + c2, s2))
                            any_ = True
                    if not any_:
                        nh.append((c + 12.0, s))
            nh.sort(key=lambda h: h[0])
            seen = set()
            hyps = []
            for h in nh:
                key = h[1][:7]
                if key in seen:
                    continue
                seen.add(key)
                hyps.append(h)
                if len(hyps) >= RW:
                    break
        return (hyps[0][0] + base, hyps[0][1])

    return replay


def _refine(events, owner, S, dup_prev, hint, W, D, t0, budget):
    nev = len(events)
    replay = _make_replay(events, dup_prev, hint, W, D, 6)
    plists = [[] for _ in range(S)]
    for p in range(nev):
        if owner[p] is not None and events[p]["type"] != "crash":
            plists[owner[p]].append(p)
    memb = [set(pl) for pl in plists]
    cost = [0.0] * S
    fstate = [None] * S
    touched = set()
    for k in range(S):
        if time.process_time() - t0 > budget:
            return owner, fstate, set()
        c, s = replay(k, plists[k], memb[k])
        cost[k] = c
        fstate[k] = s
    anon = [p for p in range(nev) if events[p]["sid"] is None and events[p]["type"] != "crash"]
    rad = max(40, 4 * W)
    ptimes = [[events[q]["t"] for q in pl] for pl in plists]

    def cands_for(p):
        e = events[p]
        t = e["t"]
        res = []
        for k in range(S):
            if k == owner[p]:
                continue
            pl = plists[k]
            if not pl:
                continue
            if events[pl[0]]["t"] > t + W:
                continue
            if e["type"] == "recover":
                res.append(k)
                continue
            ts = ptimes[k]
            a = bisect.bisect_left(ts, t - rad)
            b = bisect.bisect_right(ts, t + rad)
            for q in pl[a:b]:
                if events[q]["node"] == e["node"]:
                    res.append(k)
                    break
        return res

    def without(pl, p):
        j = bisect.bisect_left(pl, p)
        return pl[:j] + pl[j + 1:]

    def withp(pl, p):
        j = bisect.bisect_left(pl, p)
        return pl[:j] + [p] + pl[j:]

    out_of_time = False
    for it in range(4):
        improved = False
        for p in anon:
            if time.process_time() - t0 > budget:
                out_of_time = True
                break
            cl = cands_for(p)
            if not cl:
                continue
            a = owner[p]
            pa = without(plists[a], p)
            ma = memb[a] - {p}
            ca, sa = replay(a, pa, ma)
            bestd = -0.25
            bestm = None
            for b in cl:
                if time.process_time() - t0 > budget:
                    out_of_time = True
                    break
                pb = withp(plists[b], p)
                mb = memb[b] | {p}
                cb, sb = replay(b, pb, mb)
                d = (ca + cb) - (cost[a] + cost[b])
                if d < bestd:
                    bestd = d
                    bestm = (b, pb, mb, cb, sb)
            if out_of_time:
                break
            if bestm is not None:
                b, pb, mb, cb, sb = bestm
                plists[a] = pa
                memb[a] = ma
                cost[a] = ca
                fstate[a] = sa
                ptimes[a] = [events[q]["t"] for q in pa]
                plists[b] = pb
                memb[b] = mb
                cost[b] = cb
                fstate[b] = sb
                ptimes[b] = [events[q]["t"] for q in pb]
                owner[p] = b
                touched.add(a)
                touched.add(b)
                improved = True
        if out_of_time or not improved:
            break
    return owner, fstate, touched


def _solve(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    S = len(sids)
    if S == 0:
        return _fallback(state)
    sidx = {s: k for k, s in enumerate(sids)}
    W = _est_window(events) + 2
    nev = len(events)

    anc, anc_t, crashes = _build_anchors(events, sidx, S)

    def crashed(nd, a, b):
        lst = crashes.get(nd)
        if not lst:
            return False
        j = bisect.bisect_right(lst, a)
        return j < len(lst) and lst[j] < b

    def in_gaps(gaps, o):
        for (a, b) in gaps:
            if a <= o < b:
                return True
        return False

    def anc_adj(k, t, s2):
        if s2[0] != 1:
            return 0.0
        lst = anc[k]
        if not lst:
            return 0.0
        ts = anc_t[k]
        adj = 0.0
        nd2 = s2[1]
        fr2 = s2[2]
        j = bisect.bisect_right(ts, t)
        if j < len(lst):
            a = lst[j]
            if a[0] - t <= 3 * W and a[4] == nd2 and a[2] is not None:
                if a[1] in ("write", "checkpoint", "commit") and a[2] == fr2:
                    adj -= 0.6
        j2 = bisect.bisect_right(ts, t + W)
        if j2 < len(lst):
            a = lst[j2]
            if not crashed(nd2, t - W, a[0] + W):
                if a[4] != nd2:
                    if a[1] != "recover":
                        adj += 1.5
                elif a[1] in ("write", "checkpoint", "commit") and a[2] is not None:
                    if a[2] < fr2 and not in_gaps(s2[4], a[2]):
                        adj += 2.0
        return adj

    sig_hist = {}
    dup_prev = [None] * nev
    for p, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sg = (e["node"], e["type"], e["off"], e["len"])
        lst = sig_hist.setdefault(sg, [])
        if lst:
            dup_prev[p] = list(lst[-3:])
        lst.append(p)

    dd = []
    for p in range(nev):
        if dup_prev[p] and events[p]["sid"] is not None:
            for q in dup_prev[p]:
                if events[q]["sid"] == events[p]["sid"]:
                    dd.append(events[p]["t"] - events[q]["t"])
    if dd:
        dd.sort()
        med = dd[len(dd) // 2]
        lim = 3 * med + W
        D = max([x for x in dd if x <= lim] or [12]) + W
    else:
        D = 12 + W

    need_track = set()
    for p in range(nev):
        if dup_prev[p]:
            for q in dup_prev[p]:
                need_track.add(q)
    track_sorted = sorted(need_track)
    hint = [None] * nev
    for p, e in enumerate(events):
        if e["sid"] is not None and dup_prev[p]:
            for q in dup_prev[p]:
                if events[q]["sid"] is None and hint[q] is None:
                    hint[q] = sidx[e["sid"]]

    lastT = [NEG] * S
    for p, e in enumerate(events):
        if e["sid"] is not None and e["type"] not in ("open", "crash") and not dup_prev[p]:
            k = sidx[e["sid"]]
            if e["t"] > lastT[k]:
                lastT[k] = e["t"]

    init = tuple((0, None, 0, 0, (), NEG, False, 0, 0) for _ in range(S))
    beam = [(0.0, init, {}, None)]
    if nev < 200:
        BW = 48
    elif nev < 400:
        BW = 28
    else:
        BW = 18
    LIMIT = 0.60
    lastcrash = {}
    win2 = 2 * D + W

    for p, e in enumerate(events):
        ty = e["type"]
        el = time.process_time() - t0
        if el > LIMIT:
            BW = 1
            beam = beam[:1]
        elif p > 15 and BW > 6:
            proj = el / p * (nev - p)
            if proj > (LIMIT - el):
                BW = max(6, int(BW * 0.8))
        t = e["t"]
        nd = e["node"]
        newb = []
        if ty == "crash":
            lastcrash[nd] = t
            for (cost, ss, dm, ch) in beam:
                variants = [(cost, list(ss))]
                for k in range(S):
                    s = ss[k]
                    if s[0] == 1 and s[1] == nd:
                        down = (2, nd, s[2], s[3], s[4], t, False, s[7], s[8])
                        nv = []
                        for (c, lst) in variants:
                            if t - s[8] <= W and len(variants) < 8 and BW > 1:
                                l2 = list(lst)
                                l2[k] = down
                                nv.append((c, l2))
                                nv.append((c + 2.0, lst))
                            else:
                                lst[k] = down
                                nv.append((c, lst))
                        variants = nv
                for (c, lst) in variants:
                    newb.append((c, tuple(lst), dm, ch))
        elif ty == "open":
            k = sidx[e["sid"]]
            lc = lastcrash.get(nd)
            for (cost, ss, dm, ch) in beam:
                if ss[k][0] != 0:
                    newb.append((cost, ss, dm, ch))
                    continue
                dm2 = dm
                if p in need_track:
                    dm2 = dict(dm)
                    dm2[p] = k
                lst = list(ss)
                lst[k] = (1, nd, 0, 0, (), NEG, False, t, t)
                newb.append((cost, tuple(lst), dm2, ch))
                if lc is not None and t - lc <= W and BW > 1:
                    l2 = list(ss)
                    l2[k] = (2, nd, 0, 0, (), lc, False, t, t)
                    newb.append((cost + 2.5, tuple(l2), dm2, ch))
        else:
            known = sidx[e["sid"]] if e["sid"] is not None else None
            cands = [known] if known is not None else list(range(S))
            hp = hint[p]
            for (cost, ss, dm, ch) in beam:
                produced = []
                if dup_prev[p]:
                    for q in dup_prev[p]:
                        k = dm.get(q)
                        if k is not None and (known is None or k == known):
                            dc = 1.0 if t - events[q]["t"] <= D else 3.0
                            produced.append((dc, k, ss))
                for k in cands:
                    s = ss[k]
                    st = s[0]
                    if st == 0:
                        continue
                    if st == 1:
                        if s[1] != nd:
                            continue
                    elif st >= 3:
                        if s[1] != nd or ty == "recover":
                            continue
                    for c, s2 in _opts_for(s, e, W):
                        if known is None and hp is not None and hp != k:
                            c += 4.0
                        if s2[0] >= 3 and st < 3 and lastT[k] > t + W:
                            c += 4.0
                        c += anc_adj(k, t, s2)
                        lst = list(ss)
                        lst[k] = s2
                        produced.append((c, k, tuple(lst)))
                if not produced:
                    fs = None
                    if known is not None:
                        fs = known
                    else:
                        if hp is not None:
                            fs = hp
                        else:
                            for si in range(S):
                                if ss[si][0] != 0 and ss[si][1] == nd:
                                    fs = si
                                    break
                            if fs is None:
                                for si in range(S):
                                    if ss[si][0] != 0:
                                        fs = si
                                        break
                    if fs is None:
                        fs = 0
                    produced.append((12.0, fs, ss))
                for (c, k, nss) in produced:
                    dm2 = dm
                    if p in need_track:
                        dm2 = dict(dm)
                        dm2[p] = k
                    nch = (p, k, ch) if known is None else ch
                    newb.append((cost + c, nss, dm2, nch))
        newb.sort(key=lambda h: h[0])
        recent = [q for q in track_sorted if q <= p and events[q]["t"] >= t - win2]
        seen = set()
        beam = []
        for h in newb:
            dm = h[2]
            key = (tuple(x[:7] for x in h[1]),
                   tuple(dm.get(q) for q in recent) if recent else ())
            if key in seen:
                continue
            seen.add(key)
            beam.append(h)
            if len(beam) >= BW:
                break
        if not beam:
            beam = [(0.0, init, {}, None)]

    best = beam[0]
    owner = [None] * nev
    ch = best[3]
    while ch is not None:
        p, k, ch = ch
        owner[p] = k
    for p, e in enumerate(events):
        if e["type"] == "crash":
            continue
        if e["sid"] is not None:
            owner[p] = sidx[e["sid"]]
        elif owner[p] is None:
            owner[p] = 0
    final_states = list(best[1])

    try:
        o2, f2, touched = _refine(events, list(owner), S, dup_prev, hint, W, D, t0, 0.90)
        owner = o2
        for k in touched:
            if f2[k] is not None:
                final_states[k] = f2[k]
    except Exception:
        pass

    assign = {}
    for p, e in enumerate(events):
        if e["type"] != "crash" and e["sid"] is None:
            assign[str(e["i"])] = sids[owner[p]]
    sessions = {}
    for k, s in enumerate(final_states):
        st = s[0]
        dur = s[3]
        if st == 3:
            dur = s[2]
        sessions[sids[k]] = {"status": ST_NAMES[st], "durable": int(dur)}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

import bisect
import statistics

TERMINAL = ("committed", "aborted")


def _int_or_none(v):
    if v is None:
        return None
    try:
        return int(v)
    except Exception:
        try:
            return int(float(v))
        except Exception:
            return None


def _norm_events(raw):
    evs = []
    for k, e in enumerate(raw or []):
        if not isinstance(e, dict):
            continue
        i = e.get("i", k)
        t = _int_or_none(e.get("t"))
        evs.append({
            "i": i, "t": t if t is not None else 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _int_or_none(e.get("off")),
            "len": _int_or_none(e.get("len")), "sid": e.get("sid"), "k": k,
        })
    evs.sort(key=lambda e: (e["t"], e["k"]))
    for p, e in enumerate(evs):
        e["p"] = p
    return evs


def _estimate_jitter(evs, lab, crash_t):
    ts = [e["t"] for e in evs]
    diffs = [b - a for a, b in zip(ts, ts[1:]) if b > a]
    med = statistics.median(diffs) if diffs else 1
    inv = []
    for sid, lst in lab.items():
        seq = [x for x in lst if x["type"] in ("write", "checkpoint", "commit") and x["off"] is not None]
        for a in range(len(seq)):
            ea = seq[a]
            for b in range(a + 1, len(seq)):
                eb = seq[b]
                dt = eb["t"] - ea["t"]
                if dt > 60 * med:
                    break
                endb = eb["off"] + (eb["len"] or 0) if eb["type"] == "write" else eb["off"]
                enda = ea["off"] + (ea["len"] or 0) if ea["type"] == "write" else ea["off"] + 1
                if eb["type"] == "write" and endb <= ea["off"] and endb < enda:
                    if eb["off"] == ea["off"] and eb["len"] == ea["len"]:
                        continue
                    ct = crash_t.get(ea["node"], [])
                    q = bisect.bisect_left(ct, ea["t"] - 5 * med)
                    if q < len(ct) and ct[q] <= eb["t"]:
                        continue
                    inv.append(dt)
    J = 3 * med
    if inv:
        inv.sort()
        est = inv[int(0.9 * (len(inv) - 1))] * 1.2 + 1
        J = max(J, min(est, 30 * med))
    return J


def _options(s, e, J):
    st = s["status"]
    ty = e["type"]
    N = e["node"]
    t = e["t"]
    out = []
    if st == "pending":
        return out
    off = e["off"]
    ln = e["len"] if e["len"] is not None else 0
    late_crash = (s.get("crash_node") == N and s.get("crash_t") is not None
                  and t - s["crash_t"] <= J)
    pre = s.get("pre_off", -1)
    if ty == "write":
        if off is None:
            off = s["off"]
        end = off + ln
        if st == "active" and s["node"] == N:
            if off == s["off"]:
                out.append((0.0, {"off": end}, "x"))
            elif off > s["off"]:
                out.append((2.0, {"off": end, "gaps": s["gaps"] + [[s["off"], off]]}, "jump"))
            filled = False
            for gi, g in enumerate(s["gaps"]):
                if g[0] <= off and end <= g[1]:
                    ng = s["gaps"][:gi] + s["gaps"][gi + 1:]
                    if off > g[0]:
                        ng.append([g[0], off])
                    if end < g[1]:
                        ng.append([end, g[1]])
                    out.append((0.5, {"gaps": ng}, "gap"))
                    filled = True
                    break
            if off < s["off"] and not filled:
                out.append((3.5 if off >= s["dur"] else 5.0, None, "past"))
        if st == "down":
            if s.get("soft") and s["node"] == N and off == s["off"]:
                out.append((0.3, {"status": "active", "off": end, "soft": False}, "soft"))
            if off == s["dur"]:
                out.append((3.0, {"status": "active", "node": N, "off": end, "soft": False}, "mrec"))
            elif off > s["dur"]:
                out.append((4.5, {"status": "active", "node": N, "off": end, "soft": False,
                                  "gaps": s["gaps"] + [[s["dur"], off]]}, "mrecj"))
        if late_crash:
            if end <= pre or off < pre:
                out.append((1.5 if st == "down" else 2.0, None, "late"))
            else:
                out.append((2.5 if st == "down" else 3.0, None, "late2"))
        if st in TERMINAL and s.get("end_node") == N and t - s.get("end_t", -10 ** 9) <= J:
            if end <= s["dur"] or st == "aborted":
                out.append((1.5, None, "lateend"))
    elif ty in ("checkpoint", "commit"):
        if off is None:
            off = s["off"]
        com = ty == "commit"

        def upd(d):
            if com:
                d = dict(d)
                d["status"] = "committed"
                d["dur"] = off
                d["end_t"] = t
                d["end_node"] = N
            return d
        if st == "active" and s["node"] == N:
            if off == s["off"]:
                out.append((0.0, upd({"dur": off}), "x"))
            elif off > s["off"]:
                out.append((2.0, upd({"off": off, "dur": off, "gaps": s["gaps"] + [[s["off"], off]]}), "jump"))
            elif off >= s["dur"]:
                out.append((1.2, upd({"dur": off}), "past"))
            else:
                out.append((4.0, upd({}) if com else None, "past2"))
        if st == "down":
            if late_crash and s["dur"] <= off <= max(pre, s["dur"]):
                out.append((1.5, upd({"dur": off, "off": off}), "late"))
            if off >= s["dur"]:
                out.append((3.5 + (0.5 if off > s["dur"] else 0.0),
                            upd({"status": "active", "node": N, "off": off, "dur": off, "soft": False}), "mrec"))
        elif late_crash and off <= pre:
            out.append((2.0, None, "late"))
        if st in TERMINAL and s.get("end_node") == N and t - s.get("end_t", -10 ** 9) <= J:
            out.append((2.5, None, "lateend"))
    elif ty == "abort":
        ab = {"status": "aborted", "end_t": t, "end_node": N}
        if st == "active" and s["node"] == N:
            out.append((1.0, ab, "x"))
        if st == "down":
            if late_crash:
                out.append((1.5, ab, "late"))
            else:
                out.append((4.0, ab, "mrec"))
    elif ty == "recover":
        r = off
        if st == "down":
            d = {"status": "active", "node": N, "soft": False}
            if r is None:
                r = s["dur"]
            d["off"] = r
            d["dur"] = r
            if r == s["dur"]:
                out.append((0.0, d, "x"))
            elif s["dur"] < r <= max(pre, s["dur"]):
                out.append((1.0, d, "x1"))
            else:
                out.append((3.0, d, "x3"))
        elif st == "active":
            pc = e.get("_pending_crash")
            if pc is not None and r is not None and s["dur"] <= r <= s["off"]:
                ct = pc(s["node"], t)
                if ct is not None:
                    d = {"node": N, "off": r, "dur": r, "gaps": [g for g in s["gaps"] if g[1] <= r]}
                    if N == s["node"]:
                        d["skip_crash"] = ct
                    out.append((1.5 if r == s["dur"] else 2.0, d, "early"))
    return out


def _force(s, e):
    ty = e["type"]
    N = e["node"]
    t = e["t"]
    if s["status"] in TERMINAL:
        return None
    off = e["off"]
    if ty == "write":
        o = off if off is not None else s["off"]
        return {"status": "active", "node": N, "off": o + (e["len"] or 0), "soft": False}
    if ty == "checkpoint":
        o = off if off is not None else s["off"]
        return {"status": "active", "node": N, "off": o, "dur": o, "soft": False}
    if ty == "commit":
        o = off if off is not None else s["off"]
        return {"status": "committed", "dur": o, "end_t": t, "end_node": N}
    if ty == "abort":
        return {"status": "aborted", "end_t": t, "end_node": N}
    if ty == "recover":
        o = off if off is not None else s["dur"]
        return {"status": "active", "node": N, "off": o, "dur": o, "soft": False}
    return None


def solve(state, params):
    inp = state.get("input") or {}
    evs = _norm_events(inp.get("events") if isinstance(inp, dict) else [])
    sess = {}
    order = []

    def get_s(sid):
        if sid not in sess:
            sess[sid] = {"sid": sid, "status": "pending", "node": None, "off": 0, "dur": 0,
                         "gaps": [], "open_t": None, "nev": 0}
            order.append(sid)
        return sess[sid]

    lab = {}
    crash_t = {}
    keyseen = set()
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])
            continue
        key = (e["node"], e["type"], e["off"], e["len"])
        e["maybe_dup"] = key in keyseen
        keyseen.add(key)
        if e["sid"] is not None:
            get_s(e["sid"])
            lab.setdefault(e["sid"], []).append(e)
    for sid in lab:
        lab[sid].sort(key=lambda x: x["p"])
    labpos = {sid: [x["p"] for x in lst] for sid, lst in lab.items()}
    J = _estimate_jitter(evs, lab, crash_t)
    offidx = {}
    for e in evs:
        if e["type"] in ("write", "checkpoint", "commit") and e["off"] is not None:
            offidx.setdefault((e["node"], e["off"]), []).append(e["p"])

    def continues(node, off, p):
        lst = offidx.get((node, off), [])
        q = bisect.bisect_right(lst, p)
        return q < len(lst)

    def pending_crash(node, t):
        ct = crash_t.get(node, [])
        q = bisect.bisect_right(ct, t)
        if q < len(ct) and ct[q] - t <= J:
            return ct[q]
        return None

    def crash_between(node, t1, t2):
        ct = crash_t.get(node, [])
        q = bisect.bisect_right(ct, t1)
        return q < len(ct) and ct[q] <= t2

    def look_adj(s, e, upd):
        sid = s["sid"]
        adj = 0.0
        if e["type"] == "abort" and s["status"] == "active" \
                and continues(s["node"], s["off"], e["p"]):
            adj += 0.8
        if sid not in lab:
            return adj
        lst = lab[sid]
        q = bisect.bisect_right(labpos[sid], e["p"])
        new = dict(s)
        if upd:
            new.update(upd)
        if e["type"] in ("commit", "abort") or (upd and upd.get("status") in TERMINAL):
            for x in lst[q:]:
                if x["t"] > e["t"] + J and not x.get("maybe_dup") and \
                        x["type"] in ("write", "checkpoint", "recover", "commit"):
                    adj += 1.5
                    break
        nxt = None
        for x in lst[q:q + 3]:
            if not x.get("maybe_dup"):
                nxt = x
                break
        if nxt is None:
            return adj
        if new.get("status") == "active" and nxt["type"] in ("write", "checkpoint", "commit") \
                and nxt["off"] is not None:
            if nxt["node"] == new.get("node"):
                if nxt["off"] == new["off"]:
                    adj -= 0.4
                elif nxt["t"] > e["t"] + J and nxt["type"] == "write" and nxt["off"] < new["off"] \
                        and not crash_between(new.get("node"), e["t"], nxt["t"]):
                    adj += 0.6
            elif nxt["t"] > e["t"] + J and not crash_between(new.get("node"), e["t"], nxt["t"]):
                adj += 0.5
        if e["type"] == "recover" and nxt["type"] != "recover":
            if nxt["node"] == e["node"]:
                adj -= 0.3
            elif nxt["t"] > e["t"] + J and not crash_between(e["node"], e["t"], nxt["t"]):
                adj += 0.8
        return adj

    seen = {}
    assign = {}

    def apply(s, upd, e):
        if upd:
            s.update(upd)
            if len(s["gaps"]) > 8:
                s["gaps"] = s["gaps"][-8:]
        s["nev"] += 1
        s["last_t"] = e["t"]

    for e in evs:
        ty = e["type"]
        N = e["node"]
        t = e["t"]
        if ty == "crash":
            for sid in order:
                s = sess[sid]
                if s["status"] != "active" or s["node"] != N:
                    continue
                if s.get("skip_crash") is not None and s["skip_crash"] == t:
                    s["skip_crash"] = None
                    continue
                s["soft"] = s["nev"] == 0 and s["open_t"] is not None and t - s["open_t"] <= J
                s["pre_off"] = s["off"]
                s["crash_t"] = t
                s["crash_node"] = N
                s["status"] = "down"
                s["off"] = s["dur"]
                s["gaps"] = [[g[0], min(g[1], s["dur"])] for g in s["gaps"] if g[0] < s["dur"]]
            continue
        if ty == "open":
            sid = e["sid"]
            if sid is None:
                continue
            s = get_s(sid)
            if s["status"] == "pending":
                s.update({"status": "active", "node": N, "off": 0, "dur": 0, "gaps": [], "open_t": t})
            continue
        e["_pending_crash"] = pending_crash
        key = (N, ty, e["off"], e["len"])
        prev = seen.get(key, [])
        sid = e["sid"]
        best = None
        if sid is not None:
            s = get_s(sid)
            for c, upd, tag in _options(s, e, J):
                if best is None or c < best[0]:
                    best = (c, 0, sid, upd, False)
            for (pt, psid) in prev:
                if psid == sid:
                    c = 0.6
                    if best is None or c < best[0]:
                        best = (c, 0, sid, None, True)
            if best is None or best[0] >= 6.0:
                f = _force(s, e)
                if best is None or 8.0 < best[0]:
                    best = (8.0, 0, sid, f, False)
            chosen = sid
        else:
            for oi, sd in enumerate(order):
                s = sess[sd]
                for c, upd, tag in _options(s, e, J):
                    c2 = c + look_adj(s, e, upd)
                    if best is None or c2 < best[0]:
                        best = (c2, oi, sd, upd, False)
            for (pt, psid) in prev:
                c = 0.6 + (0.3 if t - pt > 6 * J else 0.0)
                if best is None or c < best[0]:
                    best = (c, -1, psid, None, True)
            if best is None:
                cand = None
                for oi, sd in enumerate(order):
                    s = sess[sd]
                    sc = 0
                    if s["node"] == N:
                        sc += 0 if s["status"] not in TERMINAL else 5
                    else:
                        sc += 10
                    if s["status"] == "pending":
                        sc += 20
                    if e["off"] is not None:
                        sc += min(abs(e["off"] - s["off"]), 10 ** 6) / 1e7
                    if cand is None or sc < cand[0]:
                        cand = (sc, sd)
                best = (99, 0, cand[1] if cand else None, None, True)
            chosen = best[2]
            if chosen is not None:
                assign[str(e["i"])] = chosen
        if chosen is None:
            continue
        if not best[4]:
            apply(sess[chosen], best[3], e)
        seen.setdefault(key, []).append((t, chosen))

    sessions = {}
    for sid in order:
        s = sess[sid]
        st = s["status"]
        if st == "pending":
            st = "active"
        sessions[str(sid)] = {"status": st, "durable": int(s["dur"])}
    for e in evs:
        if e["type"] != "crash" and e["sid"] is None and str(e["i"]) not in assign and order:
            assign[str(e["i"])] = order[0]
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def _fallback(state):
    inp = state.get("input") or {}
    raw = inp.get("events") if isinstance(inp, dict) else []
    raw = raw or []
    sids = []
    node_of = {}
    for e in raw:
        if isinstance(e, dict) and e.get("sid") is not None and e.get("sid") not in node_of:
            sids.append(e.get("sid"))
            node_of[e.get("sid")] = e.get("node")
    assign = {}
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        if e.get("type") != "crash" and e.get("sid") is None and sids:
            pick = sids[0]
            for s in sids:
                if node_of.get(s) == e.get("node"):
                    pick = s
                    break
            assign[str(e.get("i", k))] = pick
    sessions = {str(s): {"status": "active", "durable": 0} for s in sids}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state


def run(state, params):
    try:
        return solve(state, params)
    except Exception:
        return _fallback(state)

import time
import bisect

SESSION_TYPES = ("write", "checkpoint", "commit", "abort", "recover")


def _gi(x):
    try:
        return int(x) if x is not None else None
    except Exception:
        return None


def prepare(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        evs.append({
            "i": e.get("i", k), "t": _gi(e.get("t")) or 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _gi(e.get("off")), "len": _gi(e.get("len")),
            "sid": e.get("sid"),
        })
    evs.sort(key=lambda e: (e["t"], e["i"] if isinstance(e["i"], int) else 0))
    sids = []
    seen = set()
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in seen:
            seen.add(e["sid"])
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["sid"] not in seen and e["type"] != "crash":
            seen.add(e["sid"])
            sids.append(e["sid"])
    gaps = sorted(g for g in (evs[k + 1]["t"] - evs[k]["t"] for k in range(len(evs) - 1)) if g >= 0)
    med = gaps[len(gaps) // 2] if gaps else 1
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])
    obs = 0
    bys = {}
    for e in evs:
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None and e["len"] is not None:
            bys.setdefault(e["sid"], []).append(e)
    for s, lst in bys.items():
        for a in range(len(lst)):
            A = lst[a]
            for b in range(a + 1, min(len(lst), a + 12)):
                B = lst[b]
                if B["node"] == A["node"] and B["off"] + B["len"] <= A["off"] and B["t"] > A["t"]:
                    ct = crash_t.get(A["node"], [])
                    p = bisect.bisect_left(ct, A["t"])
                    if p < len(ct) and ct[p] <= B["t"]:
                        continue
                    obs = max(obs, B["t"] - A["t"])
    J = max(int(obs * 1.5) + 1, 4 * med, 2)
    state["prep"] = {"events": evs, "sids": sids, "J": J}
    return state


def beam_search(state, params):
    t0 = time.process_time()
    prep = state["prep"]
    evs = prep["events"]
    sids = prep["sids"]
    J = prep["J"]
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    E = len(evs)
    C_GAP, C_MISS, C_DUP, C_DEFER, C_LATE = 2.0, 2.0, 1.0, 0.4, 1.0
    C_RECACT, C_FORCE, C_ABORT, C_LOOK = 3.0, 15.0, 0.1, 1.5
    MAXPEND = 3

    # duplicate candidates: earlier events with identical signature
    sigmap = {}
    dupc = [None] * E
    is_orig = set()
    for k, e in enumerate(evs):
        if e["type"] in SESSION_TYPES:
            sig = (e["node"], e["type"], e["off"], e["len"])
            prev = sigmap.get(sig)
            if prev:
                dupc[k] = list(prev[-4:])
                for j in prev[-4:]:
                    if evs[j]["sid"] is None:
                        is_orig.add(j)
            sigmap.setdefault(sig, []).append(k)
    # labelled lookahead per session
    lab_t = [[] for _ in range(S)]
    lab_e = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["sid"] is not None and e["sid"] in sidx and e["type"] in ("write", "checkpoint", "commit") and e["off"] is not None:
            q = sidx[e["sid"]]
            lab_t[q].append(e["t"])
            lab_e[q].append(k)
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])

    def look_cost(q, node, t, newoff):
        lt = lab_t[q]
        p = bisect.bisect_right(lt, t + J)
        if p >= len(lt):
            return 0.0
        f = evs[lab_e[q][p]]
        if f["off"] < newoff:
            ct = crash_t.get(node, [])
            c = bisect.bisect_left(ct, t)
            if c < len(ct) and ct[c] <= f["t"]:
                return 0.0
            return C_LOOK
        return 0.0

    # session tuple: (st, node, off, dur, lost, tdown, tact)
    # st: 0 unopened, 1 active, 2 down, 3 committed, 4 aborted
    def sess_opts(ss, q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        res = []
        if typ == "open":
            if st == 0:
                res.append((0.0, (1, N, 0, 0, 0, 0, t)))
            return res
        if st == 0 or st >= 3:
            return res
        if o is None and typ != "abort":
            o = off
        if typ == "write":
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (1, nd, o + l, dur, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (1, nd, o + l, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (2, nd, off, dur, o + l, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (1, N, o + l, dur, lost, tdn, t)))
        elif typ == "checkpoint" or typ == "commit":
            ns = 1 if typ == "checkpoint" else 3
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (ns, nd, o, o, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (ns, nd, o, o, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    nst = 2 if ns == 1 else 3
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (nst, nd, o, o, o, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (ns, N, o, o, lost, tdn, t)))
        elif typ == "abort":
            if st == 1:
                if nd == N:
                    res.append((C_ABORT, (4, nd, off, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N:
                    res.append((C_LATE, (4, nd, off, dur, lost, tdn, tact)))
                res.append((C_MISS, (4, N, off, dur, lost, tdn, tact)))
        elif typ == "recover":
            if st == 2:
                if o == dur:
                    res.append((0.0, (1, N, o, o, lost, tdn, t)))
                elif dur < o <= lost:
                    res.append((C_MISS, (1, N, o, o, lost, tdn, t)))
                elif o > lost:
                    res.append((C_MISS + C_GAP, (1, N, o, o, lost, tdn, t)))
            else:
                if dur <= o <= off:
                    res.append((C_RECACT, (1, N, o, o, lost, tdn, t)))
        return res

    def force(ss, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        if o is None:
            o = off
        if typ == "open":
            return (1, N, 0, 0, 0, 0, t)
        if typ == "write":
            return (1, N, o + l, dur, lost, tdn, tact)
        if typ == "checkpoint":
            return (1, N, o, o, lost, tdn, tact)
        if typ == "commit":
            return (3, N, o, o, lost, tdn, tact)
        if typ == "abort":
            return (4, nd, off, dur, lost, tdn, tact)
        if typ == "recover":
            return (1, N, o, o, lost, tdn, t)
        return ss

    # hypothesis: (cost, sessions tuple, pending tuple, chain, origmap)
    def event_opts(h, k, exact=False):
        cost, ss, pend, chain, om = h
        e = evs[k]
        sid = e["sid"]
        typ = e["type"]
        N = e["node"]
        out = []
        anon = sid is None
        if not anon:
            q0 = sidx.get(sid)
            cands = [q0] if q0 is not None else []
        else:
            cands = range(S)
        newoff = (e["off"] or 0) + (e["len"] or 0)
        for q in cands:
            s = ss[q]
            st = s[0]
            if typ != "open":
                if st == 0 or st >= 3:
                    continue
                if anon and st == 1 and s[1] != N and typ != "recover":
                    continue
            elif st != 0:
                continue
            for c, ns in sess_opts(s, q, k):
                if anon and typ == "write":
                    c += look_cost(q, N, e["t"], newoff)
                if exact and c > 0.5:
                    continue
                out.append((c, ss[:q] + (ns,) + ss[q + 1:], q))
        if exact:
            return out
        dc = dupc[k]
        if dc:
            for j in dc:
                js = evs[j]["sid"]
                if js is not None:
                    q = sidx.get(js)
                else:
                    q = om.get(j) if om else None
                if q is None or q < 0:
                    continue
                if not anon and sidx.get(sid) != q:
                    continue
                out.append((C_DUP, ss, q))
        if not out:
            if not anon and sid in sidx:
                q = sidx[sid]
                out.append((C_FORCE, ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
            elif anon:
                o = e["off"] or 0
                best = []
                for q in range(S):
                    s = ss[q]
                    if s[0] == 0:
                        continue
                    sc = (0 if s[1] == N else 1, 0 if s[0] in (1, 2) else 1, abs(s[2] - o))
                    best.append((sc, q))
                best.sort()
                for sc, q in best[:2]:
                    out.append((C_FORCE + sc[0] + sc[1], ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
        if not out:
            out.append((C_FORCE * 2, ss, 0 if S else -1))
        return out

    def apply_opt(h, k, c, nss, q, remove_pending):
        cost, ss, pend, chain, om = h
        if remove_pending:
            pend = tuple(p for p in pend if p != k)
        if evs[k]["sid"] is None:
            chain = (k, q, chain)
            if k in is_orig:
                om = dict(om) if om else {}
                om[k] = q
        return (cost + c, nss, pend, chain, om)

    def flush(h, depth=0):
        pend = h[2]
        if not pend or depth > 6:
            return [h]
        for k in pend:
            opts = event_opts(h, k, True)
            if opts:
                res = []
                for c, nss, q in opts[:3]:
                    res.extend(flush(apply_opt(h, k, c, nss, q, True), depth + 1))
                return res
        return [h]

    def expire(h, tnow, final=False):
        hs = [h]
        while True:
            nhs = []
            changed = False
            for x in hs:
                old = None
                for k in x[2]:
                    if final or tnow - evs[k]["t"] > J:
                        old = k
                        break
                if old is None:
                    nhs.append(x)
                    continue
                changed = True
                for c, nss, q in event_opts(x, old):
                    nhs.append(apply_opt(x, old, c, nss, q, True))
            hs = nhs
            if not changed:
                return hs
            if len(hs) > 40:
                hs.sort(key=lambda z: z[0])
                hs = hs[:40]

    def crash(h, k):
        cost, ss, pend, chain, om = h
        e = evs[k]
        N = e["node"]
        t = e["t"]
        aff = []
        recent = []
        for q in range(S):
            s = ss[q]
            if s[0] == 1 and s[1] == N:
                aff.append(q)
                if t - s[6] <= J and s[6] > 0:
                    recent.append(q)

        def down(sset, qs):
            l = list(sset)
            for q in qs:
                s = l[q]
                l[q] = (2, s[1], s[3], s[3], s[2], t, s[6])
            return tuple(l)

        res = [(cost, down(ss, aff), pend, chain, om)]
        if recent:
            rest = [q for q in aff if q not in recent]
            res.append((cost + C_LATE, down(ss, rest), pend, chain, om))
        return res

    K = 48 if E * max(S, 4) <= 4000 else 32
    if E * S > 8000:
        K = 24
    beam = [(0.0, tuple((0, "", 0, 0, 0, 0, 0) for _ in range(S)), (), None, None)]
    budget = 0.7
    for k in range(E):
        e = evs[k]
        el = time.process_time() - t0
        frac = (k + 1) / max(E, 1)
        if el > budget * frac * 1.05 and K > 4:
            K = max(4, int(K * 0.8))
        elif el < budget * frac * 0.6 and K < 96:
            K += 1
        if el > 1.0:
            K = 1
        cand = []
        tnow = e["t"]
        for h in beam:
            for x in expire(h, tnow):
                if e["type"] == "crash":
                    cand.extend(crash(x, k))
                    continue
                if e["type"] not in SESSION_TYPES and e["type"] != "open":
                    cand.append(x)
                    continue
                for c, nss, q in event_opts(x, k):
                    cand.extend(flush(apply_opt(x, k, c, nss, q, False)))
                if e["type"] != "open" and len(x[2]) < MAXPEND and K > 4:
                    cand.append((x[0] + C_DEFER, x[1], x[2] + (k,), x[3], x[4]))
        if not cand:
            continue
        cand.sort(key=lambda z: z[0])
        seen = set()
        nb = []
        for z in cand:
            key = (z[1], z[2])
            if key in seen:
                continue
            seen.add(key)
            nb.append(z)
            if len(nb) >= K:
                break
        beam = nb
    finals = []
    for h in beam:
        finals.extend(expire(h, 0, True))
    finals.sort(key=lambda z: z[0])
    best = finals[0] if finals else beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        kk, q, ch = ch
        assign[kk] = q
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_a = {}
    for k, e in enumerate(evs):
        if e["sid"] is None and e["type"] != "crash":
            q = assign.get(k)
            if q is None or q < 0 or q >= S:
                q = 0
            if S:
                out_a[str(e["i"])] = sids[q]
    sessions = {}
    for q, s in enumerate(sids):
        st = best[1][q]
        sessions[s] = {"status": names.get(st[0], "active"), "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": sessions}
    return state

import bisect
import statistics
import time
from collections import defaultdict

TERM = ("commit", "abort")
SUCC_T = ("write", "checkpoint", "commit", "abort", "recover")


def _norm(raw):
    evs = []
    for k, e in enumerate(raw or []):
        if not isinstance(e, dict):
            continue
        try:
            t = int(e.get("t") or 0)
        except Exception:
            t = 0
        off = e.get("off")
        ln = e.get("len")
        evs.append({"i": e.get("i", k), "t": t, "node": str(e.get("node")),
                    "type": str(e.get("type") or ""),
                    "off": off if isinstance(off, int) else None,
                    "len": ln if isinstance(ln, int) else None,
                    "sid": e.get("sid")})
    return evs


def _estimate_jitter(evs):
    byl = defaultdict(list)
    for e in evs:
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None and e["len"] is not None:
            byl[e["sid"]].append(e)
    inv = 0
    for sid, lst in byl.items():
        lst.sort(key=lambda x: x["t"])
        for a in range(len(lst)):
            for b in range(a + 1, min(len(lst), a + 6)):
                x, y = lst[a], lst[b]
                if x["node"] == y["node"] and y["off"] + y["len"] == x["off"] and x["t"] <= y["t"]:
                    inv = max(inv, y["t"] - x["t"])
    return inv


def solve(state, params):
    try:
        return _solve(state, params)
    except Exception:
        state["output"] = _fallback(state)
        return state


def _fallback(state):
    inp = state.get("input") or {}
    evs = [e for e in (inp.get("events") or []) if isinstance(e, dict)]
    sids = [e.get("sid") for e in evs if e.get("type") == "open" and e.get("sid") is not None]
    if not sids:
        sids = ["s0"]
    asg = {}
    for e in evs:
        if e.get("type") != "crash" and e.get("sid") is None:
            asg[str(e.get("i"))] = sids[0]
    return {"assignments": asg, "sessions": {s: {"status": "active", "durable": 0} for s in sids}}


def _solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = _norm(inp.get("events"))
    evs.sort(key=lambda e: (e["t"], e["i"]))
    n = len(evs)
    crashes = defaultdict(list)
    for e in evs:
        if e["type"] == "crash":
            crashes[e["node"]].append(e["t"])
    for k in crashes:
        crashes[k].sort()
    sess_ev = [e for e in evs if e["type"] != "crash"]
    ts_all = [e["t"] for e in evs]
    gaps = [b - a for a, b in zip(ts_all, ts_all[1:])]
    g = max(1.0, statistics.mean(gaps)) if gaps else 1.0
    inv = _estimate_jitter(evs)
    J = max(inv + 1, int(3 * g) + 1)
    Jwin = max(2 * inv + 2, int(5 * g) + 2)
    opens = [e for e in evs if e["type"] == "open" and e["sid"] is not None]
    sids = []
    for e in opens:
        if e["sid"] not in sids:
            sids.append(e["sid"])
    for e in sess_ev:
        if e["sid"] is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    nsess = max(1, len(sids))
    P = params or {}
    S = max(1.0, g * nsess * P.get("sf", 0.25))
    TW = P.get("tw", 1.2)
    BW = P.get("bw", 0.3)
    GAP = P.get("gap", 2.5)

    # ---------- duplicate collapse ----------
    D = max(12, 2 * J + 10)
    groups = defaultdict(list)
    for idx, e in enumerate(evs):
        if e["type"] in SUCC_T:
            groups[(e["node"], e["type"], e["off"], e["len"])].append(idx)
    dup_of = {}
    for key, lst in groups.items():
        if len(lst) < 2:
            continue
        paired = set()
        for b in lst:
            if b in paired:
                continue
            eb = evs[b]
            best = None
            for a in lst:
                if a == b or a in paired or a in dup_of or evs[a]["t"] > eb["t"]:
                    continue
                if evs[a]["t"] == eb["t"] and a > b:
                    continue
                if eb["t"] - evs[a]["t"] > D:
                    continue
                sa, sb = evs[a]["sid"], eb["sid"]
                if sa is not None and sb is not None and sa != sb:
                    continue
                if best is None or evs[a]["t"] > evs[best]["t"]:
                    best = a
            if best is not None:
                dup_of[b] = best
                paired.add(best)
                paired.add(b)
    reps = [idx for idx in range(n) if evs[idx]["type"] != "crash" and idx not in dup_of]
    members = {r: [r] for r in reps}
    for b, a in dup_of.items():
        members[a].append(b)
    label = {}
    for r in reps:
        for m in members[r]:
            if evs[m]["sid"] is not None:
                label[r] = evs[m]["sid"]
                break

    def crash_in(node, lo, hi):
        lst = crashes.get(node)
        if not lst:
            return False
        k = bisect.bisect_right(lst, lo)
        return k < len(lst) and lst[k] < hi

    def pinfo(r):
        e = evs[r]
        ty = e["type"]
        if ty == "open":
            return 0, 0
        if ty == "write":
            if e["off"] is None:
                return None, None
            return e["off"] + (e["len"] or 0), None
        if ty in ("checkpoint", "recover"):
            return e["off"], e["off"]
        return None, None

    PI = {r: pinfo(r) for r in reps}

    def cost(p, s):
        ep, es = evs[p], evs[s]
        E, pdur = PI[p]
        if E is None:
            return None
        tp, tsx = ep["t"], es["t"]
        dt = tsx - tp
        if dt < -Jwin:
            return None
        N = ep["node"]
        sty = es["type"]
        tpen = TW * max(dt, 0) / S + BW * max(-dt, 0) / max(J, 1)
        crash_any = crash_in(N, tp - J, tsx + J)
        crash_sure = crash_in(N, tp + J, tsx - J)
        if sty == "recover":
            if not crash_any or es["off"] is None:
                return None
            o = es["off"]
            if pdur is not None:
                if o == pdur:
                    b = 0.2
                elif o < pdur:
                    return None
                elif o <= E:
                    b = 2.0
                else:
                    b = 5.0
            else:
                if o <= ep["off"]:
                    b = 0.7
                elif o == E:
                    b = 2.0
                elif o < E:
                    return None
                else:
                    b = 5.0
            return b + tpen
        if sty == "abort":
            if es["node"] == N:
                b = 1.2 + (1.5 if crash_sure else 0.0)
            elif crash_any:
                b = 3.5
            else:
                return None
            return b + tpen
        o = es["off"]
        if o is None:
            return None
        if es["node"] == N:
            if o == E:
                b = 0.0 + (1.5 if crash_sure else 0.0)
                return b + tpen
            if o > E:
                return GAP + (1.0 if crash_sure else 0.0) + tpen
        # rollback/migration without visible recover
        if not crash_any:
            return None
        if pdur is not None:
            if o == pdur:
                b = 3.0
            elif o < pdur:
                return None
            elif o <= E:
                b = 4.0
            else:
                return None
        else:
            if o <= ep["off"]:
                b = 3.2
            elif o <= E:
                b = 4.2
            else:
                return None
        return b + tpen

    # ---------- candidate edges ----------
    preds = [r for r in reps if PI[r][0] is not None]
    succs = [r for r in reps if evs[r]["type"] in SUCC_T]
    succ_t = [evs[s]["t"] for s in succs]
    exact = defaultdict(list)
    for s in succs:
        es = evs[s]
        if es["off"] is not None and es["type"] != "recover":
            exact[(es["node"], es["off"])].append(s)
    SCAN = 160 if n <= 300 else 110
    edges = []
    for p in preds:
        tp = evs[p]["t"]
        k0 = bisect.bisect_left(succ_t, tp - Jwin)
        seen = set()
        for s in succs[k0:k0 + SCAN]:
            if s == p:
                continue
            c = cost(p, s)
            seen.add(s)
            if c is not None:
                edges.append((c, evs[s]["t"] - tp, p, s))
        for s in exact.get((evs[p]["node"], PI[p][0]), ()):
            if s in seen or s == p:
                continue
            c = cost(p, s)
            if c is not None:
                edges.append((c, evs[s]["t"] - tp, p, s))
    edges.sort()

    # ---------- greedy chain matching with label-conflict resolution ----------
    parent = {r: r for r in reps}
    clabel = {r: label.get(r) for r in reps}
    for r in reps:
        if evs[r]["type"] == "open":
            clabel[r] = evs[r]["sid"]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    nxt, prv = {}, {}
    for c, _, p, s in edges:
        if p in nxt or s in prv:
            continue
        rp, rs = find(p), find(s)
        if rp == rs:
            continue
        lp, ls = clabel[rp], clabel[rs]
        if lp is not None and ls is not None and lp != ls:
            continue
        nxt[p] = s
        prv[s] = p
        parent[rs] = rp
        clabel[rp] = lp if lp is not None else ls

    # ---------- augmenting repairs: 2-opt successor swaps and relinks ----------
    OP = P.get("op", 2.0)
    ecost = {}
    out_edges = defaultdict(list)
    for c, _, p, s in edges:
        ecost[(p, s)] = c
        out_edges[p].append((c, s))
    base_lab = {}
    for r in reps:
        base_lab[r] = evs[r]["sid"] if evs[r]["type"] == "open" else label.get(r)

    def rebuild():
        cid, plab, slab = {}, {}, {}
        for h in reps:
            if h in prv:
                continue
            ch = [h]
            x = h
            while x in nxt:
                x = nxt[x]
                ch.append(x)
            cur = None
            for x in ch:
                if cur is None:
                    cur = base_lab[x]
                plab[x] = cur
                cid[x] = h
            cur = None
            for x in reversed(ch):
                if cur is None:
                    cur = base_lab[x]
                slab[x] = cur
        return cid, plab, slab

    def compat(a, b):
        return a is None or b is None or a == b

    def unl(a, b):
        return OP if (a is None and b is None) else 0.0

    deadline = t0 + P.get("budget", 0.55)
    for _round in range(6):
        if time.process_time() > deadline:
            break
        cid, plab, slab = rebuild()
        improved = 0
        dirty = set()
        for p1 in list(nxt.keys()):
            if time.process_time() > deadline:
                break
            if p1 in dirty:
                continue
            s1 = nxt[p1]
            if s1 in dirty:
                continue
            c11 = ecost.get((p1, s1))
            if c11 is None:
                continue
            best = None
            pl1 = plab[p1]
            sl1 = slab[s1]
            for c12, s2 in out_edges[p1]:
                if s2 == s1 or c12 >= c11 + OP + 4.0 or s2 in dirty:
                    continue
                if cid[s2] == cid[p1]:
                    continue
                p2 = prv.get(s2)
                sl2 = slab[s2]
                if not compat(pl1, sl2):
                    continue
                if p2 is None:
                    hl = slab[s2]
                    old = c11 + unl(pl1, sl1) + unl(None, hl)
                    newv = c12 + unl(pl1, hl) + unl(None, sl1)
                    d = newv - old
                else:
                    if p2 in dirty:
                        continue
                    c21 = ecost.get((p2, s1))
                    if c21 is None:
                        c21 = cost(p2, s1)
                        if c21 is None:
                            continue
                    c22 = ecost.get((p2, s2), 0.0)
                    pl2 = plab[p2]
                    if not compat(pl2, sl1):
                        continue
                    old = c11 + c22 + unl(pl1, sl1) + unl(pl2, sl2)
                    newv = c12 + c21 + unl(pl1, sl2) + unl(pl2, sl1)
                    d = newv - old
                if d < -1e-6 and (best is None or d < best[0]):
                    best = (d, s2, p2)
            if best is None:
                continue
            d, s2, p2 = best
            if p2 is None:
                del prv[s1]
                nxt[p1] = s2
                prv[s2] = p1
                dirty.update((p1, s1, s2))
            else:
                nxt[p1] = s2
                prv[s2] = p1
                nxt[p2] = s1
                prv[s1] = p2
                dirty.update((p1, s1, p2, s2))
            improved += 1
        if not improved:
            break
    cid, plab, slab = rebuild()
    parent = {r: r for r in reps}
    clabel = {}
    for r in reps:
        parent[r] = cid[r]
    for r in reps:
        h = cid[r]
        if clabel.get(h) is None:
            clabel[h] = plab[r] if plab[r] is not None else slab[r]
    for r in reps:
        clabel.setdefault(r, None)

    # ---------- chains ----------
    heads = [r for r in reps if r not in prv]
    chains = []
    for h in heads:
        ch = [h]
        x = h
        while x in nxt:
            x = nxt[x]
            ch.append(x)
        chains.append(ch)
    chains.sort(key=lambda ch: evs[ch[0]]["t"])
    owner = {}
    sess_members = defaultdict(list)
    orphans = []
    for ch in chains:
        lab = clabel[find(ch[0])]
        if lab is None:
            orphans.append(ch)
            continue
        for r in ch:
            owner[r] = lab
            sess_members[lab].append(r)

    # ---------- second round: gap edges between free tails and orphan heads ----------
    RW = P.get("rw", 1.0)

    def relaxed(x, h):
        E, _ = PI[x]
        if E is None:
            return None
        ex, eh = evs[x], evs[h]
        dt = eh["t"] - ex["t"]
        if dt < -Jwin:
            return None
        N = ex["node"]
        ca = crash_in(N, ex["t"] - J, eh["t"] + J)
        ty = eh["type"]
        if ty == "abort":
            b = 1.0 if eh["node"] == N else (2.0 if ca else 5.0)
        elif ty == "recover":
            b = 1.0 if ca else 4.0
            if eh["off"] is not None and eh["off"] > E:
                b += 1.0
        else:
            o = eh["off"] if eh["off"] is not None else E
            if eh["node"] == N:
                b = 1.0 if o >= E else (1.5 if ca else 4.0)
            else:
                b = 1.5 if ca else 5.0
        return b + RW * TW * max(dt, 0) / S + BW * max(-dt, 0) / max(J, 1)

    orph_heads = {ch[0]: ch for ch in orphans}
    free_tail = {}
    for ch in chains:
        x = ch[-1]
        if x in owner and PI[x][0] is not None:
            free_tail[x] = owner[x]
    changed = True
    while changed and orph_heads and free_tail:
        changed = False
        pairs = []
        for x in free_tail:
            for h in orph_heads:
                c = relaxed(x, h)
                if c is not None:
                    pairs.append((c, x, h))
        pairs.sort()
        used_x, used_h = set(), set()
        for c, x, h in pairs:
            if x in used_x or h in used_h:
                continue
            used_x.add(x)
            used_h.add(h)
            sid = free_tail.pop(x)
            ch = orph_heads.pop(h)
            for r in ch:
                owner[r] = sid
                sess_members[sid].append(r)
            if PI[ch[-1]][0] is not None:
                free_tail[ch[-1]] = sid
            changed = True
    orphans = [ch for ch in orphans if ch[0] in orph_heads]

    # attach orphan chains (in time order) to best-fitting session member
    for ch in orphans:
        h = ch[0]
        best, bc = None, None
        for sid in sids:
            for x in sess_members.get(sid, ()):
                if PI[x][0] is None:
                    continue
                c = cost(x, h)
                if c is None:
                    continue
                if nxt.get(x) is not None:
                    c += 0.5
                if bc is None or c < bc:
                    bc, best = c, sid
        if best is None:
            th, nh = evs[h]["t"], evs[h]["node"]
            for sid in sids:
                for x in sess_members.get(sid, ()):
                    ex = evs[x]
                    d = abs(ex["t"] - th) / S + (0 if ex["node"] == nh else 3.0)
                    if ex["type"] in TERM and ex["t"] < th:
                        d += 5.0
                    if bc is None or d < bc:
                        bc, best = d, sid
        if best is None:
            best = sids[0] if sids else "s0"
        for r in ch:
            owner[r] = best
            sess_members[best].append(r)

    # ---------- assignments ----------
    assignments = {}
    for idx, e in enumerate(evs):
        if e["type"] == "crash" or e["sid"] is not None:
            continue
        r = dup_of.get(idx, idx)
        sid = owner.get(r)
        if sid is None:
            sid = sids[0] if sids else "s0"
        assignments[str(e["i"])] = sid

    # ---------- replay final states ----------
    sessions = {}
    sess_chains = defaultdict(list)
    for ch in chains:
        if ch and ch[0] in owner:
            sess_chains[owner[ch[0]]].append(ch)
    for sid in sids:
        order = []
        for ch in sess_chains.get(sid, []):
            order.extend(ch)
        commit = [r for r in order if evs[r]["type"] == "commit" and evs[r]["off"] is not None]
        durs = [0]
        for r in order:
            e = evs[r]
            if e["type"] in ("checkpoint", "recover") and e["off"] is not None:
                durs.append(e["off"])
        for p, s in zip(order, order[1:]):
            if nxt.get(p) != s:
                continue
            E, _ = PI[p]
            es = evs[s]
            if es["type"] in ("write", "checkpoint", "commit") and es["off"] is not None and E is not None:
                if es["off"] < E or es["node"] != evs[p]["node"]:
                    durs.append(es["off"])
        if commit:
            c = max(commit, key=lambda r: evs[r]["t"])
            sessions[sid] = {"status": "committed", "durable": evs[c]["off"]}
            continue
        dur = max(durs)
        if any(evs[r]["type"] == "abort" for r in order):
            sessions[sid] = {"status": "aborted", "durable": dur}
            continue
        if not order:
            sessions[sid] = {"status": "active", "durable": dur}
            continue
        last = order[-1]
        for ch in sess_chains.get(sid, []):
            if evs[ch[-1]]["t"] > evs[last]["t"]:
                last = ch[-1]
        el = evs[last]
        lst = crashes.get(el["node"], [])
        k = bisect.bisect_right(lst, el["t"])
        down = k < len(lst)
        sessions[sid] = {"status": "down" if down else "active", "durable": dur}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import time
import random
import bisect

TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}
C_GAP = 1.0      # implied missing write(s)
C_BACK = 3.0     # offset going backwards without crash
C_NODE = 4.0     # active session acting on another node
C_END = 5.0      # event after commit/abort (or before open)
C_MISSREC = 1.0  # implied missing recover
C_MISSCP = 1.0   # implied missing checkpoint
C_BADREC = 2.0   # recover while active
C_DUP = 0.2      # duplicate copy
C_CRASH = 0.15   # prefer near-simultaneous fitting events before a crash
C_RANK = 0.1     # order-deviation penalty inside the jitter window


def _int(x, d=None):
    try:
        if x is None:
            return d
        return int(x)
    except Exception:
        return d


def prepare(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        ty = TYPES.get(e.get("type"), -1)
        if ty < 0:
            continue
        i = _int(e.get("i"), k)
        t = _int(e.get("t"), 0)
        sid = e.get("sid")
        sid = str(sid) if sid is not None else None
        evs.append([t, i, ty, str(e.get("node")), _int(e.get("off")), _int(e.get("len"), 0), sid])
    evs.sort(key=lambda r: (r[0], r[1]))
    state["_evs"] = evs
    return state


def _estimate_window(evs):
    by = {}
    for r in evs:
        if r[6] is not None and r[2] in (1, 2, 3):
            by.setdefault(r[6], []).append(r)
    W = 0
    for lst in by.values():
        n = len(lst)
        for a in range(n):
            ra = lst[a]
            if ra[4] is None:
                continue
            for b in range(a + 1, min(n, a + 8)):
                rb = lst[b]
                if rb[2] == 1 and rb[4] is not None and rb[4] + rb[5] == ra[4]:
                    W = max(W, ra[0] - rb[0])
    ts = [r[0] for r in evs]
    gaps = sorted(ts[k + 1] - ts[k] for k in range(len(ts) - 1)) or [1]
    med = gaps[len(gaps) // 2]
    return max(W + 1, 3 * med, 2)


def _step(st, ty, node, off, ln):
    # st = [status, node, cur, dur, maxcur]; status 0 none 1 active 2 down 3 committed 4 aborted
    s = st[0]
    if ty == 0:
        if s == 0:
            st[0] = 1; st[1] = node; st[2] = 0; st[3] = 0; st[4] = 0
            return 0.0
        return C_END
    if s >= 3 or s == 0:
        return C_END
    cost = 0.0
    if s == 2:
        if ty == 5:
            st[0] = 1; st[1] = node
            if off is None or off == st[3]:
                st[2] = st[3]
                return 0.0
            if st[3] < off <= st[4]:
                cost = C_MISSCP
            else:
                cost = C_BACK
            st[2] = off; st[3] = off
            return cost
        cost += C_MISSREC
        st[0] = 1; st[1] = node; st[2] = st[3]
        if off is not None and ty in (1, 2, 3) and st[3] < off <= st[4]:
            cost += C_MISSCP
            st[2] = off; st[3] = off
    elif ty == 5:
        st[1] = node
        if off is not None:
            st[2] = off; st[3] = off
        return C_BADREC
    elif node != st[1]:
        cost += C_NODE
        st[1] = node
    cur = st[2]
    if ty == 1:
        if off is None:
            st[2] = cur + (ln or 0)
            return cost
        if off != cur:
            cost += C_GAP if off > cur else C_BACK
        st[2] = off + (ln or 0)
        return cost
    if ty == 2 or ty == 3:
        if off is not None and off != cur:
            cost += C_GAP if off > cur else C_BACK
            cur = off
        st[2] = cur; st[3] = cur
        if ty == 3:
            st[0] = 3
        return cost
    if ty == 4:
        st[0] = 4
    return cost


def _replay(items, crashes, W, final=False):
    cost = 0.0
    seen = set()
    prim = []
    for it in items:
        if it[2] != 0:
            sig = (it[2], it[3], it[4], it[5])
            if sig in seen:
                cost += C_DUP
                continue
            seen.add(sig)
        prim.append(it)
    if not prim:
        st = [0, None, 0, 0, 0]
        return (cost, st) if final else cost
    t0 = prim[0][0] - W
    ci = bisect.bisect_left(crashes, (t0,))
    merged = prim
    if ci < len(crashes):
        merged = sorted(prim + crashes[ci:])
    st = [0, None, 0, 0, 0]
    n = len(merged)
    done = [False] * n
    p = 0
    while p < n:
        if done[p]:
            p += 1
            continue
        tlim = merged[p][0] + W
        best = -1
        bv = 1e18
        bst = None
        rank = 0
        q = p
        while q < n and rank < 5:
            if done[q]:
                q += 1
                continue
            it = merged[q]
            if it[0] > tlim:
                break
            if it[2] == 6:
                if st[0] == 1 and st[1] == it[3]:
                    v = C_CRASH + C_RANK * rank
                    if v < bv:
                        bv = v; best = q; bst = None
                elif rank == 0:
                    if 0.0 < bv:
                        bv = 0.0; best = q; bst = None
            else:
                s2 = st[:]
                c = _step(s2, it[2], it[3], it[4], it[5])
                v = c + C_RANK * rank
                if v < bv:
                    bv = v; best = q; bst = (s2, c)
            rank += 1
            q += 1
        if best < 0:
            best = p
            bst = None
        it = merged[best]
        done[best] = True
        if it[2] == 6:
            if st[0] == 1 and st[1] == it[3]:
                st[0] = 2; st[4] = st[2]; st[2] = st[3]
        else:
            if bst is None:
                c = _step(st, it[2], it[3], it[4], it[5])
            else:
                st = bst[0]
                c = bst[1]
            cost += c
    return (cost, st) if final else cost


def solve(state, params):
    T0 = time.perf_counter()
    P0 = time.process_time()
    BUDGET = 0.55
    evs = state.get("_evs") or []
    W = _estimate_window(evs) if evs else 2
    crashes = [tuple(r[:6]) for r in evs if r[2] == 6]
    sessions = []
    open_t = {}
    for r in evs:
        if r[2] == 0 and r[6] is not None and r[6] not in open_t:
            open_t[r[6]] = (r[0], r[1])
            sessions.append(r[6])
    for r in evs:
        if r[6] is not None and r[2] != 6 and r[6] not in open_t:
            open_t[r[6]] = (r[0] - 1, -1)
            sessions.append(r[6])
    sidx = {s: k for k, s in enumerate(sessions)}
    S = len(sessions)
    if S == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state
    lists = [[] for _ in range(S)]
    var_items = []
    var_cands = []
    for r in evs:
        if r[2] == 6:
            continue
        it = tuple(r[:6])
        if r[6] is not None:
            lists[sidx[r[6]]].append(it)
        else:
            c = [k for k in range(S) if open_t[sessions[k]] <= (r[0], r[1])]
            if not c:
                c = list(range(S))
            var_items.append(it)
            var_cands.append(c)
    V = len(var_items)

    # ---- seed: streaming tracker with append-at-end step cost ----
    assign = [0] * V
    sts = [[0, None, 0, 0, 0] for _ in range(S)]
    vpos = {}
    for v, it in enumerate(var_items):
        vpos[it[1]] = v
    seen = [set() for _ in range(S)]
    for r in evs:
        it = tuple(r[:6])
        if r[2] == 6:
            for st in sts:
                if st[0] == 1 and st[1] == it[3]:
                    st[0] = 2; st[4] = st[2]; st[2] = st[3]
            continue
        sig = (it[2], it[3], it[4], it[5])
        if r[6] is not None:
            k = sidx[r[6]]
            if it[2] != 0 and sig in seen[k]:
                continue
            seen[k].add(sig)
            _step(sts[k], it[2], it[3], it[4], it[5])
            continue
        v = vpos[it[1]]
        best = None
        bc = 1e18
        for k in var_cands[v]:
            if sig in seen[k]:
                c = C_DUP
            else:
                s2 = sts[k][:]
                c = _step(s2, it[2], it[3], it[4], it[5])
            if c < bc:
                bc = c; best = k
        assign[v] = best
        if sig in seen[best]:
            continue
        seen[best].add(sig)
        _step(sts[best], it[2], it[3], it[4], it[5])

    for v in range(V):
        bisect.insort(lists[assign[v]], var_items[v])
    costs = [_replay(lists[k], crashes, W) for k in range(S)]
    total = sum(costs)
    best_assign = assign[:]
    best_total = total

    def elapsed():
        return max(time.perf_counter() - T0, time.process_time() - P0)

    def remove(k, it):
        L = lists[k]
        j = bisect.bisect_left(L, it)
        if j < len(L) and L[j] == it:
            del L[j]

    rng = random.Random(12345)
    movable = [v for v in range(V) if len(var_cands[v]) > 1]
    if movable:
        Thi, Tlo = 1.5, 0.03
        it_count = 0
        temp = Thi
        while True:
            if (it_count & 31) == 0:
                el = elapsed()
                if el > BUDGET:
                    break
                temp = Thi * (Tlo / Thi) ** (el / BUDGET)
            it_count += 1
            v = movable[rng.randrange(len(movable))]
            a = assign[v]
            cands = var_cands[v]
            b = cands[rng.randrange(len(cands))]
            if b == a:
                continue
            if rng.random() < 0.2:
                tv = var_items[v][0:2]
                ma = [u for u in range(V) if assign[u] == a and var_items[u][0:2] >= tv and b in var_cands[u]]
                mb = [u for u in range(V) if assign[u] == b and var_items[u][0:2] >= tv and a in var_cands[u]]
                for u in ma:
                    remove(a, var_items[u]); bisect.insort(lists[b], var_items[u])
                for u in mb:
                    remove(b, var_items[u]); bisect.insort(lists[a], var_items[u])
                ca = _replay(lists[a], crashes, W)
                cb = _replay(lists[b], crashes, W)
                d = ca + cb - costs[a] - costs[b]
                if d <= 0 or rng.random() < pow(2.718281828, -d / temp):
                    for u in ma:
                        assign[u] = b
                    for u in mb:
                        assign[u] = a
                    costs[a] = ca; costs[b] = cb; total += d
                    if total < best_total - 1e-9:
                        best_total = total; best_assign = assign[:]
                else:
                    for u in ma:
                        remove(b, var_items[u]); bisect.insort(lists[a], var_items[u])
                    for u in mb:
                        remove(a, var_items[u]); bisect.insort(lists[b], var_items[u])
                continue
            it = var_items[v]
            remove(a, it)
            bisect.insort(lists[b], it)
            ca = _replay(lists[a], crashes, W)
            cb = _replay(lists[b], crashes, W)
            d = ca + cb - costs[a] - costs[b]
            if d <= 0 or rng.random() < pow(2.718281828, -d / temp):
                assign[v] = b
                costs[a] = ca; costs[b] = cb; total += d
                if total < best_total - 1e-9:
                    best_total = total; best_assign = assign[:]
            else:
                remove(b, it)
                bisect.insort(lists[a], it)

    # ---- final replay of best assignment ----
    lists = [[] for _ in range(S)]
    for r in evs:
        if r[2] != 6 and r[6] is not None:
            lists[sidx[r[6]]].append(tuple(r[:6]))
    for v in range(V):
        lists[best_assign[v]].append(var_items[v])
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_s = {}
    for k in range(S):
        lists[k].sort()
        c, st = _replay(lists[k], crashes, W, final=True)
        dur = st[2] if st[0] == 3 else st[3]
        out_s[sessions[k]] = {"status": names.get(st[0], "active"), "durable": int(dur or 0)}
    out_a = {str(var_items[v][1]): sessions[best_assign[v]] for v in range(V)}
    state["output"] = {"assignments": out_a, "sessions": out_s}
    return state

import time
import bisect
import random

SESSION_TYPES = ("write", "checkpoint", "commit", "abort", "recover")


def _gi(x):
    try:
        return int(x) if x is not None else None
    except Exception:
        return None


def prepare(state, params):
    p0 = time.process_time()
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        evs.append({
            "i": e.get("i", k), "t": _gi(e.get("t")) or 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _gi(e.get("off")), "len": _gi(e.get("len")),
            "sid": e.get("sid"),
        })
    evs.sort(key=lambda e: (e["t"], e["i"] if isinstance(e["i"], int) else 0))
    sids = []
    seen = set()
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in seen:
            seen.add(e["sid"])
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["sid"] not in seen and e["type"] != "crash":
            seen.add(e["sid"])
            sids.append(e["sid"])
    gaps = sorted(g for g in (evs[k + 1]["t"] - evs[k]["t"] for k in range(len(evs) - 1)) if g >= 0)
    med = gaps[len(gaps) // 2] if gaps else 1
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])
    obs = 0
    bys = {}
    for e in evs:
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None and e["len"] is not None:
            bys.setdefault(e["sid"], []).append(e)
    for s, lst in bys.items():
        for a in range(len(lst)):
            A = lst[a]
            for b in range(a + 1, min(len(lst), a + 12)):
                B = lst[b]
                if B["node"] == A["node"] and B["off"] + B["len"] <= A["off"] and B["t"] > A["t"]:
                    ct = crash_t.get(A["node"], [])
                    p = bisect.bisect_left(ct, A["t"])
                    if p < len(ct) and ct[p] <= B["t"]:
                        continue
                    obs = max(obs, B["t"] - A["t"])
    J = max(int(obs * 1.5) + 1, 4 * med, 2)
    state["prep"] = {"events": evs, "sids": sids, "J": J, "p0": p0}
    return state


def beam_search(state, params):
    t0 = time.process_time()
    prep = state["prep"]
    evs = prep["events"]
    sids = prep["sids"]
    J = prep["J"]
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    E = len(evs)
    C_GAP, C_MISS, C_DUP, C_DEFER, C_LATE = 2.0, 2.0, 1.0, 0.4, 1.0
    C_RECACT, C_FORCE, C_ABORT, C_LOOK = 3.0, 15.0, 0.1, 1.5
    MAXPEND = 3

    sigmap = {}
    dupc = [None] * E
    is_orig = set()
    for k, e in enumerate(evs):
        if e["type"] in SESSION_TYPES:
            sig = (e["node"], e["type"], e["off"], e["len"])
            prev = sigmap.get(sig)
            if prev:
                dupc[k] = list(prev[-4:])
                for j in prev[-4:]:
                    if evs[j]["sid"] is None:
                        is_orig.add(j)
            sigmap.setdefault(sig, []).append(k)
    lab_t = [[] for _ in range(S)]
    lab_e = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["sid"] is not None and e["sid"] in sidx and e["type"] in ("write", "checkpoint", "commit") and e["off"] is not None:
            q = sidx[e["sid"]]
            lab_t[q].append(e["t"])
            lab_e[q].append(k)
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])

    def look_cost(q, node, t, newoff):
        lt = lab_t[q]
        p = bisect.bisect_right(lt, t + J)
        if p >= len(lt):
            return 0.0
        f = evs[lab_e[q][p]]
        if f["off"] < newoff:
            ct = crash_t.get(node, [])
            c = bisect.bisect_left(ct, t)
            if c < len(ct) and ct[c] <= f["t"]:
                return 0.0
            return C_LOOK
        return 0.0

    def sess_opts(ss, q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        res = []
        if typ == "open":
            if st == 0:
                res.append((0.0, (1, N, 0, 0, 0, 0, t)))
            return res
        if st == 0 or st >= 3:
            return res
        if o is None and typ != "abort":
            o = off
        if typ == "write":
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (1, nd, o + l, dur, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (1, nd, o + l, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (2, nd, off, dur, o + l, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (1, N, o + l, dur, lost, tdn, t)))
        elif typ == "checkpoint" or typ == "commit":
            ns = 1 if typ == "checkpoint" else 3
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (ns, nd, o, o, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (ns, nd, o, o, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    nst = 2 if ns == 1 else 3
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (nst, nd, o, o, o, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (ns, N, o, o, lost, tdn, t)))
        elif typ == "abort":
            if st == 1:
                if nd == N:
                    res.append((C_ABORT, (4, nd, off, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N:
                    res.append((C_LATE, (4, nd, off, dur, lost, tdn, tact)))
                res.append((C_MISS, (4, N, off, dur, lost, tdn, tact)))
        elif typ == "recover":
            if st == 2:
                if o == dur:
                    res.append((0.0, (1, N, o, o, lost, tdn, t)))
                elif dur < o <= lost:
                    res.append((C_MISS, (1, N, o, o, lost, tdn, t)))
                elif o > lost:
                    res.append((C_MISS + C_GAP, (1, N, o, o, lost, tdn, t)))
            else:
                if dur <= o <= off:
                    res.append((C_RECACT, (1, N, o, o, lost, tdn, t)))
        return res

    def force(ss, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        if o is None:
            o = off
        if typ == "open":
            return (1, N, 0, 0, 0, 0, t)
        if typ == "write":
            return (1, N, o + l, dur, lost, tdn, tact)
        if typ == "checkpoint":
            return (1, N, o, o, lost, tdn, tact)
        if typ == "commit":
            return (3, N, o, o, lost, tdn, tact)
        if typ == "abort":
            return (4, nd, off, dur, lost, tdn, tact)
        if typ == "recover":
            return (1, N, o, o, lost, tdn, t)
        return ss

    def event_opts(h, k, exact=False):
        cost, ss, pend, chain, om = h
        e = evs[k]
        sid = e["sid"]
        typ = e["type"]
        N = e["node"]
        out = []
        anon = sid is None
        if not anon:
            q0 = sidx.get(sid)
            cands = [q0] if q0 is not None else []
        else:
            cands = range(S)
        newoff = (e["off"] or 0) + (e["len"] or 0)
        for q in cands:
            s = ss[q]
            st = s[0]
            if typ != "open":
                if st == 0 or st >= 3:
                    continue
                if anon and st == 1 and s[1] != N and typ != "recover":
                    continue
            elif st != 0:
                continue
            for c, ns in sess_opts(s, q, k):
                if anon and typ == "write":
                    c += look_cost(q, N, e["t"], newoff)
                if exact and c > 0.5:
                    continue
                out.append((c, ss[:q] + (ns,) + ss[q + 1:], q))
        if exact:
            return out
        dc = dupc[k]
        if dc:
            for j in dc:
                js = evs[j]["sid"]
                if js is not None:
                    q = sidx.get(js)
                else:
                    q = om.get(j) if om else None
                if q is None or q < 0:
                    continue
                if not anon and sidx.get(sid) != q:
                    continue
                out.append((C_DUP, ss, q))
        if not out:
            if not anon and sid in sidx:
                q = sidx[sid]
                out.append((C_FORCE, ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
            elif anon:
                o = e["off"] or 0
                best = []
                for q in range(S):
                    s = ss[q]
                    if s[0] == 0:
                        continue
                    sc = (0 if s[1] == N else 1, 0 if s[0] in (1, 2) else 1, abs(s[2] - o))
                    best.append((sc, q))
                best.sort()
                for sc, q in best[:2]:
                    out.append((C_FORCE + sc[0] + sc[1], ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
        if not out:
            out.append((C_FORCE * 2, ss, 0 if S else -1))
        return out

    def apply_opt(h, k, c, nss, q, remove_pending):
        cost, ss, pend, chain, om = h
        if remove_pending:
            pend = tuple(p for p in pend if p != k)
        if evs[k]["sid"] is None:
            chain = (k, q, chain)
            if k in is_orig:
                om = dict(om) if om else {}
                om[k] = q
        return (cost + c, nss, pend, chain, om)

    def flush(h, depth=0):
        pend = h[2]
        if not pend or depth > 6:
            return [h]
        for k in pend:
            opts = event_opts(h, k, True)
            if opts:
                res = []
                for c, nss, q in opts[:3]:
                    res.extend(flush(apply_opt(h, k, c, nss, q, True), depth + 1))
                return res
        return [h]

    def expire(h, tnow, final=False):
        hs = [h]
        while True:
            nhs = []
            changed = False
            for x in hs:
                old = None
                for k in x[2]:
                    if final or tnow - evs[k]["t"] > J:
                        old = k
                        break
                if old is None:
                    nhs.append(x)
                    continue
                changed = True
                for c, nss, q in event_opts(x, old):
                    nhs.append(apply_opt(x, old, c, nss, q, True))
            hs = nhs
            if not changed:
                return hs
            if len(hs) > 40:
                hs.sort(key=lambda z: z[0])
                hs = hs[:40]

    def crash(h, k):
        cost, ss, pend, chain, om = h
        e = evs[k]
        N = e["node"]
        t = e["t"]
        aff = []
        recent = []
        for q in range(S):
            s = ss[q]
            if s[0] == 1 and s[1] == N:
                aff.append(q)
                if t - s[6] <= J and s[6] > 0:
                    recent.append(q)

        def down(sset, qs):
            l = list(sset)
            for q in qs:
                s = l[q]
                l[q] = (2, s[1], s[3], s[3], s[2], t, s[6])
            return tuple(l)

        res = [(cost, down(ss, aff), pend, chain, om)]
        if recent:
            rest = [q for q in aff if q not in recent]
            res.append((cost + C_LATE, down(ss, rest), pend, chain, om))
        return res

    K = 48 if E * max(S, 4) <= 4000 else 32
    if E * S > 8000:
        K = 24
    beam = [(0.0, tuple((0, "", 0, 0, 0, 0, 0) for _ in range(S)), (), None, None)]
    budget = 0.45
    for k in range(E):
        e = evs[k]
        el = time.process_time() - t0
        frac = (k + 1) / max(E, 1)
        if el > budget * frac * 1.05 and K > 4:
            K = max(4, int(K * 0.8))
        elif el < budget * frac * 0.6 and K < 96:
            K += 1
        if el > 0.6:
            K = 1
        cand = []
        tnow = e["t"]
        for h in beam:
            for x in expire(h, tnow):
                if e["type"] == "crash":
                    cand.extend(crash(x, k))
                    continue
                if e["type"] not in SESSION_TYPES and e["type"] != "open":
                    cand.append(x)
                    continue
                for c, nss, q in event_opts(x, k):
                    cand.extend(flush(apply_opt(x, k, c, nss, q, False)))
                if e["type"] != "open" and len(x[2]) < MAXPEND and K > 4:
                    cand.append((x[0] + C_DEFER, x[1], x[2] + (k,), x[3], x[4]))
        if not cand:
            continue
        cand.sort(key=lambda z: z[0])
        seen = set()
        nb = []
        for z in cand:
            key = (z[1], z[2])
            if key in seen:
                continue
            seen.add(key)
            nb.append(z)
            if len(nb) >= K:
                break
        beam = nb
    finals = []
    for h in beam:
        finals.extend(expire(h, 0, True))
    finals.sort(key=lambda z: z[0])
    best = finals[0] if finals else beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        kk, q, ch = ch
        assign[kk] = q
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_a = {}
    seed = {}
    for k, e in enumerate(evs):
        if e["sid"] is None and e["type"] != "crash":
            q = assign.get(k)
            if q is None or q < 0 or q >= S:
                q = 0
            if S:
                out_a[str(e["i"])] = sids[q]
                seed[str(k)] = q
    sessions = {}
    for q, s in enumerate(sids):
        st = best[1][q]
        sessions[s] = {"status": names.get(st[0], "active"), "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": sessions}
    state["beam"] = {"seed": seed}
    return state


# ---------------- replay-based conservative descent ----------------

RTYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}
R_GAP = 1.0
R_BACK = 3.0
R_NODE = 4.0
R_END = 5.0
R_MISSREC = 1.0
R_MISSCP = 1.0
R_BADREC = 2.0
R_DUP = 0.2
R_CRASH = 0.15
R_RANK = 0.1
MARGIN = 0.5


def _estimate_window(evs):
    by = {}
    for r in evs:
        if r[6] is not None and r[2] in (1, 2, 3):
            by.setdefault(r[6], []).append(r)
    W = 0
    for lst in by.values():
        n = len(lst)
        for a in range(n):
            ra = lst[a]
            if ra[4] is None:
                continue
            for b in range(a + 1, min(n, a + 8)):
                rb = lst[b]
                if rb[2] == 1 and rb[4] is not None and rb[4] + rb[5] == ra[4]:
                    W = max(W, ra[0] - rb[0])
    ts = [r[0] for r in evs]
    gaps = sorted(ts[k + 1] - ts[k] for k in range(len(ts) - 1)) or [1]
    med = gaps[len(gaps) // 2]
    return max(W + 1, 3 * med, 2)


def _step(st, ty, node, off, ln):
    s = st[0]
    if ty == 0:
        if s == 0:
            st[0] = 1; st[1] = node; st[2] = 0; st[3] = 0; st[4] = 0
            return 0.0
        return R_END
    if s >= 3 or s == 0:
        return R_END
    cost = 0.0
    if s == 2:
        if ty == 5:
            st[0] = 1; st[1] = node
            if off is None or off == st[3]:
                st[2] = st[3]
                return 0.0
            if st[3] < off <= st[4]:
                cost = R_MISSCP
            else:
                cost = R_BACK
            st[2] = off; st[3] = off
            return cost
        cost += R_MISSREC
        st[0] = 1; st[1] = node; st[2] = st[3]
        if off is not None and ty in (1, 2, 3) and st[3] < off <= st[4]:
            cost += R_MISSCP
            st[2] = off; st[3] = off
    elif ty == 5:
        st[1] = node
        if off is not None:
            st[2] = off; st[3] = off
        return R_BADREC
    elif node != st[1]:
        cost += R_NODE
        st[1] = node
    cur = st[2]
    if ty == 1:
        if off is None:
            st[2] = cur + (ln or 0)
            return cost
        if off != cur:
            cost += R_GAP if off > cur else R_BACK
        st[2] = off + (ln or 0)
        return cost
    if ty == 2 or ty == 3:
        if off is not None and off != cur:
            cost += R_GAP if off > cur else R_BACK
            cur = off
        st[2] = cur; st[3] = cur
        if ty == 3:
            st[0] = 3
        return cost
    if ty == 4:
        st[0] = 4
    return cost


def _replay(items, crashes, W, final=False):
    cost = 0.0
    seen = set()
    prim = []
    for it in items:
        if it[2] != 0:
            sig = (it[2], it[3], it[4], it[5])
            if sig in seen:
                cost += R_DUP
                continue
            seen.add(sig)
        prim.append(it)
    if not prim:
        st = [0, None, 0, 0, 0]
        return (cost, st) if final else cost
    t0 = prim[0][0] - W
    ci = bisect.bisect_left(crashes, (t0,))
    merged = prim
    if ci < len(crashes):
        merged = sorted(prim + crashes[ci:])
    st = [0, None, 0, 0, 0]
    n = len(merged)
    done = [False] * n
    p = 0
    while p < n:
        if done[p]:
            p += 1
            continue
        tlim = merged[p][0] + W
        best = -1
        bv = 1e18
        bst = None
        rank = 0
        q = p
        while q < n and rank < 5:
            if done[q]:
                q += 1
                continue
            it = merged[q]
            if it[0] > tlim:
                break
            if it[2] == 6:
                if st[0] == 1 and st[1] == it[3]:
                    v = R_CRASH + R_RANK * rank
                    if v < bv:
                        bv = v; best = q; bst = None
                elif rank == 0:
                    if 0.0 < bv:
                        bv = 0.0; best = q; bst = None
            else:
                s2 = st[:]
                c = _step(s2, it[2], it[3], it[4], it[5])
                v = c + R_RANK * rank
                if v < bv:
                    bv = v; best = q; bst = (s2, c)
            rank += 1
            q += 1
        if best < 0:
            best = p
            bst = None
        it = merged[best]
        done[best] = True
        if it[2] == 6:
            if st[0] == 1 and st[1] == it[3]:
                st[0] = 2; st[4] = st[2]; st[2] = st[3]
        else:
            if bst is None:
                c = _step(st, it[2], it[3], it[4], it[5])
            else:
                st = bst[0]
                c = bst[1]
            cost += c
    return (cost, st) if final else cost


def refine(state, params):
    T0 = time.perf_counter()
    P0 = time.process_time()
    prep = state.get("prep") or {}
    beamres = state.get("beam") or {}
    out = state.get("output")
    if not out or not prep:
        return state
    sessions = prep.get("sids") or []
    S = len(sessions)
    p_start = prep.get("p0", P0)
    budget = min(0.3, 0.85 - (P0 - p_start))
    if S < 2 or budget < 0.03:
        return state
    seed = beamres.get("seed") or {}
    pe = prep["events"]
    evs = []
    for k, e in enumerate(pe):
        ty = RTYPES.get(e["type"], -1)
        if ty < 0:
            continue
        sid = e["sid"]
        sid = str(sid) if sid is not None else None
        evs.append([e["t"], k, ty, e["node"], e["off"], e["len"] or 0, sid])
    if not evs:
        return state
    W = _estimate_window(evs)
    crashes = [tuple(r[:6]) for r in evs if r[2] == 6]
    sname = [str(s) for s in sessions]
    sidx = {s: q for q, s in enumerate(sname)}
    open_t = {}
    for r in evs:
        if r[2] == 0 and r[6] is not None and r[6] not in open_t:
            open_t[r[6]] = (r[0], r[1])
    for r in evs:
        if r[6] is not None and r[2] != 6 and r[6] not in open_t:
            open_t[r[6]] = (r[0] - 1, -1)
    lists = [[] for _ in range(S)]
    var_items = []
    var_cands = []
    assign = []
    for r in evs:
        if r[2] == 6:
            continue
        it = tuple(r[:6])
        if r[6] is not None:
            q = sidx.get(r[6])
            if q is not None:
                lists[q].append(it)
            continue
        q = seed.get(str(r[1]), 0)
        if q is None or q < 0 or q >= S:
            q = 0
        c = [j for j in range(S) if sname[j] in open_t and open_t[sname[j]] <= (r[0], r[1])]
        if q not in c:
            c.append(q)
        var_items.append(it)
        var_cands.append(c)
        assign.append(q)
    V = len(var_items)
    for v in range(V):
        lists[assign[v]].append(var_items[v])
    for L in lists:
        L.sort()
    costs = [_replay(lists[q], crashes, W) for q in range(S)]
    touched = set()

    def elapsed():
        return max(time.perf_counter() - T0, time.process_time() - P0)

    def remove(q, it):
        L = lists[q]
        j = bisect.bisect_left(L, it)
        if j < len(L) and L[j] == it:
            del L[j]

    rng = random.Random(9173)
    movable = [v for v in range(V) if len(var_cands[v]) > 1]
    it_count = 0
    if movable:
        while True:
            if (it_count & 15) == 0 and elapsed() > budget:
                break
            it_count += 1
            v = movable[rng.randrange(len(movable))]
            a = assign[v]
            cands = var_cands[v]
            b = cands[rng.randrange(len(cands))]
            if b == a:
                continue
            if rng.random() < 0.2:
                tv = var_items[v][0:2]
                ma = [u for u in range(V) if assign[u] == a and var_items[u][0:2] >= tv and b in var_cands[u]]
                mb = [u for u in range(V) if assign[u] == b and var_items[u][0:2] >= tv and a in var_cands[u]]
                for u in ma:
                    remove(a, var_items[u]); bisect.insort(lists[b], var_items[u])
                for u in mb:
                    remove(b, var_items[u]); bisect.insort(lists[a], var_items[u])
                ca = _replay(lists[a], crashes, W)
                cb = _replay(lists[b], crashes, W)
                d = ca + cb - costs[a] - costs[b]
                if d < -MARGIN:
                    for u in ma:
                        assign[u] = b
                    for u in mb:
                        assign[u] = a
                    costs[a] = ca; costs[b] = cb
                    touched.add(a); touched.add(b)
                else:
                    for u in ma:
                        remove(b, var_items[u]); bisect.insort(lists[a], var_items[u])
                    for u in mb:
                        remove(a, var_items[u]); bisect.insort(lists[b], var_items[u])
                continue
            it = var_items[v]
            remove(a, it)
            bisect.insort(lists[b], it)
            ca = _replay(lists[a], crashes, W)
            cb = _replay(lists[b], crashes, W)
            d = ca + cb - costs[a] - costs[b]
            if d < -MARGIN:
                assign[v] = b
                costs[a] = ca; costs[b] = cb
                touched.add(a); touched.add(b)
            else:
                remove(b, it)
                bisect.insort(lists[a], it)

    if not touched:
        return state
    out_a = dict(out.get("assignments") or {})
    for v in range(V):
        k = var_items[v][1]
        out_a[str(pe[k]["i"])] = sessions[assign[v]]
    out_s = dict(out.get("sessions") or {})
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    for q in touched:
        c, st = _replay(lists[q], crashes, W, final=True)
        dur = st[2] if st[0] == 3 else st[3]
        out_s[sessions[q]] = {"status": names.get(st[0], "active"), "durable": int(dur or 0)}
    state["output"] = {"assignments": out_a, "sessions": out_s}
    return state

import time
import bisect

SESSION_TYPES = ("write", "checkpoint", "commit", "abort", "recover")


def _gi(x):
    try:
        return int(x) if x is not None else None
    except Exception:
        return None


def prepare(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        evs.append({
            "i": e.get("i", k), "t": _gi(e.get("t")) or 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _gi(e.get("off")), "len": _gi(e.get("len")),
            "sid": e.get("sid"),
        })
    evs.sort(key=lambda e: (e["t"], e["i"] if isinstance(e["i"], int) else 0))
    sids = []
    seen = set()
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in seen:
            seen.add(e["sid"])
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["sid"] not in seen and e["type"] != "crash":
            seen.add(e["sid"])
            sids.append(e["sid"])
    gaps = sorted(g for g in (evs[k + 1]["t"] - evs[k]["t"] for k in range(len(evs) - 1)) if g >= 0)
    med = gaps[len(gaps) // 2] if gaps else 1
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])
    obs = 0
    bys = {}
    for e in evs:
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None and e["len"] is not None:
            bys.setdefault(e["sid"], []).append(e)
    for s, lst in bys.items():
        for a in range(len(lst)):
            A = lst[a]
            for b in range(a + 1, min(len(lst), a + 12)):
                B = lst[b]
                if B["node"] == A["node"] and B["off"] + B["len"] <= A["off"] and B["t"] > A["t"]:
                    ct = crash_t.get(A["node"], [])
                    p = bisect.bisect_left(ct, A["t"])
                    if p < len(ct) and ct[p] <= B["t"]:
                        continue
                    obs = max(obs, B["t"] - A["t"])
    J = max(int(obs * 1.5) + 1, 4 * med, 2)
    state["prep"] = {"events": evs, "sids": sids, "J": J}
    return state


def beam_search(state, params):
    t0 = time.process_time()
    prep = state["prep"]
    evs = prep["events"]
    sids = prep["sids"]
    J = prep["J"]
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    E = len(evs)
    C_GAP, C_MISS, C_DUP, C_DEFER, C_LATE = 2.0, 2.0, 1.0, 0.4, 1.0
    C_RECACT, C_FORCE, C_ABORT, C_LOOK = 3.0, 15.0, 0.1, 1.5
    C_TERM, C_DUPHINT = 6.0, 0.6
    MAXPEND = 3

    sigmap = {}
    dupc = [None] * E
    is_orig = set()
    for k, e in enumerate(evs):
        if e["type"] in SESSION_TYPES:
            sig = (e["node"], e["type"], e["off"], e["len"])
            prev = sigmap.get(sig)
            if prev:
                dupc[k] = list(prev[-4:])
                for j in prev[-4:]:
                    if evs[j]["sid"] is None:
                        is_orig.add(j)
            sigmap.setdefault(sig, []).append(k)
    # later labelled copies with the same signature (duplicate hint)
    dup_hint = [None] * E
    for sig, lst in sigmap.items():
        for a in range(len(lst)):
            ka = lst[a]
            if evs[ka]["sid"] is not None:
                continue
            hs = set()
            for b in range(a + 1, min(len(lst), a + 4)):
                sb = evs[lst[b]]["sid"]
                if sb is not None and sb in sidx:
                    hs.add(sidx[sb])
            if hs:
                dup_hint[ka] = hs

    lab_t = [[] for _ in range(S)]
    lab_e = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["sid"] is not None and e["sid"] in sidx and e["type"] in SESSION_TYPES:
            q = sidx[e["sid"]]
            lab_t[q].append(e["t"])
            lab_e[q].append(k)
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])

    def crashed_between(node, ta, tb):
        ct = crash_t.get(node)
        if not ct:
            return False
        c = bisect.bisect_left(ct, ta)
        return c < len(ct) and ct[c] <= tb

    def look_cost(q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        t = e["t"]
        lt = lab_t[q]
        le = lab_e[q]
        p = bisect.bisect_right(lt, t + J)
        f = None
        while p < len(lt):
            idx = le[p]
            if dupc[idx]:
                p += 1
                continue
            f = evs[idx]
            break
        if f is None:
            return 0.0
        if typ == "commit" or typ == "abort":
            return C_TERM
        if crashed_between(N, t - J, f["t"]):
            return 0.0
        if f["type"] == "recover":
            return C_LOOK
        if f["node"] != N:
            return C_LOOK
        if f["type"] in ("write", "checkpoint", "commit") and f["off"] is not None:
            o = e["off"] or 0
            newoff = o + (e["len"] or 0) if typ == "write" else o
            if f["off"] < newoff:
                return C_LOOK
        return 0.0

    def sess_opts(ss, q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        res = []
        if typ == "open":
            if st == 0:
                res.append((0.0, (1, N, 0, 0, 0, 0, t)))
            return res
        if st == 0 or st >= 3:
            return res
        if o is None and typ != "abort":
            o = off
        if typ == "write":
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (1, nd, o + l, dur, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (1, nd, o + l, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (2, nd, off, dur, o + l, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (1, N, o + l, dur, lost, tdn, t)))
        elif typ == "checkpoint" or typ == "commit":
            ns = 1 if typ == "checkpoint" else 3
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (ns, nd, o, o, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (ns, nd, o, o, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    nst = 2 if ns == 1 else 3
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (nst, nd, o, o, o, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (ns, N, o, o, lost, tdn, t)))
        elif typ == "abort":
            if st == 1:
                if nd == N:
                    res.append((C_ABORT, (4, nd, off, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N:
                    res.append((C_LATE, (4, nd, off, dur, lost, tdn, tact)))
                res.append((C_MISS, (4, N, off, dur, lost, tdn, tact)))
        elif typ == "recover":
            if st == 2:
                if o == dur:
                    res.append((0.0, (1, N, o, o, lost, tdn, t)))
                elif dur < o <= lost:
                    res.append((C_MISS, (1, N, o, o, lost, tdn, t)))
                elif o > lost:
                    res.append((C_MISS + C_GAP, (1, N, o, o, lost, tdn, t)))
            else:
                if dur <= o <= off:
                    res.append((C_RECACT, (1, N, o, o, lost, tdn, t)))
        return res

    def force(ss, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        if o is None:
            o = off
        if typ == "open":
            return (1, N, 0, 0, 0, 0, t)
        if typ == "write":
            return (1, N, o + l, dur, lost, tdn, tact)
        if typ == "checkpoint":
            return (1, N, o, o, lost, tdn, tact)
        if typ == "commit":
            return (3, N, o, o, lost, tdn, tact)
        if typ == "abort":
            return (4, nd, off, dur, lost, tdn, tact)
        if typ == "recover":
            return (1, N, o, o, lost, tdn, t)
        return ss

    look_cache = {}

    def lc(q, k):
        key = q * (E + 1) + k
        v = look_cache.get(key)
        if v is None:
            v = look_cost(q, k)
            hs = dup_hint[k]
            if hs is not None and q not in hs:
                v += C_DUPHINT
            look_cache[key] = v
        return v

    def event_opts(h, k, exact=False):
        cost, ss, pend, chain, om = h
        e = evs[k]
        sid = e["sid"]
        typ = e["type"]
        N = e["node"]
        out = []
        anon = sid is None
        if not anon:
            q0 = sidx.get(sid)
            cands = [q0] if q0 is not None else []
        else:
            cands = range(S)
        for q in cands:
            s = ss[q]
            st = s[0]
            if typ != "open":
                if st == 0 or st >= 3:
                    continue
                if anon and st == 1 and s[1] != N and typ != "recover":
                    continue
            elif st != 0:
                continue
            for c, ns in sess_opts(s, q, k):
                if anon and typ != "open":
                    c += lc(q, k)
                if exact and c > 0.5:
                    continue
                out.append((c, ss[:q] + (ns,) + ss[q + 1:], q))
        if exact:
            return out
        dc = dupc[k]
        if dc:
            for j in dc:
                js = evs[j]["sid"]
                if js is not None:
                    q = sidx.get(js)
                else:
                    q = om.get(j) if om else None
                if q is None or q < 0:
                    continue
                if not anon and sidx.get(sid) != q:
                    continue
                out.append((C_DUP, ss, q))
        if not out:
            if not anon and sid in sidx:
                q = sidx[sid]
                out.append((C_FORCE, ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
            elif anon:
                o = e["off"] or 0
                best = []
                for q in range(S):
                    s = ss[q]
                    if s[0] == 0:
                        continue
                    sc = (0 if s[1] == N else 1, 0 if s[0] in (1, 2) else 1, abs(s[2] - o))
                    best.append((sc, q))
                best.sort()
                for sc, q in best[:2]:
                    out.append((C_FORCE + sc[0] + sc[1], ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
        if not out:
            out.append((C_FORCE * 2, ss, 0 if S else -1))
        return out

    def apply_opt(h, k, c, nss, q, remove_pending):
        cost, ss, pend, chain, om = h
        if remove_pending:
            pend = tuple(p for p in pend if p != k)
        if evs[k]["sid"] is None:
            chain = (k, q, chain)
            if k in is_orig:
                om = dict(om) if om else {}
                om[k] = q
        return (cost + c, nss, pend, chain, om)

    def flush(h, depth=0):
        pend = h[2]
        if not pend or depth > 6:
            return [h]
        for k in pend:
            opts = event_opts(h, k, True)
            if opts:
                res = []
                for c, nss, q in opts[:3]:
                    res.extend(flush(apply_opt(h, k, c, nss, q, True), depth + 1))
                return res
        return [h]

    def expire(h, tnow, final=False):
        hs = [h]
        while True:
            nhs = []
            changed = False
            for x in hs:
                old = None
                for k in x[2]:
                    if final or tnow - evs[k]["t"] > J:
                        old = k
                        break
                if old is None:
                    nhs.append(x)
                    continue
                changed = True
                for c, nss, q in event_opts(x, old):
                    nhs.append(apply_opt(x, old, c, nss, q, True))
            hs = nhs
            if not changed:
                return hs
            if len(hs) > 40:
                hs.sort(key=lambda z: z[0])
                hs = hs[:40]

    def crash(h, k):
        cost, ss, pend, chain, om = h
        e = evs[k]
        N = e["node"]
        t = e["t"]
        aff = []
        recent = []
        for q in range(S):
            s = ss[q]
            if s[0] == 1 and s[1] == N:
                aff.append(q)
                if t - s[6] <= J and s[6] > 0:
                    recent.append(q)

        def down(sset, qs):
            l = list(sset)
            for q in qs:
                s = l[q]
                l[q] = (2, s[1], s[3], s[3], s[2], t, s[6])
            return tuple(l)

        res = [(cost, down(ss, aff), pend, chain, om)]
        if recent:
            rest = [q for q in aff if q not in recent]
            res.append((cost + C_LATE, down(ss, rest), pend, chain, om))
        return res

    K = 48 if E * max(S, 4) <= 4000 else 32
    if E * S > 8000:
        K = 24
    beam = [(0.0, tuple((0, "", 0, 0, 0, 0, 0) for _ in range(S)), (), None, None)]
    budget = 0.7
    for k in range(E):
        e = evs[k]
        el = time.process_time() - t0
        frac = (k + 1) / max(E, 1)
        if el > budget * frac * 1.05 and K > 4:
            K = max(4, int(K * 0.8))
        elif el < budget * frac * 0.6 and K < 96:
            K += 1
        if el > 1.0:
            K = 1
        cand = []
        tnow = e["t"]
        for h in beam:
            for x in expire(h, tnow):
                if e["type"] == "crash":
                    cand.extend(crash(x, k))
                    continue
                if e["type"] not in SESSION_TYPES and e["type"] != "open":
                    cand.append(x)
                    continue
                for c, nss, q in event_opts(x, k):
                    cand.extend(flush(apply_opt(x, k, c, nss, q, False)))
                if e["type"] != "open" and len(x[2]) < MAXPEND and K > 4:
                    cand.append((x[0] + C_DEFER, x[1], x[2] + (k,), x[3], x[4]))
        if not cand:
            continue
        cand.sort(key=lambda z: z[0])
        seen = set()
        nb = []
        for z in cand:
            key = (z[1], z[2])
            if key in seen:
                continue
            seen.add(key)
            nb.append(z)
            if len(nb) >= K:
                break
        beam = nb
    finals = []
    for h in beam:
        finals.extend(expire(h, 0, True))
    finals.sort(key=lambda z: z[0])
    best = finals[0] if finals else beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        kk, q, ch = ch
        assign[kk] = q
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_a = {}
    for k, e in enumerate(evs):
        if e["sid"] is None and e["type"] != "crash":
            q = assign.get(k)
            if q is None or q < 0 or q >= S:
                q = 0
            if S:
                out_a[str(e["i"])] = sids[q]
    sessions = {}
    for q, s in enumerate(sids):
        st = best[1][q]
        sessions[s] = {"status": names.get(st[0], "active"), "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": sessions}
    return state

import bisect
import statistics


def _num(x):
    if x is None:
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def solve(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    E = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        sid = e.get("sid")
        E.append({
            "i": e.get("i", k), "t": _num(e.get("t")) or 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _num(e.get("off")), "len": _num(e.get("len")),
            "sid": (str(sid) if sid is not None else None), "k": k,
        })
    E.sort(key=lambda e: (e["t"], e["k"]))

    ts = [e["t"] for e in E]
    dts = [ts[j + 1] - ts[j] for j in range(len(ts) - 1) if ts[j + 1] > ts[j]]
    med = statistics.median(dts) if dts else 1
    J = max(2.0, 6.0 * med)
    lens = [e["len"] for e in E if e["type"] == "write" and e["len"]]
    scale = float(statistics.median(lens)) if lens else 100.0

    S = {}
    order_sids = []

    def mk(sid):
        if sid not in S:
            S[sid] = {"status": "new", "node": None, "off": 0, "dur": 0, "gaps": [], "ends": {0},
                      "seen": set(), "pre": 0, "ct": -10 ** 9, "cn": None, "last": -10 ** 9,
                      "skip": None, "final": 0}
            order_sids.append(sid)
        return S[sid]

    for e in E:
        if e["sid"] is not None and e["type"] != "crash":
            mk(e["sid"])

    lab = {}
    for e in E:
        if e["sid"] is not None and e["type"] not in ("crash", "open"):
            lab.setdefault(e["sid"], []).append(e)
    labtk = {sid: [(x["t"], x["k"]) for x in L] for sid, L in lab.items()}
    labt = {sid: [x["t"] for x in L] for sid, L in lab.items()}

    def nxt_lab(sid, t, k):
        L = lab.get(sid)
        if not L:
            return None
        j = bisect.bisect_right(labtk[sid], (t, k))
        return L[j] if j < len(L) else None

    def future_lab_after(sid, t):
        L = lab.get(sid)
        if not L:
            return False
        return bisect.bisect_right(labt[sid], t) < len(L)

    def key(e):
        return (e["node"], e["type"], e["off"], e["len"])

    def gap_fit(s, N, o, L, t):
        best = None
        if o is None:
            return None
        for gi, g in enumerate(s["gaps"]):
            if g[0] != N:
                continue
            if g[1] <= o and o + L <= g[2]:
                if o == g[1] and o + L == g[2]:
                    c = 0.1
                elif o == g[1] or o + L == g[2]:
                    c = 0.15
                else:
                    c = 0.2
                c += 0.1 * min(3.0, max(0.0, t - g[3]) / J)
                if best is None or c < best[0]:
                    best = (c, gi)
        return best

    def look_adj(sid, e, newoff):
        n = nxt_lab(sid, e["t"], e["k"])
        if n is None:
            return 0.0
        adj = 0.0
        if n["type"] in ("write", "checkpoint", "commit"):
            if n["node"] == e["node"]:
                if n["off"] == newoff:
                    adj -= 0.3
                elif n["off"] is not None and newoff is not None and n["off"] < newoff:
                    adj += 0.4
            else:
                adj += 0.3
        elif n["type"] == "abort":
            if n["node"] != e["node"]:
                adj += 0.2
        return adj

    def options(sid, e):
        s = S[sid]
        st = s["status"]
        N, ty, o, L, t = e["node"], e["type"], e["off"], e["len"], e["t"]
        opts = []
        if st == "new":
            return opts
        recent_crash = (st == "down" and s["cn"] == N and t - s["ct"] <= 3 * J)
        if ty == "write":
            if o is None:
                return opts
            L = L or 0
            if st == "active":
                if s["node"] == N:
                    if s["off"] == o:
                        opts.append((0.0 + look_adj(sid, e, o + L), "exact"))
                    elif o > s["off"]:
                        opts.append((1.0 + 0.2 * min(1.0, (o - s["off"]) / (4 * scale))
                                     + look_adj(sid, e, o + L), "jump"))
                elif o >= s["dur"]:
                    opts.append((3.0 + look_adj(sid, e, o + L), "move"))
            gf = gap_fit(s, N, o, L, t)
            if gf is not None:
                opts.append((gf[0], ("gap", gf[1])))
            if st == "down":
                if recent_crash and o == s["pre"]:
                    opts.append((0.4, "late"))
                if o == s["dur"]:
                    opts.append((1.5 + look_adj(sid, e, o + L), "implicit"))
                elif o > s["dur"]:
                    opts.append((2.0 + look_adj(sid, e, o + L), "implicit"))
        elif ty in ("checkpoint", "commit"):
            if o is None:
                return opts
            if st == "active":
                if s["node"] == N:
                    if s["off"] == o:
                        c = 0.0 if (ty == "commit" or s["dur"] != o) else 0.05
                        opts.append((c + look_adj(sid, e, o), "exact"))
                    elif o > s["off"]:
                        opts.append((1.0 + 0.2 * min(1.0, (o - s["off"]) / (4 * scale))
                                     + look_adj(sid, e, o), "jump"))
                    elif ty == "checkpoint" and o in s["ends"]:
                        opts.append((0.3 if o > s["dur"] else 0.35, "late"))
                    elif ty == "commit":
                        opts.append((1.8, "set"))
                elif o >= s["dur"]:
                    opts.append((3.0 + look_adj(sid, e, o), "move"))
            elif st == "down":
                if recent_crash and (o == s["pre"] or (ty == "checkpoint" and o in s["ends"] and o > s["dur"])):
                    opts.append((0.4, "late"))
                if o == s["dur"]:
                    opts.append((1.5 + look_adj(sid, e, o), "implicit"))
                elif o > s["dur"]:
                    opts.append((2.0 + look_adj(sid, e, o), "implicit"))
            elif st == "committed" and ty == "checkpoint":
                if o in s["ends"] and t - s["last"] <= 3 * J and o <= s["final"]:
                    opts.append((0.5, "noop"))
        elif ty == "abort":
            fut = 2.0 if future_lab_after(sid, t + J) else 0.0
            if st == "active" and s["node"] == N:
                rec = 0.1 * min(1.0, max(0.0, t - s["last"]) / (20 * J))
                opts.append((0.5 + fut + rec, "abort"))
            elif st == "down":
                opts.append(((0.8 if recent_crash else 2.5) + fut, "abort"))
        elif ty == "recover":
            if o is None:
                o = s["dur"]
            n = nxt_lab(sid, t, e["k"])
            adj = 0.0
            if n is not None:
                if n["node"] == N:
                    adj -= 0.3
                    if n["type"] in ("write", "checkpoint", "commit") and n["off"] == o:
                        adj -= 0.2
                elif n["type"] != "recover":
                    adj += 0.3
            if st == "down":
                if o == s["dur"]:
                    opts.append((0.0 + adj, "recover"))
                elif o > s["dur"]:
                    opts.append((0.8 + adj, "recover"))
                else:
                    opts.append((1.5 + adj, "recover"))
            elif st == "active":
                if s["dur"] == o or s["off"] == o:
                    opts.append((1.2 + adj, "early"))
                else:
                    opts.append((2.5 + adj, "early"))
        if key(e) in s["seen"]:
            opts.append((0.25, "dup"))
        return opts

    def apply(sid, e, act):
        s = S[sid]
        N, ty, o, L, t = e["node"], e["type"], e["off"], e["len"], e["t"]
        L = L or 0
        if act == "dup" or act == "noop":
            return
        s["seen"].add(key(e))
        if isinstance(act, tuple) and act[0] == "gap":
            g = s["gaps"].pop(act[1])
            if o > g[1]:
                s["gaps"].append([g[0], g[1], o, g[3]])
            if o + L < g[2]:
                s["gaps"].append([g[0], o + L, g[2], g[3]])
            s["ends"].add(o + L)
            s["ends"].add(o)
            return
        if act == "late":
            if ty == "write":
                if o == s["pre"]:
                    s["pre"] = o + L
                s["ends"].add(o + L)
            elif ty == "checkpoint":
                if o > s["dur"]:
                    s["dur"] = o
            elif ty == "commit":
                s["status"] = "committed"
                s["final"] = o
                s["dur"] = o
            return
        if ty == "abort":
            s["status"] = "aborted"
            s["last"] = t
            return
        if ty == "recover":
            if o is None:
                o = s["dur"]
            if act == "early" and s["node"] == N:
                s["skip"] = [N, t]
            s["status"] = "active"
            s["node"] = N
            s["off"] = o
            s["dur"] = o
            s["ends"].add(o)
            s["last"] = t
            return
        if act in ("implicit", "move"):
            if s["status"] == "down":
                s["off"] = s["dur"]
            s["status"] = "active"
            s["node"] = N
        if act in ("jump", "implicit", "move") and o is not None and o > s["off"]:
            s["gaps"].append([N, s["off"], o, t])
        if ty == "write":
            s["off"] = o + L
            s["ends"].add(o + L)
        elif ty == "checkpoint":
            s["off"] = o
            s["dur"] = o
            s["ends"].add(o)
        elif ty == "commit":
            s["off"] = o
            s["dur"] = o
            s["final"] = o
            s["status"] = "committed"
            s["ends"].add(o)
        s["last"] = t

    def force(sid, e):
        s = S[sid]
        N, ty, o, L, t = e["node"], e["type"], e["off"], e["len"] or 0, e["t"]
        s["seen"].add(key(e))
        if s["status"] in ("committed", "aborted"):
            return
        same = (s["status"] == "active" and s["node"] == N)
        if ty == "write" and o is not None:
            if same and o + L <= s["off"]:
                pass
            else:
                s["status"] = "active"; s["node"] = N; s["off"] = o + L; s["ends"].add(o + L)
        elif ty == "checkpoint" and o is not None:
            if same and o <= s["off"]:
                s["dur"] = max(s["dur"], o)
            else:
                s["status"] = "active"; s["node"] = N; s["off"] = o; s["dur"] = o
            s["ends"].add(o)
        elif ty == "commit" and o is not None:
            s["status"] = "committed"; s["off"] = o; s["dur"] = o; s["final"] = o
        elif ty == "abort":
            s["status"] = "aborted"
        elif ty == "recover":
            s["status"] = "active"; s["node"] = N
            if o is not None:
                s["off"] = o; s["dur"] = o
        s["last"] = t

    assign = {}
    for e in E:
        ty = e["type"]
        if ty == "crash":
            N = e["node"]
            for sid in order_sids:
                s = S[sid]
                if s["status"] == "active" and s["node"] == N:
                    sk = s["skip"]
                    if sk is not None and sk[0] == N and e["t"] - sk[1] <= 3 * J:
                        s["skip"] = None
                        continue
                    s["status"] = "down"
                    s["pre"] = s["off"]
                    s["off"] = s["dur"]
                    s["cn"] = N
                    s["ct"] = e["t"]
            continue
        sid = e["sid"]
        if ty == "open" and sid is not None:
            s = mk(sid)
            if s["status"] == "new":
                s["status"] = "active"; s["node"] = e["node"]; s["off"] = 0; s["dur"] = 0
                s["last"] = e["t"]
            continue
        if sid is not None:
            s = mk(sid)
            if s["status"] == "new":
                s["status"] = "active"; s["node"] = e["node"]
            opts = options(sid, e)
            if opts:
                opts.sort(key=lambda x: x[0])
                if opts[0][0] < 2.9 or opts[0][1] == "dup":
                    apply(sid, e, opts[0][1])
                else:
                    force(sid, e)
            else:
                force(sid, e)
            continue
        best = None
        for sid2 in order_sids:
            for c, act in options(sid2, e):
                if best is None or c < best[0] - 1e-12:
                    best = (c, sid2, act)
        if best is None:
            cand = None
            for sid2 in order_sids:
                s = S[sid2]
                if s["status"] == "new":
                    continue
                sc = (1 if s["node"] == e["node"] else 0, s["last"])
                if cand is None or sc > cand[0]:
                    cand = (sc, sid2)
            if cand is None and order_sids:
                cand = (None, order_sids[0])
            if cand is not None:
                assign[str(e["i"])] = cand[1]
            continue
        assign[str(e["i"])] = best[1]
        apply(best[1], e, best[2])

    sessions = {}
    for sid in order_sids:
        s = S[sid]
        st = s["status"]
        if st == "new":
            st = "active"
        d = s["final"] if st == "committed" else s["dur"]
        sessions[sid] = {"status": st, "durable": int(d)}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

import time
import bisect

SESSION_TYPES = ("write", "checkpoint", "commit", "abort", "recover")


def _gi(x):
    try:
        return int(x) if x is not None else None
    except Exception:
        return None


def prepare(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        evs.append({
            "i": e.get("i", k), "t": _gi(e.get("t")) or 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _gi(e.get("off")), "len": _gi(e.get("len")),
            "sid": e.get("sid"),
        })
    evs.sort(key=lambda e: (e["t"], e["i"] if isinstance(e["i"], int) else 0))
    sids = []
    seen = set()
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in seen:
            seen.add(e["sid"])
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["sid"] not in seen and e["type"] != "crash":
            seen.add(e["sid"])
            sids.append(e["sid"])
    gaps = sorted(g for g in (evs[k + 1]["t"] - evs[k]["t"] for k in range(len(evs) - 1)) if g >= 0)
    med = gaps[len(gaps) // 2] if gaps else 1
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])
    obs = 0
    bys = {}
    for e in evs:
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None and e["len"] is not None:
            bys.setdefault(e["sid"], []).append(e)
    for s, lst in bys.items():
        for a in range(len(lst)):
            A = lst[a]
            for b in range(a + 1, min(len(lst), a + 12)):
                B = lst[b]
                if B["node"] == A["node"] and B["off"] + B["len"] <= A["off"] and B["t"] > A["t"]:
                    ct = crash_t.get(A["node"], [])
                    p = bisect.bisect_left(ct, A["t"])
                    if p < len(ct) and ct[p] <= B["t"]:
                        continue
                    obs = max(obs, B["t"] - A["t"])
    J = max(int(obs * 1.5) + 1, 4 * med, 2)
    state["prep"] = {"events": evs, "sids": sids, "J": J}
    return state


def beam_search(state, params):
    t0 = time.process_time()
    prep = state["prep"]
    evs = prep["events"]
    sids = prep["sids"]
    J = prep["J"]
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    E = len(evs)
    C_GAP, C_MISS, C_DUP, C_DEFER, C_LATE = 2.0, 2.0, 1.0, 0.4, 1.0
    C_RECACT, C_FORCE, C_ABORT, C_LOOK = 3.0, 15.0, 0.1, 1.5
    C_TERM, C_DUPHINT, C_TIE = 6.0, 0.6, 0.5
    MAXPEND = 3

    sigmap = {}
    dupc = [None] * E
    is_orig = set()
    for k, e in enumerate(evs):
        if e["type"] in SESSION_TYPES:
            sig = (e["node"], e["type"], e["off"], e["len"])
            prev = sigmap.get(sig)
            if prev:
                dupc[k] = list(prev[-4:])
                for j in prev[-4:]:
                    if evs[j]["sid"] is None:
                        is_orig.add(j)
            sigmap.setdefault(sig, []).append(k)
    dup_hint = [None] * E
    for sig, lst in sigmap.items():
        for a in range(len(lst)):
            ka = lst[a]
            if evs[ka]["sid"] is not None:
                continue
            hs = set()
            for b in range(a + 1, min(len(lst), a + 4)):
                sb = evs[lst[b]]["sid"]
                if sb is not None and sb in sidx:
                    hs.add(sidx[sb])
            if hs:
                dup_hint[ka] = hs

    lab_t = [[] for _ in range(S)]
    lab_e = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["sid"] is not None and e["sid"] in sidx and e["type"] in SESSION_TYPES:
            q = sidx[e["sid"]]
            lab_t[q].append(e["t"])
            lab_e[q].append(k)
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])

    def crashed_between(node, ta, tb):
        ct = crash_t.get(node)
        if not ct:
            return False
        c = bisect.bisect_left(ct, ta)
        return c < len(ct) and ct[c] <= tb

    def look_cost(q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        t = e["t"]
        lt = lab_t[q]
        le = lab_e[q]
        p = bisect.bisect_right(lt, t + J)
        f = None
        while p < len(lt):
            idx = le[p]
            if dupc[idx]:
                p += 1
                continue
            f = evs[idx]
            break
        if f is None:
            return 0.0
        if typ == "commit" or typ == "abort":
            return C_TERM
        if crashed_between(N, t - J, f["t"]):
            return 0.0
        if f["type"] == "recover":
            return C_LOOK
        if f["node"] != N:
            return C_LOOK
        if f["type"] in ("write", "checkpoint", "commit") and f["off"] is not None:
            o = e["off"] or 0
            newoff = o + (e["len"] or 0) if typ == "write" else o
            if f["off"] < newoff:
                return C_LOOK
        return 0.0

    def cont_cost(q, k):
        e = evs[k]
        typ = e["type"]
        if typ not in ("write", "checkpoint", "commit"):
            return 0.0
        o = e["off"]
        if o is None:
            return 0.0
        N = e["node"]
        t = e["t"]
        end = o + (e["len"] or 0) if typ == "write" else o
        lt = lab_t[q]
        le = lab_e[q]
        W = 3 * J
        p = bisect.bisect_left(lt, t - W)
        while p < len(lt) and lt[p] <= t + W:
            idx = le[p]
            p += 1
            if idx == k:
                continue
            f = evs[idx]
            if f["node"] != N or f["off"] is None:
                continue
            ft = f["type"]
            if ft in ("write", "checkpoint", "commit") and f["off"] == end:
                return 0.0
            if ft == "write" and f["len"] is not None and f["off"] + f["len"] == o:
                return 0.0
        return C_TIE

    def sess_opts(ss, q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        res = []
        if typ == "open":
            if st == 0:
                res.append((0.0, (1, N, 0, 0, 0, 0, t)))
            return res
        if st == 0 or st >= 3:
            return res
        if o is None and typ != "abort":
            o = off
        if typ == "write":
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (1, nd, o + l, dur, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (1, nd, o + l, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (2, nd, off, dur, o + l, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (1, N, o + l, dur, lost, tdn, t)))
        elif typ == "checkpoint" or typ == "commit":
            ns = 1 if typ == "checkpoint" else 3
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (ns, nd, o, o, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (ns, nd, o, o, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    nst = 2 if ns == 1 else 3
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (nst, nd, o, o, o, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (ns, N, o, o, lost, tdn, t)))
        elif typ == "abort":
            if st == 1:
                if nd == N:
                    res.append((C_ABORT, (4, nd, off, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N:
                    res.append((C_LATE, (4, nd, off, dur, lost, tdn, tact)))
                res.append((C_MISS, (4, N, off, dur, lost, tdn, tact)))
        elif typ == "recover":
            if st == 2:
                if o == dur:
                    res.append((0.0, (1, N, o, o, lost, tdn, t)))
                elif dur < o <= lost:
                    res.append((C_MISS, (1, N, o, o, lost, tdn, t)))
                elif o > lost:
                    res.append((C_MISS + C_GAP, (1, N, o, o, lost, tdn, t)))
            else:
                if dur <= o <= off:
                    res.append((C_RECACT, (1, N, o, o, lost, tdn, t)))
        return res

    def force(ss, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        if o is None:
            o = off
        if typ == "open":
            return (1, N, 0, 0, 0, 0, t)
        if typ == "write":
            return (1, N, o + l, dur, lost, tdn, tact)
        if typ == "checkpoint":
            return (1, N, o, o, lost, tdn, tact)
        if typ == "commit":
            return (3, N, o, o, lost, tdn, tact)
        if typ == "abort":
            return (4, nd, off, dur, lost, tdn, tact)
        if typ == "recover":
            return (1, N, o, o, lost, tdn, t)
        return ss

    look_cache = {}

    def lc(q, k):
        key = q * (E + 1) + k
        v = look_cache.get(key)
        if v is None:
            v = look_cost(q, k) + cont_cost(q, k)
            hs = dup_hint[k]
            if hs is not None and q not in hs:
                v += C_DUPHINT
            look_cache[key] = v
        return v

    def event_opts(h, k, exact=False):
        cost, ss, pend, chain, om = h
        e = evs[k]
        sid = e["sid"]
        typ = e["type"]
        N = e["node"]
        out = []
        anon = sid is None
        if not anon:
            q0 = sidx.get(sid)
            cands = [q0] if q0 is not None else []
        else:
            cands = range(S)
        for q in cands:
            s = ss[q]
            st = s[0]
            if typ != "open":
                if st == 0 or st >= 3:
                    continue
                if anon and st == 1 and s[1] != N and typ != "recover":
                    continue
            elif st != 0:
                continue
            for c, ns in sess_opts(s, q, k):
                if anon and typ != "open":
                    c += lc(q, k)
                if exact and c > 0.6:
                    continue
                out.append((c, ss[:q] + (ns,) + ss[q + 1:], q))
        if exact:
            return out
        dc = dupc[k]
        if dc:
            for j in dc:
                js = evs[j]["sid"]
                if js is not None:
                    q = sidx.get(js)
                else:
                    q = om.get(j) if om else None
                if q is None or q < 0:
                    continue
                if not anon and sidx.get(sid) != q:
                    continue
                out.append((C_DUP, ss, q))
        if not out:
            if not anon and sid in sidx:
                q = sidx[sid]
                out.append((C_FORCE, ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
            elif anon:
                o = e["off"] or 0
                best = []
                for q in range(S):
                    s = ss[q]
                    if s[0] == 0:
                        continue
                    sc = (0 if s[1] == N else 1, 0 if s[0] in (1, 2) else 1, abs(s[2] - o))
                    best.append((sc, q))
                best.sort()
                for sc, q in best[:2]:
                    out.append((C_FORCE + sc[0] + sc[1], ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
        if not out:
            out.append((C_FORCE * 2, ss, 0 if S else -1))
        return out

    def apply_opt(h, k, c, nss, q, remove_pending):
        cost, ss, pend, chain, om = h
        if remove_pending:
            pend = tuple(p for p in pend if p != k)
        if evs[k]["sid"] is None:
            chain = (k, q, chain)
            if k in is_orig:
                om = dict(om) if om else {}
                om[k] = q
        return (cost + c, nss, pend, chain, om)

    def flush(h, depth=0):
        pend = h[2]
        if not pend or depth > 6:
            return [h]
        for k in pend:
            opts = event_opts(h, k, True)
            if opts:
                res = []
                for c, nss, q in opts[:3]:
                    res.extend(flush(apply_opt(h, k, c, nss, q, True), depth + 1))
                return res
        return [h]

    def expire(h, tnow, final=False):
        hs = [h]
        while True:
            nhs = []
            changed = False
            for x in hs:
                old = None
                for k in x[2]:
                    if final or tnow - evs[k]["t"] > J:
                        old = k
                        break
                if old is None:
                    nhs.append(x)
                    continue
                changed = True
                for c, nss, q in event_opts(x, old):
                    nhs.append(apply_opt(x, old, c, nss, q, True))
            hs = nhs
            if not changed:
                return hs
            if len(hs) > 40:
                hs.sort(key=lambda z: z[0])
                hs = hs[:40]

    def crash(h, k):
        cost, ss, pend, chain, om = h
        e = evs[k]
        N = e["node"]
        t = e["t"]
        aff = []
        recent = []
        for q in range(S):
            s = ss[q]
            if s[0] == 1 and s[1] == N:
                aff.append(q)
                if t - s[6] <= J and s[6] > 0:
                    recent.append(q)

        def down(sset, qs):
            l = list(sset)
            for q in qs:
                s = l[q]
                l[q] = (2, s[1], s[3], s[3], s[2], t, s[6])
            return tuple(l)

        res = [(cost, down(ss, aff), pend, chain, om)]
        if recent:
            rest = [q for q in aff if q not in recent]
            res.append((cost + C_LATE, down(ss, rest), pend, chain, om))
        return res

    K = 48 if E * max(S, 4) <= 4000 else 32
    if E * S > 8000:
        K = 24
    beam = [(0.0, tuple((0, "", 0, 0, 0, 0, 0) for _ in range(S)), (), None, None)]
    budget = 0.68
    for k in range(E):
        e = evs[k]
        el = time.process_time() - t0
        frac = (k + 1) / max(E, 1)
        if el > budget * frac * 1.05 and K > 4:
            K = max(4, int(K * 0.8))
        elif el < budget * frac * 0.6 and K < 96:
            K += 1
        if el > 1.0:
            K = 1
        cand = []
        tnow = e["t"]
        for h in beam:
            for x in expire(h, tnow):
                if e["type"] == "crash":
                    cand.extend(crash(x, k))
                    continue
                if e["type"] not in SESSION_TYPES and e["type"] != "open":
                    cand.append(x)
                    continue
                for c, nss, q in event_opts(x, k):
                    cand.extend(flush(apply_opt(x, k, c, nss, q, False)))
                if e["type"] != "open" and len(x[2]) < MAXPEND and K > 4:
                    cand.append((x[0] + C_DEFER, x[1], x[2] + (k,), x[3], x[4]))
        if not cand:
            continue
        cand.sort(key=lambda z: z[0])
        seen = set()
        nb = []
        for z in cand:
            key = (z[1], z[2])
            if key in seen:
                continue
            seen.add(key)
            nb.append(z)
            if len(nb) >= K:
                break
        beam = nb
    finals = []
    for h in beam:
        finals.extend(expire(h, 0, True))
    finals.sort(key=lambda z: z[0])
    best = finals[0] if finals else beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        kk, q, ch = ch
        assign[kk] = q
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_a = {}
    for k, e in enumerate(evs):
        if e["sid"] is None and e["type"] != "crash":
            q = assign.get(k)
            if q is None or q < 0 or q >= S:
                q = 0
            if S:
                out_a[str(e["i"])] = sids[q]

    # per-session event times for the silence (missing abort) test
    times = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["type"] == "crash":
            continue
        if e["sid"] is not None:
            q = sidx.get(e["sid"])
        else:
            q = assign.get(k)
        if q is not None and 0 <= q < S:
            times[q].append(e["t"])
    T_end = evs[-1]["t"] if evs else 0
    T_start = evs[0]["t"] if evs else 0
    span = max(1, T_end - T_start)

    sessions = {}
    for q, s in enumerate(sids):
        st = best[1][q]
        status = names.get(st[0], "active")
        if st[0] == 1:
            tl = sorted(times[q])
            if len(tl) >= 4:
                mg = (tl[-1] - tl[0]) / float(len(tl) - 1)
                silence = T_end - tl[-1]
                if mg > 0 and silence > 6.0 * mg and silence > 0.25 * span:
                    status = "aborted"
        sessions[s] = {"status": status, "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": sessions}
    return state

import time


def _oc(off, cur):
    if off == cur:
        return 0.0
    if off > cur:
        return 2.0
    return 2.5


def _trans(k, ty, en, off, ln):
    cur, dur, node, st = k
    if st == 'A':
        if en == node:
            if ty == 'write':
                if off is None or ln is None:
                    return [((cur, dur, node, 'A'), 1.0)]
                return [((max(cur, off + ln), dur, node, 'A'), _oc(off, cur))]
            if ty == 'checkpoint':
                if off is None:
                    return [((cur, cur, node, 'A'), 0.5)]
                return [((max(cur, off), max(dur, off), node, 'A'), _oc(off, cur))]
            if ty == 'commit':
                o = cur if off is None else off
                return [((o, o, node, 'C'), _oc(o, cur))]
            if ty == 'abort':
                return [((cur, dur, node, 'X'), 0.5)]
        if ty == 'recover':
            o = dur if off is None else off
            return [((o, o, en, 'A'), 3.0 + (0.0 if o == dur else 1.5))]
        return []
    if st == 'D':
        if ty == 'recover':
            o = dur if off is None else off
            c = 0.0 if o == dur else (1.5 if o > dur else 3.0)
            return [((o, o, en, 'A'), c)]
        if ty in ('write', 'checkpoint', 'commit', 'abort'):
            r = _trans((dur, dur, en, 'A'), ty, en, off, ln)
            return [(k2, c + 3.0) for (k2, c) in r]
        return []
    if en != node:
        return []
    if st == 'C' and ty == 'commit' and (off is None or off == cur):
        return [(k, 1.5)]
    if st == 'X' and ty == 'abort':
        return [(k, 1.5)]
    if ty == 'write' and off is not None and ln is not None and off + ln <= cur:
        return [(k, 2.5)]
    if ty == 'checkpoint' and off is not None and off <= cur:
        return [(k, 2.5)]
    return []


def _put(d, k, sc, bk):
    o = d.get(k)
    if o is None or sc > o[0]:
        d[k] = (sc, bk)


def reconstruct(state, params):
    t0 = time.perf_counter()
    inp = state["input"]
    evs = sorted(inp.get("events", []), key=lambda e: (e.get("t", 0), e.get("i", 0)))
    n = len(evs)
    sessions = []
    open_pos = {}
    for p, e in enumerate(evs):
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in open_pos:
            open_pos[e["sid"]] = p
            sessions.append(e["sid"])
    for p, e in enumerate(evs):
        s = e.get("sid")
        if s is not None and s not in open_pos:
            open_pos[s] = p
            sessions.append(s)
    anon = [p for p in range(n) if evs[p].get("type") != "crash" and evs[p].get("sid") is None]
    anon_set = set(anon)

    rel = {}
    start_state = {}
    for s in sessions:
        op = open_pos[s]
        e0 = evs[op]
        if e0.get("type") == "open":
            start_state[s] = (0, 0, e0.get("node"), 'A')
            first = op + 1
        else:
            o = e0.get("off") or 0
            start_state[s] = (o, o, e0.get("node"), 'A')
            first = op
        lst = []
        for p in range(first, n):
            e = evs[p]
            ty = e.get("type")
            if ty == "crash":
                lst.append(p)
            elif ty == "open":
                continue
            elif e.get("sid") is None or e.get("sid") == s:
                lst.append(p)
        rel[s] = lst

    K = 6
    RL = 40.0
    R = 5.0
    CR_IGN = 3.5

    def dp(s, rewfn):
        states = {start_state[s]: (0.0, None)}
        for p in rel[s]:
            e = evs[p]
            ty = e["type"]
            if ty == "crash":
                nd = e.get("node")
                new = {}
                for k, v in states.items():
                    if k[3] == 'A' and k[2] == nd:
                        _put(new, (k[1], k[1], k[2], 'D'), v[0], v[1])
                        _put(new, k, v[0] - CR_IGN, v[1])
                    else:
                        _put(new, k, v[0], v[1])
                states = new
            else:
                if e.get("sid") is not None:
                    r = RL
                else:
                    r = rewfn(p)
                    if r is None:
                        continue
                en = e.get("node")
                off = e.get("off")
                ln = e.get("len")
                adds = []
                for k, v in states.items():
                    st = k[3]
                    if st == 'A':
                        if k[2] != en and ty != 'recover':
                            continue
                    elif st != 'D':
                        if k[2] != en:
                            continue
                    for k2, c in _trans(k, ty, en, off, ln):
                        adds.append((k2, v[0] + r - c, (p, c, v[1])))
                for k2, sc, bk in adds:
                    _put(states, k2, sc, bk)
            if len(states) > K:
                items = sorted(states.items(), key=lambda kv: -kv[1][0])[:K]
                states = dict(items)
        bestk = None
        bestv = None
        for k, v in states.items():
            if bestv is None or v[0] > bestv[0]:
                bestk, bestv = k, v
        path = []
        bk = bestv[1] if bestv else None
        while bk is not None:
            path.append((bk[0], bk[1]))
            bk = bk[2]
        path.reverse()
        return bestk, path

    price = [0.0] * n
    claims = {}
    it = 0
    iter_time = 0.0
    while True:
        ts = time.perf_counter()
        claims = {p: [] for p in anon}
        rewfn = lambda p: R - price[p]
        for s in sessions:
            _, path = dp(s, rewfn)
            for p, c in path:
                if p in anon_set:
                    claims[p].append((c, s))
        iter_time = max(iter_time, time.perf_counter() - ts)
        bad = 0
        for p in anon:
            if len(claims[p]) != 1:
                bad += 1
        it += 1
        if bad == 0:
            break
        if time.perf_counter() - t0 + 4.0 * iter_time > 0.75 or it >= 15:
            break
        step = 1.5 / (1.0 + 0.4 * it)
        for p in anon:
            c = len(claims[p])
            if c > 1:
                price[p] = min(4 * R, price[p] + step * (c - 1))
            elif c == 0:
                price[p] = max(-3.0, price[p] - 0.6 * step)

    owner = {}
    for p in anon:
        cl = claims.get(p, [])
        if cl:
            cl.sort(key=lambda x: (x[0], sessions.index(x[1])))
            owner[p] = cl[0][1]

    unclaimed = [p for p in anon if p not in owner]
    RL2 = 20.0
    if unclaimed and time.perf_counter() - t0 + 2.5 * iter_time < 0.85:
        claims2 = {p: [] for p in unclaimed}
        for s in sessions:
            def rf(p, s=s):
                o = owner.get(p)
                if o is None:
                    return R
                if o == s:
                    return RL2
                return None
            _, path = dp(s, rf)
            for p, c in path:
                if p in claims2:
                    claims2[p].append((c, s))
        for p in unclaimed:
            if claims2[p]:
                claims2[p].sort(key=lambda x: (x[0], sessions.index(x[1])))
                owner[p] = claims2[p][0][1]

    # fallback: nearest event on same node with a known session
    known = {}
    for p in range(n):
        e = evs[p]
        if e.get("sid") is not None:
            known[p] = e["sid"]
        elif p in owner:
            known[p] = owner[p]
    for p in anon:
        if p in owner:
            continue
        nd = evs[p].get("node")
        best = None
        for d in range(1, n):
            for q in (p - d, p + d):
                if 0 <= q < n and q in known and evs[q].get("node") == nd:
                    best = known[q]
                    break
            if best is not None:
                break
        if best is None:
            best = sessions[0] if sessions else ""
        owner[p] = best

    smap = {'A': 'active', 'D': 'down', 'C': 'committed', 'X': 'aborted'}
    sess_out = {}
    for s in sessions:
        def rf(p, s=s):
            return RL2 if owner.get(p) == s else None
        k, _ = dp(s, rf)
        if k is None:
            sess_out[s] = {"status": "active", "durable": 0}
        else:
            sess_out[s] = {"status": smap.get(k[3], "active"), "durable": int(k[1])}

    assignments = {}
    for p in anon:
        assignments[str(evs[p].get("i"))] = owner[p]
    state["output"] = {"assignments": assignments, "sessions": sess_out}
    return state

import time
import bisect

SESSION_TYPES = ("write", "checkpoint", "commit", "abort", "recover")


def _gi(x):
    try:
        return int(x) if x is not None else None
    except Exception:
        return None


def prepare(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    evs = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        evs.append({
            "i": e.get("i", k), "t": _gi(e.get("t")) or 0, "node": str(e.get("node")),
            "type": str(e.get("type") or ""), "off": _gi(e.get("off")), "len": _gi(e.get("len")),
            "sid": e.get("sid"),
        })
    evs.sort(key=lambda e: (e["t"], e["i"] if isinstance(e["i"], int) else 0))
    sids = []
    seen = set()
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in seen:
            seen.add(e["sid"])
            sids.append(e["sid"])
    for e in evs:
        if e["sid"] is not None and e["sid"] not in seen and e["type"] != "crash":
            seen.add(e["sid"])
            sids.append(e["sid"])
    gaps = sorted(g for g in (evs[k + 1]["t"] - evs[k]["t"] for k in range(len(evs) - 1)) if g >= 0)
    med = gaps[len(gaps) // 2] if gaps else 1
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])
    obs = 0
    bys = {}
    for e in evs:
        if e["sid"] is not None and e["type"] == "write" and e["off"] is not None and e["len"] is not None:
            bys.setdefault(e["sid"], []).append(e)
    for s, lst in bys.items():
        for a in range(len(lst)):
            A = lst[a]
            for b in range(a + 1, min(len(lst), a + 12)):
                B = lst[b]
                if B["node"] == A["node"] and B["off"] + B["len"] <= A["off"] and B["t"] > A["t"]:
                    ct = crash_t.get(A["node"], [])
                    p = bisect.bisect_left(ct, A["t"])
                    if p < len(ct) and ct[p] <= B["t"]:
                        continue
                    obs = max(obs, B["t"] - A["t"])
    J = max(int(obs * 1.5) + 1, 4 * med, 2)
    state["prep"] = {"events": evs, "sids": sids, "J": J}
    return state


def beam_search(state, params):
    t0 = time.process_time()
    prep = state["prep"]
    evs = prep["events"]
    sids = prep["sids"]
    J = prep["J"]
    S = len(sids)
    sidx = {s: k for k, s in enumerate(sids)}
    E = len(evs)
    C_GAP, C_MISS, C_DUP, C_DEFER, C_LATE = 2.0, 2.0, 1.0, 0.4, 1.0
    C_RECACT, C_FORCE, C_ABORT, C_LOOK = 3.0, 15.0, 0.1, 1.5
    C_TERM, C_DUPHINT = 6.0, 0.6
    MAXPEND = 3

    sigmap = {}
    dupc = [None] * E
    is_orig = set()
    for k, e in enumerate(evs):
        if e["type"] in SESSION_TYPES:
            sig = (e["node"], e["type"], e["off"], e["len"])
            prev = sigmap.get(sig)
            if prev:
                dupc[k] = list(prev[-4:])
                for j in prev[-4:]:
                    if evs[j]["sid"] is None:
                        is_orig.add(j)
            sigmap.setdefault(sig, []).append(k)
    dup_hint = [None] * E
    for sig, lst in sigmap.items():
        for a in range(len(lst)):
            ka = lst[a]
            if evs[ka]["sid"] is not None:
                continue
            hs = set()
            for b in range(a + 1, min(len(lst), a + 4)):
                sb = evs[lst[b]]["sid"]
                if sb is not None and sb in sidx:
                    hs.add(sidx[sb])
            if hs:
                dup_hint[ka] = hs

    lab_t = [[] for _ in range(S)]
    lab_e = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["sid"] is not None and e["sid"] in sidx and e["type"] in SESSION_TYPES:
            q = sidx[e["sid"]]
            lab_t[q].append(e["t"])
            lab_e[q].append(k)
    crash_t = {}
    for e in evs:
        if e["type"] == "crash":
            crash_t.setdefault(e["node"], []).append(e["t"])

    def crashed_between(node, ta, tb):
        ct = crash_t.get(node)
        if not ct:
            return False
        c = bisect.bisect_left(ct, ta)
        return c < len(ct) and ct[c] <= tb

    def look_cost(q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        t = e["t"]
        lt = lab_t[q]
        le = lab_e[q]
        p = bisect.bisect_right(lt, t + J)
        f = None
        while p < len(lt):
            idx = le[p]
            if dupc[idx]:
                p += 1
                continue
            f = evs[idx]
            break
        if f is None:
            return 0.0
        if typ == "commit" or typ == "abort":
            return C_TERM
        if crashed_between(N, t - J, f["t"]):
            return 0.0
        if f["type"] == "recover":
            return C_LOOK
        if f["node"] != N:
            return C_LOOK
        if f["type"] in ("write", "checkpoint", "commit") and f["off"] is not None:
            o = e["off"] or 0
            newoff = o + (e["len"] or 0) if typ == "write" else o
            if f["off"] < newoff:
                return C_LOOK
        return 0.0

    def sess_opts(ss, q, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        res = []
        if typ == "open":
            if st == 0:
                res.append((0.0, (1, N, 0, 0, 0, 0, t)))
            return res
        if st == 0 or st >= 3:
            return res
        if o is None and typ != "abort":
            o = off
        if typ == "write":
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (1, nd, o + l, dur, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (1, nd, o + l, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (2, nd, off, dur, o + l, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (1, N, o + l, dur, lost, tdn, t)))
        elif typ == "checkpoint" or typ == "commit":
            ns = 1 if typ == "checkpoint" else 3
            if st == 1:
                if nd == N:
                    if o == off:
                        res.append((0.0, (ns, nd, o, o, lost, tdn, tact)))
                    elif o > off:
                        res.append((C_GAP, (ns, nd, o, o, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N and o >= lost:
                    nst = 2 if ns == 1 else 3
                    res.append((C_LATE + (C_GAP if o > lost else 0.0), (nst, nd, o, o, o, tdn, tact)))
                if o >= dur:
                    res.append((C_MISS + (C_GAP if o > dur else 0.0), (ns, N, o, o, lost, tdn, t)))
        elif typ == "abort":
            if st == 1:
                if nd == N:
                    res.append((C_ABORT, (4, nd, off, dur, lost, tdn, tact)))
            else:
                if t - tdn <= J and nd == N:
                    res.append((C_LATE, (4, nd, off, dur, lost, tdn, tact)))
                res.append((C_MISS, (4, N, off, dur, lost, tdn, tact)))
        elif typ == "recover":
            if st == 2:
                if o == dur:
                    res.append((0.0, (1, N, o, o, lost, tdn, t)))
                elif dur < o <= lost:
                    res.append((C_MISS, (1, N, o, o, lost, tdn, t)))
                elif o > lost:
                    res.append((C_MISS + C_GAP, (1, N, o, o, lost, tdn, t)))
            else:
                if dur <= o <= off:
                    res.append((C_RECACT, (1, N, o, o, lost, tdn, t)))
        return res

    def force(ss, k):
        e = evs[k]
        typ = e["type"]
        N = e["node"]
        o = e["off"]
        l = e["len"] or 0
        t = e["t"]
        st, nd, off, dur, lost, tdn, tact = ss
        if o is None:
            o = off
        if typ == "open":
            return (1, N, 0, 0, 0, 0, t)
        if typ == "write":
            return (1, N, o + l, dur, lost, tdn, tact)
        if typ == "checkpoint":
            return (1, N, o, o, lost, tdn, tact)
        if typ == "commit":
            return (3, N, o, o, lost, tdn, tact)
        if typ == "abort":
            return (4, nd, off, dur, lost, tdn, tact)
        if typ == "recover":
            return (1, N, o, o, lost, tdn, t)
        return ss

    look_cache = {}

    def lc(q, k):
        key = q * (E + 1) + k
        v = look_cache.get(key)
        if v is None:
            v = look_cost(q, k)
            hs = dup_hint[k]
            if hs is not None and q not in hs:
                v += C_DUPHINT
            look_cache[key] = v
        return v

    def event_opts(h, k, exact=False):
        cost, ss, pend, chain, om = h
        e = evs[k]
        sid = e["sid"]
        typ = e["type"]
        N = e["node"]
        out = []
        anon = sid is None
        if not anon:
            q0 = sidx.get(sid)
            cands = [q0] if q0 is not None else []
        else:
            cands = range(S)
        for q in cands:
            s = ss[q]
            st = s[0]
            if typ != "open":
                if st == 0 or st >= 3:
                    continue
                if anon and st == 1 and s[1] != N and typ != "recover":
                    continue
            elif st != 0:
                continue
            for c, ns in sess_opts(s, q, k):
                if anon and typ != "open":
                    c += lc(q, k)
                if exact and c > 0.5:
                    continue
                out.append((c, ss[:q] + (ns,) + ss[q + 1:], q))
        if exact:
            return out
        dc = dupc[k]
        if dc:
            for j in dc:
                js = evs[j]["sid"]
                if js is not None:
                    q = sidx.get(js)
                else:
                    q = om.get(j) if om else None
                if q is None or q < 0:
                    continue
                if not anon and sidx.get(sid) != q:
                    continue
                out.append((C_DUP, ss, q))
        if not out:
            if not anon and sid in sidx:
                q = sidx[sid]
                out.append((C_FORCE, ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
            elif anon:
                o = e["off"] or 0
                best = []
                for q in range(S):
                    s = ss[q]
                    if s[0] == 0:
                        continue
                    sc = (0 if s[1] == N else 1, 0 if s[0] in (1, 2) else 1, abs(s[2] - o))
                    best.append((sc, q))
                best.sort()
                for sc, q in best[:2]:
                    out.append((C_FORCE + sc[0] + sc[1], ss[:q] + (force(ss[q], k),) + ss[q + 1:], q))
        if not out:
            out.append((C_FORCE * 2, ss, 0 if S else -1))
        return out

    def apply_opt(h, k, c, nss, q, remove_pending):
        cost, ss, pend, chain, om = h
        if remove_pending:
            pend = tuple(p for p in pend if p != k)
        if evs[k]["sid"] is None:
            chain = (k, q, chain)
            if k in is_orig:
                om = dict(om) if om else {}
                om[k] = q
        return (cost + c, nss, pend, chain, om)

    def flush(h, depth=0):
        pend = h[2]
        if not pend or depth > 6:
            return [h]
        for k in pend:
            opts = event_opts(h, k, True)
            if opts:
                res = []
                for c, nss, q in opts[:3]:
                    res.extend(flush(apply_opt(h, k, c, nss, q, True), depth + 1))
                return res
        return [h]

    def expire_one(hs, pick):
        # resolve one chosen pending event per hypothesis, repeat until none chosen
        while True:
            nhs = []
            changed = False
            for x in hs:
                old = pick(x)
                if old is None:
                    nhs.append(x)
                    continue
                changed = True
                for c, nss, q in event_opts(x, old):
                    nhs.append(apply_opt(x, old, c, nss, q, True))
            hs = nhs
            if not changed:
                return hs
            if len(hs) > 40:
                hs.sort(key=lambda z: z[0])
                hs = hs[:40]

    def expire(h, tnow, final=False):
        def pick(x):
            for k in x[2]:
                if final or tnow - evs[k]["t"] > J:
                    return k
            return None
        return expire_one([h], pick)

    def resolve_origs(h, k):
        # if the possible originals of duplicate k are still pending, resolve them first
        dc = dupc[k]
        if not dc or not h[2]:
            return [h]
        want = set(j for j in dc if evs[j]["sid"] is None)
        if not want:
            return [h]

        def pick(x):
            for p in x[2]:
                if p in want:
                    return p
            return None
        return expire_one([h], pick)

    def crash(h, k):
        cost, ss, pend, chain, om = h
        e = evs[k]
        N = e["node"]
        t = e["t"]
        aff = []
        recent = []
        for q in range(S):
            s = ss[q]
            if s[0] == 1 and s[1] == N:
                aff.append(q)
                if t - s[6] <= J and s[6] > 0:
                    recent.append(q)

        def down(sset, qs):
            l = list(sset)
            for q in qs:
                s = l[q]
                l[q] = (2, s[1], s[3], s[3], s[2], t, s[6])
            return tuple(l)

        res = [(cost, down(ss, aff), pend, chain, om)]
        if recent:
            rest = [q for q in aff if q not in recent]
            res.append((cost + C_LATE, down(ss, rest), pend, chain, om))
        return res

    K = 64 if E * max(S, 4) <= 4000 else 40
    if E * S > 8000:
        K = 28
    beam = [(0.0, tuple((0, "", 0, 0, 0, 0, 0) for _ in range(S)), (), None, None)]
    budget = 0.8
    for k in range(E):
        e = evs[k]
        el = time.process_time() - t0
        frac = (k + 1) / max(E, 1)
        if el > budget * frac * 1.05 and K > 4:
            K = max(4, int(K * 0.8))
        elif el < budget * frac * 0.6 and K < 128:
            K += 1
        if el > 1.05:
            K = 1
        cand = []
        tnow = e["t"]
        for h in beam:
            for x0 in expire(h, tnow):
                if e["type"] == "crash":
                    cand.extend(crash(x0, k))
                    continue
                if e["type"] not in SESSION_TYPES and e["type"] != "open":
                    cand.append(x0)
                    continue
                xs = resolve_origs(x0, k) if dupc[k] else [x0]
                for x in xs:
                    for c, nss, q in event_opts(x, k):
                        cand.extend(flush(apply_opt(x, k, c, nss, q, False)))
                if e["type"] != "open" and len(x0[2]) < MAXPEND and K > 4:
                    cand.append((x0[0] + C_DEFER, x0[1], x0[2] + (k,), x0[3], x0[4]))
        if not cand:
            continue
        cand.sort(key=lambda z: z[0])
        seen = set()
        nb = []
        for z in cand:
            key = (z[1], z[2])
            if key in seen:
                continue
            seen.add(key)
            nb.append(z)
            if len(nb) >= K:
                break
        beam = nb
    finals = []
    for h in beam:
        finals.extend(expire(h, 0, True))
    finals.sort(key=lambda z: z[0])
    best = finals[0] if finals else beam[0]
    assign = {}
    ch = best[3]
    while ch is not None:
        kk, q, ch = ch
        assign[kk] = q
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    out_a = {}
    sess_times = [[] for _ in range(S)]
    for k, e in enumerate(evs):
        if e["type"] == "crash":
            continue
        if e["sid"] is None:
            q = assign.get(k)
            if q is None or q < 0 or q >= S:
                q = 0
            if S:
                out_a[str(e["i"])] = sids[q]
                sess_times[q].append(e["t"])
        else:
            q = sidx.get(e["sid"])
            if q is not None:
                sess_times[q].append(e["t"])

    # silent-session heuristic: a session that is "active" but silent far longer
    # than its own cadence while the log goes on was most likely aborted (abort lost)
    noncrash_t = sorted(e["t"] for e in evs if e["type"] != "crash")
    if noncrash_t:
        T0, T1 = noncrash_t[0], noncrash_t[-1]
    else:
        T0, T1 = 0, 0
    span = max(1, T1 - T0)
    sessions = {}
    for q, s in enumerate(sids):
        st = best[1][q]
        status = names.get(st[0], "active")
        if st[0] == 1 and sess_times[q]:
            ts = sorted(sess_times[q])
            last = ts[-1]
            g = [ts[a + 1] - ts[a] for a in range(len(ts) - 1)]
            g.sort()
            mg = g[len(g) // 2] if g else span / 8.0
            later = len(noncrash_t) - bisect.bisect_right(noncrash_t, last)
            silence = T1 - last
            if later >= 8 and silence > max(6 * max(mg, 1), 0.15 * span, 3 * J):
                status = "aborted"
        sessions[s] = {"status": status, "durable": int(st[3])}
    state["output"] = {"assignments": out_a, "sessions": sessions}
    return state

import bisect
import heapq
import time

GAP = 1.0
BAD = 3.0
MISSREC = 1.0
K = 4
INIT = (0, None, 0, 0, (), -1, None, 0, None, 0)


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    E = sorted(inp.get("events") or [], key=lambda e: (e["t"], e["i"]))
    crashes = [e for e in E if e["type"] == "crash"]
    ckeys = [(c["t"], c["i"]) for c in crashes]
    ncr = len(crashes)

    order = []
    opens = {}
    for e in E:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in opens:
            opens[e["sid"]] = e
            order.append(e["sid"])
    oidx = {s: k for k, s in enumerate(order)}
    tl = {s: [] for s in order}
    anon = []
    for e in E:
        if e["type"] == "crash":
            continue
        s = e.get("sid")
        if s is None:
            anon.append(e)
        elif s in tl:
            tl[s].append(e)

    # ---- jitter scale estimate
    ts = [e["t"] for e in E]
    diffs = sorted(b - a for a, b in zip(ts, ts[1:]) if b > a)
    meddt = diffs[len(diffs) // 2] if diffs else 1
    maxinv = 0
    for s in order:
        lst = [e for e in tl[s] if e["type"] in ("write", "checkpoint", "commit") and e["off"] is not None]
        for x, y in zip(lst, lst[1:]):
            if x["node"] != y["node"] or y["type"] != "write":
                continue
            yend = y["off"] + (y["len"] or 0)
            if yend <= x["off"]:
                kx = (x["t"], x["i"])
                ky = (y["t"], y["i"])
                a = bisect.bisect_left(ckeys, kx)
                b = bisect.bisect_right(ckeys, ky)
                hit = False
                for q in range(a, b):
                    if crashes[q]["node"] == x["node"]:
                        hit = True
                        break
                if not hit:
                    maxinv = max(maxinv, y["t"] - x["t"])
    J = max(3 * meddt, 2 * maxinv, 1)

    def cstep(s, c):
        st, node, cur, dur, gaps, lc, cn, tc, skn, tsk = s
        cnode = c["node"]
        ct = c["t"]
        if skn is not None:
            if ct > tsk + J:
                skn = None
                tsk = 0
            elif cnode == skn:
                return (st, node, cur, dur, gaps, lc, cn, tc, None, 0)
        if st == 1 and node == cnode:
            return (2, node, dur, dur, (), cur, node, ct, None, 0)
        if skn is None and s[8] is not None:
            return (st, node, cur, dur, gaps, lc, cn, tc, None, 0)
        return s

    def step(s, e):
        st, node, cur, dur, gaps, lc, cn, tc, skn, tsk = s
        ty = e["type"]
        en = e["node"]
        off = e["off"]
        et = e["t"]
        if ty == "open":
            if st != 0:
                return s, 5.0
            return (1, en, 0, 0, (), -1, None, 0, None, 0), 0.0
        if st == 0:
            return s, 6.0
        strag = (cn is not None and en == cn and et <= tc + J)
        if ty == "write":
            if off is None:
                off = cur
            end = off + (e["len"] or 0)
            if st == 1:
                if en == node:
                    if off == cur:
                        return (1, node, end, dur, gaps, lc, cn, tc, skn, tsk), 0.0
                    if off > cur:
                        return (1, node, end, dur, gaps + ((cur, off, True),), lc, cn, tc, skn, tsk), GAP
                    for gi in range(len(gaps)):
                        a, b, ch = gaps[gi]
                        if a <= off and end <= b:
                            ng = list(gaps[:gi]) + list(gaps[gi + 1:])
                            rem = []
                            if a < off:
                                rem.append((a, off))
                            if end < b:
                                rem.append((end, b))
                            c = 0.2
                            if rem:
                                ng.append((rem[0][0], rem[0][1], ch))
                                if len(rem) > 1:
                                    ng.append((rem[1][0], rem[1][1], False))
                            elif ch:
                                c -= GAP
                            return (1, node, cur, dur, tuple(ng), lc, cn, tc, skn, tsk), c
                if strag and off <= lc:
                    return (st, node, cur, dur, gaps, max(lc, end), cn, tc, skn, tsk), 0.4
                return s, BAD
            if st == 2:
                if strag and off <= lc:
                    return (st, node, cur, dur, gaps, max(lc, end), cn, tc, skn, tsk), 0.4
                c = MISSREC
                if off == dur:
                    g = ()
                elif off > dur:
                    c += GAP
                    g = ((dur, off, True),)
                else:
                    c += BAD
                    g = ()
                return (1, en, end, dur, g, lc, cn, tc, skn, tsk), c
            if en == node and (end <= cur or off == cur):
                return s, 0.5
            return s, 5.0
        if ty == "checkpoint" or ty == "commit":
            if off is None:
                off = cur
            fin = (ty == "commit")
            nst = 3 if fin else 1
            if st == 1:
                if en != node:
                    if strag and off <= lc:
                        return s, 0.5
                    return s, BAD
                if off == cur:
                    return (nst, node, cur, cur, gaps, lc, cn, tc, skn, tsk), 0.0
                if off > cur:
                    return (nst, node, off, off, gaps + ((cur, off, True),), lc, cn, tc, skn, tsk), GAP
                if off >= dur:
                    if fin:
                        return (3, node, off, off, gaps, lc, cn, tc, skn, tsk), 1.5
                    return (1, node, cur, off, gaps, lc, cn, tc, skn, tsk), 0.4
                if strag and off <= lc:
                    return s, 0.5
                return s, BAD * 0.7
            if st == 2:
                if strag and off >= dur:
                    c = 0.4 if off <= lc else 0.4 + GAP
                    if fin:
                        return (3, node, off, off, (), lc, cn, tc, skn, tsk), c
                    return (2, node, off, off, (), lc, cn, tc, skn, tsk), c
                c = MISSREC + (0.0 if off == dur else (GAP if off > dur else BAD))
                return (nst, en, off, off, (), lc, cn, tc, skn, tsk), c
            if en == node and off <= cur:
                return s, 0.5
            return s, 5.0
        if ty == "abort":
            if st == 1:
                if en == node:
                    return (4, node, cur, dur, gaps, lc, cn, tc, skn, tsk), 0.0
                return s, BAD
            if st == 2:
                if strag:
                    return (4, node, dur, dur, (), lc, cn, tc, skn, tsk), 0.4
                return (4, en, dur, dur, (), lc, cn, tc, skn, tsk), MISSREC
            return s, 5.0
        if ty == "recover":
            if off is None:
                off = dur
            if st == 2:
                c = 0.0 if off == dur else (0.5 if off > dur else BAD)
                return (1, en, off, off, (), lc, cn, tc, None, 0), c
            if st == 1:
                c = 1.5 + (0.0 if off == dur else 1.0)
                return (1, en, off, off, (), lc, cn, tc, node, et), c
            return s, 5.0
        return s, 5.0

    SD = {}

    def rebuild(s):
        evl = tl[s]
        keys = [(e["t"], e["i"]) for e in evl]
        dup = []
        seen = set()
        snaps = [INIT]
        st = INIT
        ci = 0
        for e, k in zip(evl, keys):
            while ci < ncr and ckeys[ci] < k:
                st = cstep(st, crashes[ci])
                ci += 1
            dk = (e["type"], e["node"], e["off"], e["len"])
            d = dk in seen
            seen.add(dk)
            dup.append(d)
            if not d:
                st, _ = step(st, e)
            snaps.append(st)
        fin = st
        while ci < ncr:
            fin = cstep(fin, crashes[ci])
            ci += 1
        SD[s] = (evl, keys, dup, snaps, seen, fin)

    def delta(e, s):
        evl, keys, dup, snaps, seen, fin = SD[s]
        ke = (e["t"], e["i"])
        p = bisect.bisect_left(keys, ke)
        if p == 0:
            return 6.0
        if (e["type"], e["node"], e["off"], e["len"]) in seen:
            return -2.0
        st = snaps[p]
        ci = bisect.bisect_right(ckeys, keys[p - 1])
        while ci < ncr and ckeys[ci] < ke:
            st = cstep(st, crashes[ci])
            ci += 1
        ns, c = step(st, e)
        tie = 0.02 * min((e["t"] - keys[p - 1][0]) / (10.0 * meddt), 1.0)
        if ns is st:
            return c + tie
        n = len(evl)
        hi = min(p + K, n)

        def run(x):
            cost = 0.0
            cj = ci
            for q in range(p, hi):
                k = keys[q]
                while cj < ncr and ckeys[cj] < k:
                    x = cstep(x, crashes[cj])
                    cj += 1
                if not dup[q]:
                    x, cc = step(x, evl[q])
                    cost += cc
            return cost

        return c + run(ns) - run(st) + tie

    for s in order:
        rebuild(s)

    akeys = [(e["t"], e["i"]) for e in anon]
    okey = {s: (opens[s]["t"], opens[s]["i"]) for s in order}
    Dl = []
    assigned = [None] * len(anon)
    ver = [0] * len(anon)
    dupgroups = {}
    heap = []

    def prio(d):
        if not d:
            return 0.0, 0.0
        vals = sorted(d.values())
        if len(vals) == 1:
            return 50.0, vals[0]
        return vals[1] - vals[0], vals[0]

    def best_of(d):
        bs = None
        bv = None
        for s in order:
            if s in d:
                v = d[s]
                if bv is None or v < bv:
                    bv = v
                    bs = s
        return bs

    budget = 0.8
    timed_out = False
    for j, e in enumerate(anon):
        d = {}
        if not timed_out:
            for s in order:
                if okey[s] < akeys[j]:
                    d[s] = delta(e, s)
            if time.process_time() - t0 > budget:
                timed_out = True
        Dl.append(d)
        dupgroups.setdefault((e["type"], e["node"], e["off"], e["len"]), []).append(j)
        m, b = prio(d)
        heapq.heappush(heap, (-m, b, akeys[j], j, 0))

    while heap and not timed_out:
        if time.process_time() - t0 > budget:
            break
        negm, b, _, j, v = heapq.heappop(heap)
        if assigned[j] is not None or v != ver[j]:
            continue
        d = Dl[j]
        if not d:
            assigned[j] = order[0] if order else None
            continue
        s = best_of(d)
        assigned[j] = s
        e = anon[j]
        pos = bisect.bisect_left(SD[s][1], akeys[j])
        tl[s].insert(pos, e)
        rebuild(s)
        keys = SD[s][1]
        pc = bisect.bisect_left(keys, akeys[j])
        lo = keys[max(0, pc - K - 1)]
        hi = keys[min(len(keys) - 1, pc + 1)]
        a = bisect.bisect_right(akeys, lo)
        bnd = bisect.bisect_right(akeys, hi)
        touched = set(range(a, bnd))
        for q in dupgroups.get((e["type"], e["node"], e["off"], e["len"]), []):
            touched.add(q)
        for q in sorted(touched):
            if assigned[q] is None and s in Dl[q]:
                Dl[q][s] = delta(anon[q], s)
                ver[q] += 1
                m, bb = prio(Dl[q])
                heapq.heappush(heap, (-m, bb, akeys[q], q, ver[q]))

    # leftovers (time guard)
    for j, e in enumerate(anon):
        if assigned[j] is None:
            d = Dl[j]
            s = best_of(d) if d else None
            if s is None:
                cands = [x for x in order if okey[x] < akeys[j]]
                s = cands[-1] if cands else (order[0] if order else "s0")
            assigned[j] = s
            if s in tl:
                pos = bisect.bisect_left([(x["t"], x["i"]) for x in tl[s]], akeys[j])
                tl[s].insert(pos, e)

    for s in order:
        rebuild(s)

    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    sessions = {}
    for s in order:
        fin = SD[s][5]
        sessions[s] = {"status": names.get(fin[0], "active"), "durable": int(fin[3])}
    assignments = {}
    for j, e in enumerate(anon):
        assignments[str(e["i"])] = assigned[j]
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state
